// User preferences are server-backed only (/api/preferences + uiPrefs).
// Real browser localStorage zncave-* keys are wiped at boot. An in-memory Storage
// shim remains so ephemeral session caches (drafts, notification toast list,
// draft-session id) do not hit the browser disk. Durable state must go through
// collectUiPrefs / savePreferences or dedicated server APIs (ops products, NHC desk).
try {
  const browserStorage = window.localStorage;
  for (let index = browserStorage.length - 1; index >= 0; index -= 1) {
    const key = browserStorage.key(index);
    if (key?.startsWith("zncave-")) browserStorage.removeItem(key);
  }
} catch { /* browser storage unavailable */ }
/** Session-only keys that must not trigger a server preference save. */
const MEMORY_ONLY_STORAGE_KEYS = new Set([
  "zncave-client-state-updated-at",
  "zncave-draft-session-id",
  "zncave-haz-beta-draft",
  "zncave-nhc-forecast",
  "zncave-nhc-forecasts",
  "zncave-notifications",
  "zncave-active-warnings",
  "zncave-active-watches",
  "zncave-warning-audit-log",
  "zncave-warning-eval-reminders",
  "zncave-spc-ops"
]);
let userPrefsReady = false;
/** Single debounce for all user-pref writes (UI toggles, layer styles). */
const PREFS_SAVE_DEBOUNCE_MS = 400;
let prefsDebounceTimer = 0;

/**
 * Queue a server prefs save. All UI persistence should go through this
 * (or savePreferences({ immediate: true }) for conflict overwrite / critical actions).
 */
function schedulePreferencesSave(delayMs = PREFS_SAVE_DEBOUNCE_MS) {
  if (!userPrefsReady) return;
  if (typeof savePreferences === "function") {
    savePreferences({ delayMs: Math.max(0, Number(delayMs) || PREFS_SAVE_DEBOUNCE_MS) });
  }
}

function scheduleServerPrefSaveFromMemory(key) {
  if (!userPrefsReady) return;
  if (!String(key || "").startsWith("zncave-")) return;
  if (MEMORY_ONLY_STORAGE_KEYS.has(String(key))) return;
  if (String(key).startsWith("zncave-layer-preferences:")) return;
  if (String(key).startsWith("zncave-radar-palettes:")) return;
  schedulePreferencesSave(PREFS_SAVE_DEBOUNCE_MS);
}
const localStorage = (() => {
  const values = new Map();
  return {
    get length() { return values.size; },
    key(index) { return [...values.keys()][index] ?? null; },
    getItem(key) { return values.has(String(key)) ? values.get(String(key)) : null; },
    setItem(key, value) {
      values.set(String(key), String(value));
      scheduleServerPrefSaveFromMemory(key);
    },
    removeItem(key) { values.delete(String(key)); },
    clear() { values.clear(); }
  };
})();

