// rank: 1 major, 2 regional, 3 local, 4 hamlet
// Display is zoom-gated; WarnGen uses the full catalog (placesCatalog) at any zoom.
// Slim map labels (~1–2 MB). Full gazetteer loads in background for WarnGen only.
const MAP_CITIES_GEOJSON_URL = "/data/generated/base/map-cities.geojson";
const CITIES_GEOJSON_URL = "/data/generated/base/cities.geojson";
const CITY_DENSITY_PROFILES = {
  sparse: { minPopulation: 25_000, regionalZoom: 5.5, localZoom: 7, hamletZoom: 9, microZoom: 11 },
  balanced: { minPopulation: 10_000, regionalZoom: 5, localZoom: 6.5, hamletZoom: 8, microZoom: 10 },
  dense: { minPopulation: 5_000, regionalZoom: 4.8, localZoom: 6, hamletZoom: 7, microZoom: 9 },
  "super-dense": { minPopulation: 1_000, regionalZoom: 4.8, localZoom: 5.8, hamletZoom: 6.8, microZoom: 8 },
  "extreme-dense": { minPopulation: 500, regionalZoom: 4.8, localZoom: 5.6, hamletZoom: 6.5, microZoom: 7.5 }
};
let cityDensityMode = "balanced";
let cityTextScale = 100;
let cityLabelsEnabled = true;
let cityLabelsOpacity = 100;

function cityDensityProfile() {
  return CITY_DENSITY_PROFILES[cityDensityMode] || CITY_DENSITY_PROFILES.balanced;
}

function cityTextSizeExpression() {
  const scale = cityTextScale / 100;
  const values = [8.5, 9, 10, 11].map((size) => Number((size * scale).toFixed(2)));
  return ["interpolate", ["linear"], ["zoom"], 3, values[0], 6, values[1], 9, values[2], 12, values[3]];
}
/** Cap long radar windows while still allowing a full 90-minute volume-scan history. */
const RADAR_LOOP_MAX_FRAMES = 24;

function placeFeature(name, state, rank, lng, lat) {
  return {
    type: "Feature",
    properties: {
      name,
      state,
      rank,
      minzoom: rank === 1 ? 3 : rank === 2 ? 5 : rank === 3 ? 6.5 : 8.5
    },
    geometry: { type: "Point", coordinates: [lng, lat] }
  };
}

