let placesCatalog = placeLabelsBootstrap;

// Must match a font folder on the glyphs host exactly (multi-font stacks often 404).
// demotiles "Open Sans Regular" 404s; protomaps hosts Noto Sans Regular reliably.
const placeLabelFont = ["Noto Sans Regular"];
const mapGlyphsUrl = "https://protomaps.github.io/basemaps-assets/fonts/{fontstack}/{range}.pbf";

function buildPlaceLayers() {
  // Labels by rank. Majors/regionals always paint (ops need them).
  const rankEq = (rank) => ["==", ["to-number", ["get", "rank"]], rank];
  const zoomTextSize = cityTextSizeExpression();

  const density = cityDensityProfile();
  return [
    {
      id: "place-labels-major",
      type: "symbol",
      source: "cities",
      minzoom: 3,
      filter: rankEq(1),
      layout: {
        "text-field": ["get", "name"],
        "text-font": placeLabelFont,
        "text-size": zoomTextSize,
        "text-offset": [0, 0.9],
        "text-anchor": "top",
        "text-max-width": 10,
        "text-padding": 2,
        "text-allow-overlap": ["step", ["zoom"], false, 8, true],
        "text-ignore-placement": false,
        "symbol-sort-key": ["to-number", ["get", "rank"]],
        "text-optional": false
      },
      paint: {
        "text-color": "#ffffff",
        "text-halo-color": "#0b0d10",
        "text-halo-width": 1.8,
        "text-opacity": 1
      }
    },
    {
      id: "place-labels-regional",
      type: "symbol",
      source: "cities",
      minzoom: density.regionalZoom,
      filter: rankEq(2),
      layout: {
        "text-field": ["get", "name"],
        "text-font": placeLabelFont,
        "text-size": zoomTextSize,
        "text-offset": [0, 0.85],
        "text-anchor": "top",
        "text-max-width": 10,
        "text-padding": 2,
        "text-allow-overlap": false,
        "text-ignore-placement": false,
        "symbol-sort-key": ["to-number", ["get", "rank"]],
        "text-optional": false
      },
      paint: {
        "text-color": "#f3f5f7",
        "text-halo-color": "#0b0d10",
        "text-halo-width": 1.6,
        "text-opacity": 1
      }
    },
    {
      id: "place-labels-local",
      type: "symbol",
      source: "cities",
      minzoom: density.localZoom,
      filter: rankEq(3),
      layout: {
        "text-field": ["get", "name"],
        "text-font": placeLabelFont,
        "text-size": zoomTextSize,
        "text-offset": [0, 0.8],
        "text-anchor": "top",
        "text-max-width": 9,
        "text-padding": 2,
        "text-allow-overlap": false,
        "text-ignore-placement": false,
        "symbol-sort-key": ["to-number", ["get", "rank"]],
        "text-optional": true
      },
      paint: {
        "text-color": "#eef1f4",
        "text-halo-color": "#0b0d10",
        "text-halo-width": 1.4,
        "text-opacity": 1
      }
    },
    {
      id: "place-labels-hamlet",
      type: "symbol",
      source: "cities",
      // Census towns + GNIS communities (rank 4)
      minzoom: density.hamletZoom,
      filter: ["==", ["to-number", ["get", "rank"]], 4],
      layout: {
        "text-field": ["get", "name"],
        "text-font": placeLabelFont,
        "text-size": zoomTextSize,
        "text-offset": [0, 0.75],
        "text-anchor": "top",
        "text-max-width": 9,
        "text-padding": 2,
        "text-allow-overlap": false,
        "text-ignore-placement": false,
        "symbol-sort-key": ["to-number", ["get", "rank"]],
        "text-optional": true
      },
      paint: {
        "text-color": "#e4e8ec",
        "text-halo-color": "#0b0d10",
        "text-halo-width": 1.25,
        "text-opacity": 0.95
      }
    },
    {
      id: "place-labels-micro",
      type: "symbol",
      source: "cities",
      // GNIS-only hamlets / crossroads (rank 5) — densest layer
      minzoom: density.microZoom,
      filter: [">=", ["to-number", ["get", "rank"]], 5],
      layout: {
        "text-field": ["get", "name"],
        "text-font": placeLabelFont,
        "text-size": zoomTextSize,
        "text-offset": [0, 0.7],
        "text-anchor": "top",
        "text-max-width": 8,
        "text-padding": 2,
        "text-allow-overlap": false,
        "text-ignore-placement": false,
        "symbol-sort-key": ["to-number", ["get", "rank"]],
        "text-optional": true
      },
      paint: {
        "text-color": "#dce1e6",
        "text-halo-color": "#0b0d10",
        "text-halo-width": 1.15,
        "text-opacity": 0.92
      }
    }
  ].reverse();
}

