// Level 2 is no longer operator-selectable. Translate older saved preferences
// and workspaces to the closest supported Level 3 or MRMS product.
function supportedRadarProductId(productId) {
  const replacements = {
    reflectivity: "reflectivitylevel3",
    velocity: "velocitylevel3",
    meshlevel2: "mesh60"
  };
  const candidate = replacements[productId] || productId;
  return radarProductDefinitions[candidate] ? candidate : "reflectivitylevel3";
}

function isMrmsRadarProduct(productId) {
  const def = radarProductDefinitions[productId];
  return Boolean(def && def.national);
}

let radarValueHoverEnabled = false;
let radarValueHoverPopup = null;
let radarHoverMapButton = null;
let baseLayerMode = "gray";
/** Chrome theme for rail / dock / dialogs — server uiPrefs only. */
let uiTheme = "light";

function applyUiTheme(theme, options = {}) {
  uiTheme = theme === "dark" ? "dark" : "light";
  try {
    document.documentElement.setAttribute("data-theme", uiTheme);
    document.documentElement.style.colorScheme = uiTheme;
  } catch {
    /* ignore DOM issues */
  }
  if (controls?.themeSelect) controls.themeSelect.value = uiTheme;
  if (controls?.themeSelectOps) controls.themeSelectOps.value = uiTheme;
  if (options.persist !== false && typeof userPrefsReady !== "undefined" && userPrefsReady) {
    schedulePreferencesSave();
  }
  return uiTheme;
}

function applyBaseLayerMode(targetMap) {
  if (!targetMap?.getStyle?.()) return;
  if (targetMap.getLayer("base-gray")) targetMap.setLayoutProperty("base-gray", "visibility", baseLayerMode === "blank" ? "none" : "visible");
  if (targetMap.getLayer("base-satellite")) targetMap.setLayoutProperty("base-satellite", "visibility", baseLayerMode === "blank" ? "visible" : "none");
  ["place-labels-major", "place-labels-regional", "place-labels-local", "place-labels-hamlet", "place-labels-micro"].forEach((id) => {
    if (targetMap.getLayer(id)) targetMap.setLayoutProperty(id, "visibility", cityLabelsEnabled ? "visible" : "none");
  });
}

function setBaseLayerMode(mode) {
  baseLayerMode = mode === "blank" ? "blank" : "gray";
  activePanelMaps().forEach(applyBaseLayerMode);
  if (controls.baseLayerSelect) controls.baseLayerSelect.value = baseLayerMode;
  if (userPrefsReady) schedulePreferencesSave();
}

let activeMapMovementCount = 0;
let hiveBetaNavigationFrame = 0;
let hiveBetaNavigationFrames = 0;
let hiveBetaNavigationStartedAt = 0;
const hiveBetaHoverQueues = new WeakMap();

function scheduleHiveBetaMapHover(targetMap, key, event, work) {
  if (!hiveBetaMode) return work(event);
  let state = hiveBetaHoverQueues.get(targetMap);
  if (!state) {
    state = { frame: 0, jobs: new Map() };
    hiveBetaHoverQueues.set(targetMap, state);
  }
  state.jobs.set(key, { event, work });
  if (state.frame) return;
  state.frame = window.requestAnimationFrame(() => {
    state.frame = 0;
    const jobs = [...state.jobs.values()];
    state.jobs.clear();
    if (targetMap.isMoving?.() || targetMap.__zncaveRenderSuspended) return;
    jobs.forEach((job) => job.work(job.event));
  });
}

function startHiveBetaNavigationSample() {
  if (!hiveBetaMode || hiveBetaNavigationFrame) return;
  hiveBetaNavigationFrames = 0;
  hiveBetaNavigationStartedAt = performance.now();
  const count = () => {
    hiveBetaNavigationFrames += 1;
    hiveBetaNavigationFrame = window.requestAnimationFrame(count);
  };
  hiveBetaNavigationFrame = window.requestAnimationFrame(count);
}

function finishHiveBetaNavigationSample() {
  if (!hiveBetaNavigationFrame) return;
  window.cancelAnimationFrame(hiveBetaNavigationFrame);
  hiveBetaNavigationFrame = 0;
  const durationMs = Math.max(1, performance.now() - hiveBetaNavigationStartedAt);
  hiveBetaPerformance.navigation = {
    fps: Math.round((hiveBetaNavigationFrames * 1000 / durationMs) * 10) / 10,
    frames: hiveBetaNavigationFrames,
    durationMs: Math.round(durationMs),
    sampledAt: Date.now()
  };
}

function createOpsMap(containerId) {
  const betaRenderFastPath = !["/hive-legacy", "/hive-legacy/"].includes(window.location.pathname);
  const instance = new maplibregl.Map({
    container: containerId,
    style: mapStyle,
    center: defaultView.center,
    zoom: defaultView.zoom,
    maxZoom: 18,
    // Operational point placement should tolerate a few pixels of hand
    // movement without MapLibre interpreting the action as a map drag.
    clickTolerance: 8,
    keyboard: false,
    dragRotate: false,
    pitchWithRotate: false,
    attributionControl: containerId === "map",
    // Beta warning snapshots use the dedicated full-resolution 2D renderer below,
    // so retaining every WebGL frame only wastes GPU bandwidth while navigating.
    preserveDrawingBuffer: containerId === "map" && !betaRenderFastPath,
    fadeDuration: betaRenderFastPath ? 0 : 300,
    renderWorldCopies: !betaRenderFastPath
  });

  if (instance.keyboard) {
    instance.keyboard.disable();
  }
  instance.on("load", () => {
    applyBaseLayerMode(instance);
    void loadRadarStationDots(instance);
  });
  instance.on("mousemove", (event) => scheduleHiveBetaMapHover(instance, "radar", event, (latest) => handleRadarValueHover(instance, latest)));
  instance.on("movestart", () => {
    if (!activeMapMovementCount) startHiveBetaNavigationSample();
    activeMapMovementCount += 1;
    document.body.classList.add("map-is-moving");
  });
  instance.on("moveend", () => {
    activeMapMovementCount = Math.max(0, activeMapMovementCount - 1);
    if (!activeMapMovementCount) {
      document.body.classList.remove("map-is-moving");
      finishHiveBetaNavigationSample();
    }
    scheduleTransportationRefresh();
    scheduleHydrographyRefresh();
  });
  instance.on("click", (event) => handleGfeZoneMapClick(instance, event));
  instance.on("click", "radar-site-dots", (event) => handleRadarStationClick(instance, event));
  instance.on("mouseenter", "radar-site-dots", () => { instance.getCanvas().style.cursor = "pointer"; });
  instance.on("mouseleave", "radar-site-dots", () => { instance.getCanvas().style.cursor = ""; });

  instance.addControl(
    new maplibregl.NavigationControl({
      showCompass: false,
      visualizePitch: false
    }),
    "top-left"
  );

  if (containerId === "map") {
    instance.addControl({
      onAdd() {
        const container = document.createElement("div");
        container.className = "maplibregl-ctrl maplibregl-ctrl-group cwa-map-control";
        const button = document.createElement("button");
        button.type = "button";
        button.className = "cwa-map-button";
        button.textContent = "CWA";
        button.title = "Fit map to the active County Warning Area";
        button.setAttribute("aria-label", "Fit map to active County Warning Area");
        button.addEventListener("click", () => {
          fitMapToActiveCwa();
          const definition = getActiveWfoView();
          showBanner(`Centered on ${definition.label} (${activeWfo}).`);
        });
        container.append(button);
        const inspectButton = document.createElement("button");
        inspectButton.type = "button";
        inspectButton.className = "radar-hover-map-button";
        inspectButton.textContent = "⌕";
        inspectButton.title = "Toggle radar value inspection (I)";
        inspectButton.setAttribute("aria-label", "Toggle radar values on hover (I)");
        inspectButton.setAttribute("aria-pressed", String(radarValueHoverEnabled));
        inspectButton.classList.toggle("is-active", radarValueHoverEnabled);
        inspectButton.addEventListener("click", () => {
          setRadarValueHoverEnabled(!radarValueHoverEnabled);
          renderLayerControls();
          showBanner(radarValueHoverEnabled ? "Radar value inspection on — hover over precipitation or velocity data." : "Radar value inspection off.");
        });
        container.append(inspectButton);
        radarHoverMapButton = inspectButton;
        this.container = container;
        return container;
      },
      onRemove() {
        radarHoverMapButton = null;
        this.container?.remove();
      }
    }, "top-left");
  }

  return instance;
}

