const panelDock = document.querySelector("#panelDock");
const dedicatedSpcDesk = new URLSearchParams(window.location.search).get("desk") === "spc";
// The former Hive Beta is now the production Hive. Keep the legacy interface
// explicitly addressable so operators can fall back without maintaining a
// second copy of the application.
const hiveLegacyMode = ["/hive-legacy", "/hive-legacy/"].includes(window.location.pathname);
const hiveBetaPreviewRoute = ["/hive-beta", "/hive-beta/"].includes(window.location.pathname);
const hiveBetaMode = !hiveLegacyMode;
const hiveBetaMapPopoutMode = hiveBetaMode && new URLSearchParams(window.location.search).get("mapPopout") === "1";
const hiveBetaNativeFetch = window.fetch.bind(window);
const hiveBetaFetchJobs = new Map();
const hiveBetaPerformance = {
  startedAt: performance.now(),
  timings: [],
  requests: [],
  longTasks: [],
  navigation: { fps: 0, frames: 0, durationMs: 0, sampledAt: 0 },
  cacheStats: { radarHits: 0, radarMisses: 0, modelHits: 0, modelMisses: 0, satelliteHits: 0, satelliteMisses: 0, persistentHits: 0, persistentMisses: 0 },
  mark(name, startedAt, detail = {}) {
    if (!hiveBetaMode) return;
    this.timings.push({ name, durationMs: Math.round((performance.now() - startedAt) * 10) / 10, at: Date.now(), ...detail });
    if (this.timings.length > 200) this.timings.shift();
  },
  snapshot() {
    return {
      uptimeMs: Math.round(performance.now() - this.startedAt),
      timings: [...this.timings], requests: [...this.requests], longTasks: [...this.longTasks],
      memory: performance.memory ? {
        used: performance.memory.usedJSHeapSize,
        total: performance.memory.totalJSHeapSize,
        limit: performance.memory.jsHeapSizeLimit
      } : null,
      caches: { radarProducts: hiveBetaRadarProductJobs?.size || 0, gates: polarGateCache?.size || 0, meshes: polarMeshCache?.size || 0 }
    };
  }
};
window.ZNCaveBetaPerformance = hiveBetaPerformance;
if (hiveBetaMode) {
  if (typeof PerformanceObserver !== "undefined") {
    try {
      const observer = new PerformanceObserver((list) => {
        list.getEntries().forEach((entry) => hiveBetaPerformance.longTasks.push({
          durationMs: Math.round(entry.duration * 10) / 10,
          at: Date.now()
        }));
        if (hiveBetaPerformance.longTasks.length > 100) hiveBetaPerformance.longTasks.splice(0, hiveBetaPerformance.longTasks.length - 100);
      });
      observer.observe({ type: "longtask", buffered: true });
    } catch { /* Long Task API is optional. */ }
  }
  window.fetch = (input, init = {}) => {
    const method = String(init.method || (input instanceof Request ? input.method : "GET")).toUpperCase();
    const rawUrl = input instanceof Request ? input.url : String(input);
    const url = new URL(rawUrl, window.location.href);
    // Abortable requests retain independent ownership; sharing their signal
    // could let one panel cancel another panel's otherwise valid request.
    if (method !== "GET" || url.origin !== window.location.origin || init.signal) {
      return hiveBetaNativeFetch(input, init);
    }
    const key = `${method}|${url.href}|${init.credentials || "same-origin"}`;
    if (!hiveBetaFetchJobs.has(key)) {
      const startedAt = performance.now();
      const job = hiveBetaNativeFetch(input, init)
        .then((response) => {
          hiveBetaPerformance.requests.push({ url: url.pathname, status: response.status, durationMs: Math.round((performance.now() - startedAt) * 10) / 10, at: Date.now() });
          if (hiveBetaPerformance.requests.length > 200) hiveBetaPerformance.requests.shift();
          return response;
        })
        .finally(() => hiveBetaFetchJobs.delete(key));
      hiveBetaFetchJobs.set(key, job);
    }
    return hiveBetaFetchJobs.get(key).then((response) => response.clone());
  };
}

const HIVE_BETA_FRAME_CACHE_NAME = "zncave-hive-beta-frames-v1";
const HIVE_BETA_FRAME_CACHE_MAX_ENTRIES = 96;
let hiveBetaPersistentCacheTrimPending = false;

async function trimHiveBetaPersistentFrameCache(cache) {
  if (hiveBetaPersistentCacheTrimPending) return;
  hiveBetaPersistentCacheTrimPending = true;
  try {
    const keys = await cache.keys();
    const excess = keys.length - HIVE_BETA_FRAME_CACHE_MAX_ENTRIES;
    if (excess > 0) await Promise.all(keys.slice(0, excess).map((key) => cache.delete(key)));
  } catch { /* Cache Storage is best-effort. */ }
  finally { hiveBetaPersistentCacheTrimPending = false; }
}

async function fetchHiveBetaPersistentFrame(url, init = {}) {
  if (!hiveBetaMode || !("caches" in window) || String(init.method || "GET").toUpperCase() !== "GET") {
    return fetch(url, init);
  }
  const request = new Request(url, { credentials: init.credentials || "same-origin" });
  try {
    const cache = await caches.open(HIVE_BETA_FRAME_CACHE_NAME);
    const cached = await cache.match(request);
    if (cached) {
      hiveBetaPerformance.cacheStats.persistentHits += 1;
      return cached;
    }
    hiveBetaPerformance.cacheStats.persistentMisses += 1;
    const response = await fetch(url, init);
    if (response.ok && (response.headers.get("content-type") || "").includes("image")) {
      void cache.put(request, response.clone()).then(() => trimHiveBetaPersistentFrameCache(cache)).catch(() => {});
    }
    return response;
  } catch {
    return fetch(url, init);
  }
}

let hiveBetaDataWorker = null;
let hiveBetaDataWorkerSequence = 0;
const hiveBetaDataWorkerJobs = new Map();
function ensureHiveBetaDataWorker() {
  if (!hiveBetaMode || typeof Worker === "undefined") return null;
  if (hiveBetaDataWorker) return hiveBetaDataWorker;
  hiveBetaDataWorker = new Worker("/hive-beta-worker.js?v=20260814-radar-two-pass");
  hiveBetaDataWorker.addEventListener("message", (event) => {
    const job = hiveBetaDataWorkerJobs.get(event.data?.id);
    if (!job) return;
    hiveBetaDataWorkerJobs.delete(event.data.id);
    if (event.data.ok) job.resolve(event.data.value);
    else job.reject(new Error(event.data.error || "Beta data worker failed"));
  });
  hiveBetaDataWorker.addEventListener("error", (event) => {
    hiveBetaDataWorkerJobs.forEach((job) => job.reject(event.error || new Error("Beta data worker stopped")));
    hiveBetaDataWorkerJobs.clear();
    hiveBetaDataWorker?.terminate();
    hiveBetaDataWorker = null;
  });
  return hiveBetaDataWorker;
}
function hiveBetaLoadJson(url) {
  if (!hiveBetaMode || typeof Worker === "undefined") {
    return fetch(url, { cache: "force-cache" }).then((response) => {
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json();
    });
  }
  ensureHiveBetaDataWorker();
  return hiveBetaWorkerRequest("json", { url });
}

function hiveBetaWorkerRequest(type, payload, transfer = []) {
  if (!ensureHiveBetaDataWorker()) return Promise.reject(new Error("Beta data worker unavailable"));
  const id = ++hiveBetaDataWorkerSequence;
  return new Promise((resolve, reject) => {
    hiveBetaDataWorkerJobs.set(id, { resolve, reject });
    hiveBetaDataWorker.postMessage({ id, type, ...payload }, transfer);
  });
}
