const LAYER_GROUP_STATE_KEY = "zncave-layer-group-state";
const USER_CLIENT_STATE_META_KEY = "zncave-client-state-updated-at";
const USER_CLIENT_STATE_EXCLUDED_KEYS = new Set([USER_CLIENT_STATE_META_KEY, "zncave-draft-session-id"]);
const nativeLocalStorageSetItem = Storage.prototype.setItem;
const nativeLocalStorageRemoveItem = Storage.prototype.removeItem;
let userClientStateSyncReady = false;
let userClientStateSyncTimer = 0;

function userClientStateKeyAllowed(key) {
  return String(key || "").startsWith("zncave-") && !USER_CLIENT_STATE_EXCLUDED_KEYS.has(String(key));
}

function collectUserClientState() {
  const values = {};
  for (let index = 0; index < localStorage.length; index += 1) {
    const key = localStorage.key(index);
    if (userClientStateKeyAllowed(key)) values[key] = localStorage.getItem(key) || "";
  }
  return values;
}

async function pushUserClientState() {
  if (!userClientStateSyncReady || !session.authenticated) return;
  const updatedAt = Math.max(Date.now(), Number(localStorage.getItem(USER_CLIENT_STATE_META_KEY)) || 0);
  nativeLocalStorageSetItem.call(localStorage, USER_CLIENT_STATE_META_KEY, String(updatedAt));
  const response = await fetch("/api/preferences/client-state", {
    method: "PUT",
    credentials: "same-origin",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ values: collectUserClientState(), updatedAt }),
    keepalive: true
  });
  if (response.status === 409) {
    // Another computer saved a newer copy. It will be applied on the next load;
    // never overwrite it with this stale tab.
    return;
  }
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
}

function scheduleUserClientStateSync() {
  if (!userClientStateSyncReady) return;
  window.clearTimeout(userClientStateSyncTimer);
  nativeLocalStorageSetItem.call(localStorage, USER_CLIENT_STATE_META_KEY, String(Date.now()));
  userClientStateSyncTimer = window.setTimeout(() => {
    pushUserClientState().catch((error) => console.warn("User client-state sync failed", error));
  }, 500);
}

Storage.prototype.setItem = function patchedUserStateSetItem(key, value) {
  nativeLocalStorageSetItem.call(this, key, value);
  if (this === localStorage && userClientStateKeyAllowed(key)) scheduleUserClientStateSync();
};

Storage.prototype.removeItem = function patchedUserStateRemoveItem(key) {
  nativeLocalStorageRemoveItem.call(this, key);
  if (this === localStorage && userClientStateKeyAllowed(key)) scheduleUserClientStateSync();
};

/**
 * Legacy client-state bag is no longer used for user preferences.
 * Preferences load/save through /api/preferences (structured document).
 */
async function hydrateUserClientState() {
  userClientStateSyncReady = false;
  return false;
}
