function normalizeLayerGroupState(groups) {
  const next = { ...LAYER_GROUP_DEFAULTS };
  if (groups && typeof groups === "object") {
    Object.keys(next).forEach((key) => {
      if (typeof groups[key] === "boolean") next[key] = groups[key];
    });
  }
  return next;
}

let layerGroupState = normalizeLayerGroupState({});
let layerGroupStateUpdatedAt = 0;

/** True while rebuilding layer <details> so programmatic .open does not re-save prefs. */
let layerGroupUiApplying = false;

/** Pull open/closed from the live DOM before re-renders or server saves. */
function syncLayerGroupStateFromDom() {
  if (!controls?.layerList || layerGroupUiApplying) return;
  controls.layerList.querySelectorAll("details.layer-group[data-layer-group]").forEach((el) => {
    const key = el.dataset.layerGroup;
    if (key) layerGroupState[key] = Boolean(el.open);
  });
  layerGroupState = normalizeLayerGroupState(layerGroupState);
}

function persistLayerGroupState(markUpdated = false) {
  // Session memory only — collapse state is saved with server layerUiState.
  if (markUpdated) layerGroupStateUpdatedAt = Date.now();
  layerGroupState = normalizeLayerGroupState(layerGroupState);
}

/**
 * Apply server (or setup) layer-menu open/closed state.
 * Server is source of truth for user preferences.
 */
function applyLayerUiState(remoteLayerUi, { force = false } = {}) {
  if (!remoteLayerUi?.groups || typeof remoteLayerUi.groups !== "object") {
    return false;
  }
  const remoteAt = Number(remoteLayerUi.updatedAt) || 0;
  if (!force && remoteAt < layerGroupStateUpdatedAt) {
    return false;
  }
  layerGroupState = normalizeLayerGroupState(remoteLayerUi.groups);
  layerGroupStateUpdatedAt = remoteAt || layerGroupStateUpdatedAt || Date.now();
  return true;
}

