  let modelPreloadKey = "";
  const modelFrameRequests = new Map();
  const modelFrameAbortControllers = new Map();
  const MODEL_PRELOAD_CONCURRENCY = hiveBetaMode ? 3 : 2;
  /** Full-domain preload width — higher than before so CONUS plates stay sharper when zoomed a bit. */
  const MODEL_PRELOAD_WIDTH = 4096;
  const overlaySourceId = "ops-model-overlay-source";
  const overlayLayerId = "ops-model-overlay-layer";
  const overlaySecondarySourceId = "ops-model-overlay-secondary-source";
  const overlaySecondaryLayerId = "ops-model-overlay-secondary-layer";
  // Full-US default matches the HRRR CONUS domain used for ops overlays (lon/lat corners
