  const regionBounds = {
    "": [-134.1, 21.1, -60.9, 52.7], "central-us": [-104, 31, -82, 49], northeast: [-82, 37, -66, 48],
    "northern-plains": [-106, 39, -88, 50], "ohio-valley": [-93, 34, -77, 44], southeast: [-92, 24, -74, 38],
    "southern-plains": [-107, 24, -88, 39], west: [-125, 30, -101, 50], tennessee: [-90.5, 34.8, -81.4, 36.8], wyoming: [-111.2, 40.8, -103.8, 45.2]
  };
  opsModelOverlayActive = () => Boolean(overlayToggle?.checked);

