      await decodeModelFrameUrl(decodedBlobUrl);
      if (generation !== modelPreloadGeneration || cacheKey !== modelPreloadKey) { URL.revokeObjectURL(decodedBlobUrl); return; }
      modelFrameState.set(fh, { status: "ready", blobUrl: decodedBlobUrl });
