const applySatLoopDuration = (raw) => {
  const next = [15, 30, 60, 120, 240, 360].includes(Number(raw)) ? Number(raw) : 15;
  satLoopDurationMinutes = next;
  if (controls.satLoopDurationSelect) controls.satLoopDurationSelect.value = String(next);
  if (controls.satTimelineDurationSelect) controls.satTimelineDurationSelect.value = String(next);
  if (NESDIS_LOOP_PRODUCTS.has(activeSatelliteLayer)) {
    void loadSatelliteLoop(activeSatelliteLayer);
  }
  if (hiveBetaMode && activeSatelliteLayer === "native") {
    nativeGoesLoopRequest += 1;
    clearSatelliteLoopState();
    void loadNativeGoesAwsLoop();
  }
  if (userPrefsReady) savePreferences();
};
const applySatAnimationSpeed = (raw) => {
  const next = Math.max(280, Number(raw) || 850);
  satAnimationSpeedMs = next;
  if (controls.satAnimationSpeedSelect) controls.satAnimationSpeedSelect.value = String(next);
  if (controls.satTimelineSpeedSelect) controls.satTimelineSpeedSelect.value = String(next);
  if (satLoopPlaying) setSatelliteLoopPlaying(true);
  if (userPrefsReady) savePreferences();
};
