controls.radarSiteSelect.addEventListener("change", (event) => {
  const selectedSite = normalizeRadarSite(event.target.value, activeWfo);
  // Always pin the active pane (and primary when pane 1) to the chosen site first.
  panelSiteIds[Math.max(0, (activePanelIndex || 1) - 1)] = selectedSite;
  if ((activePanelIndex || 1) === 1 || !dualDisplayEnabled) {
    panelSiteIds[0] = selectedSite;
  }
  syncRadarInput(selectedSite);
  radarLoopSite = selectedSite;

  if (mutualAidModeEnabled) {
    const existingSites = savedMutualAidRadars(activeWfo, mutualAidState.radar);
    const sites = existingSites.includes(selectedSite)
      ? existingSites
      : rememberMutualAidRadars(activeWfo, [selectedSite, ...existingSites].join(", "));
    mutualAidState.radar = sites.join(", ");
    if (controls.mutualAidRadarInput) {
      controls.mutualAidRadarInput.value = mutualAidState.radar;
    }
    ensureWfoDefinition(activeWfo, { radar: mutualAidState.radar });
    saveMutualAidPreference();
  }

  if (userPrefsReady) schedulePreferencesSave();

  // Changing site while MESH is selected should not force BR
  if (isMrmsRadarProduct(activeRadarProductId) || meshProductActive) {
    updateRadarStationSelection();
    return;
  }
  updateRadarStationSelection();
  if (opsRadarSource !== "local") {
    controls.radarSummary.textContent = `${selectedSite} selected. Switch Source to Local / site products to load site radar.`;
    return;
  }
  radarFiles = [];
  controls.radarFileList.innerHTML = "";
  controls.radarSummary.textContent = `${selectedSite} selected for WFO ${activeWfo}. Loading radar in the background...`;
  loadRadarLoop();
});
function setPrimaryRadarProduct(raw, options = {}) {
  if (panelLayoutCount >= 2) {
    panelRadarSources[activePanelIndex - 1] = "local";
    removeIemNationalMosaic(panelMap());
    if (panelMap().__zncaveDataSource === "IEM radar") {
      panelMap().__zncaveDataTime = null;
      panelMap().__zncaveDataSource = "";
      renderPaneDataAges();
    }
  }
  if (opsRadarSource !== "local") {
    setOpsRadarSource("local", { skipLoad: true });
  }
  activeRadarProductId = supportedRadarProductId(raw);
  radarLayerEnabled = true;
  panelRadarEnabled[activePanelIndex - 1] = true;
  if (panelLayoutCount >= 2) {
    if (activePanelIndex === 1) panel1ProductId = activeRadarProductId;
    else if (activePanelIndex === 2) panel2ProductId = activeRadarProductId;
    else if (activePanelIndex === 3) panel3ProductId = activeRadarProductId;
    else panel4ProductId = activeRadarProductId;
  }
  if (controls.radarProductSelect && controls.radarProductSelect.value !== activeRadarProductId) {
    controls.radarProductSelect.value = activeRadarProductId;
  }
  if (
    controls.timelineRadarProductSelect &&
    controls.timelineRadarProductSelect.value !== activeRadarProductId
  ) {
    controls.timelineRadarProductSelect.value = activeRadarProductId;
  }
  const def = getActiveRadarProductDefinition();
  if (isMrmsRadarProduct(activeRadarProductId)) {
    // Kill any in-flight BR load before MESH paints
    meshProductActive = true;
    stopSiteRadarLoop("product → MESH");
    controls.radarSummary.textContent = `Loading MRMS ${def.label}…`;
  } else {
    meshProductActive = false;
    controls.radarSummary.textContent = `Loading ${def.label.toLowerCase()}…`;
  }
  if (!options.skipLoad) {
    loadRadarLoop();
  }
  syncHiveBetaRadarPresets();
}

