if (controls.panelLayoutSelect) {
  let layoutChangeSeq = 0;
  const onLayoutChange = (event) => {
    const raw = event.target.value;
    const n = Number(raw);
    const target = raw === "main3" ? "main3" : n === 4 || n === 2 ? n : 1;
    const seq = ++layoutChangeSeq;
    console.info("[panels] layout select →", raw, target);
    setPanelLayout(target)
      .then(() => {
        if (seq === layoutChangeSeq) {
          console.info("[panels] layout ready", window.ZNCavePanels?.diagnose?.());
        }
        if (userPrefsReady) savePreferences();
      })
      .catch((error) => {
        console.error("[panels] layout failed", error);
        showBanner(`Panel layout failed: ${error.message || error}`);
      });
  };
  // change only — input+change double-fired and raced two loadRadarLoop calls
  controls.panelLayoutSelect.addEventListener("change", onLayoutChange);
} else {
  console.warn("[panels] #panelLayoutSelect not found — dual/quad will not work");
}

