function userInitials(displayName, username) {
  const source = String(displayName || username || "?").trim();
  if (!source) {
    return "?";
  }
  const parts = source.split(/[\s@._-]+/).filter(Boolean);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return source.slice(0, 2).toUpperCase();
}

function railEl(id) {
  return document.getElementById(id) || (controls && controls[id]) || null;
}

function applySessionToUi() {
  const name = session.displayName || session.username || "Operator";
  const handle = session.username || "";
  const userLine = document.querySelector("#userLine");
  const railName = document.querySelector("#railUserName");
  const railHandle = document.querySelector("#railUserHandle");
  const railAvatar = document.querySelector("#railUserAvatar");
  const railSignOut = document.querySelector("#railSignOut");
  const oidcOn = Boolean(session.sso && session.sso.oidcEnabled);
  const loginUrl = (session.sso && session.sso.loginUrl) || "/auth/login";
  const logoutUrl = (session.sso && session.sso.logoutUrl) || "/auth/logout";

  if (userLine) {
    const ssoTag = session.authenticated
      ? session.via === "oidc"
        ? " · Authentik"
        : session.via === "headers"
          ? " · Authentik (proxy)"
          : " · Authentik"
      : oidcOn
        ? " · not signed in"
        : " · local";
    userLine.textContent = session.authenticated
      ? `Signed in as ${name}${ssoTag}`
      : oidcOn
        ? `Not signed in — use Login on the left rail`
        : `Signed in as ${name}${ssoTag}`;
  }
  if (railName) {
    railName.textContent = session.authenticated ? name : oidcOn ? "Sign in" : name;
    railName.title = name;
  }
  if (railHandle) {
    railHandle.textContent = session.authenticated
      ? `@${handle}`
      : oidcOn
        ? "Authentik"
        : "local";
    railHandle.title = session.email || handle || "";
  }
  if (railAvatar) {
    railAvatar.textContent = session.authenticated ? userInitials(name, handle) : oidcOn ? "→" : userInitials(name, handle);
    railAvatar.title = session.authenticated ? "Signed in via Authentik" : "Click Out area / Login";
  }
  if (railSignOut) {
    if (session.authenticated) {
      railSignOut.href = logoutUrl;
      railSignOut.title = "Sign out";
      const label = railSignOut.querySelector(".rail-label");
      if (label) {
        label.textContent = "Out";
      }
      const icon = railSignOut.querySelector("span[aria-hidden]");
      if (icon) {
        icon.textContent = "⏻";
      }
    } else if (oidcOn) {
      railSignOut.href = loginUrl;
      railSignOut.title = "Sign in with Authentik";
      const label = railSignOut.querySelector(".rail-label");
      if (label) {
        label.textContent = "In";
      }
      const icon = railSignOut.querySelector("span[aria-hidden]");
      if (icon) {
        icon.textContent = "→";
      }
    } else {
      railSignOut.href = logoutUrl;
      railSignOut.title = "Sign out";
    }
    railSignOut.hidden = false;
  }

  if (session.authenticated) {
    console.info(`[SSO] Authenticated as ${session.username} via ${session.via || "?"}`);
  } else if (oidcOn) {
    console.info("[SSO] OIDC enabled — redirecting to Authentik login if required");
  } else {
    console.warn(
      "[SSO] OIDC not configured on server (clientIdConfigured=false). Set AUTHENTIK_CLIENT_ID + SECRET and restart Node."
    );
  }
}

/** Ops only: force Authentik login when OIDC is on and user is not signed in. */
function maybeForceOidcLogin() {
  if (session.authenticated) {
    return false;
  }
  const oidcOn = Boolean(session.sso && session.sso.oidcEnabled);
  if (!oidcOn) {
    return false;
  }
  // Don't loop on public page or auth routes
  const path = window.location.pathname || "/";
  if (path.startsWith("/public") || path.startsWith("/auth/")) {
    return false;
  }
  const params = new URLSearchParams(window.location.search);
  if (params.has("auth_error") || params.has("nologin")) {
    return false;
  }
  const loginUrl = (session.sso && session.sso.loginUrl) || "/auth/login";
  const returnTo = path + window.location.search;
  const target = `${loginUrl}?returnTo=${encodeURIComponent(returnTo || "/")}`;
  console.info("[SSO] Forcing login →", target);
  window.location.replace(target);
  return true;
}

async function loadSession() {
  try {
    const response = await fetch("/api/session", { cache: "no-store", credentials: "same-origin" });

    if (!response.ok) {
      throw new Error(`Session HTTP ${response.status}`);
    }

    session = await response.json();
    reportHiveDesktopReadiness(document.body.classList.contains("warning-stream-online"));
  } catch (error) {
    console.warn("[SSO] loadSession failed", error);
    session = {
      authenticated: false,
      displayName: "Local Operator",
      username: "local-operator",
      email: "",
      headersPresent: {},
      sso: {
        oidcEnabled: false,
        loginUrl: "/auth/login",
        logoutUrl: "/auth/logout"
      }
    };
    reportHiveDesktopReadiness(false);
  }

  applySessionToUi();
  maybeForceOidcLogin();
}

async function loadPreferences() {
  try {
    const response = await fetch("/api/preferences", { credentials: "same-origin", cache: "no-store" });

    if (!response.ok) {
      throw new Error("Preferences unavailable");
    }

    const savedPreferences = await response.json();
    applyServerPreferences(savedPreferences);
    syncPracticeModeBanner();
    lastPrefsSavedAt = savedPreferences.updatedAt || new Date().toISOString();
    setSaveState("", "saved", {
      useFormatter: true,
      savedAt: lastPrefsSavedAt,
      displayName: session.displayName || session.username
    });
  } catch {
    try {
      const response = await fetch("/api/bootstrap-state", { cache: "no-store", credentials: "same-origin" });
      if (!response.ok) throw new Error(`Bootstrap HTTP ${response.status}`);
      const bootstrap = await response.json();
      applyServerPreferences(bootstrap.preferences || {});
      syncPracticeModeBanner();
      lastPrefsSavedAt = bootstrap.preferences?.updatedAt || null;
      setSaveState("", "saved", {
        useFormatter: true,
        savedAt: lastPrefsSavedAt,
        displayName: session.displayName || session.username
      });
    } catch {
      layerPreferences = cloneDefaultLayerPreferences();
      mapSetups = {};
      layerStackOrder = [...defaultLayerStackOrder];
      radarDisplaySettings = { ...defaultRadarDisplaySettings };
      cityDensityMode = "balanced";
      cityTextScale = 100;
      panelViewsLinked = true;
      setSaveState("", "error", {
        useFormatter: true,
        detail: "Could not load server preferences — using defaults"
      });
    }
  }
  renderMapSetupOptions();
  renderRadarPaletteControls();
  renderRadarDisplaySettings();
  setCityDensity(cityDensityMode, { persist: false });
  setCityTextSize(cityTextScale, { persist: false });
  setPanelViewsLinked(panelViewsLinked, { persist: false, syncNow: false });
}

function pointInRing(point, ring) {
  // Ray cast; ring is [[lng, lat], ...]
  const [x, y] = point;
  let inside = false;

  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0];
    const yi = ring[i][1];
    const xj = ring[j][0];
    const yj = ring[j][1];
    const intersects = yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 0.0) + xi;

    if (intersects) {
      inside = !inside;
    }
  }

  return inside;
}

function geometryContainsPoint(geometry, point) {
  if (!geometry) {
    return false;
  }

  if (geometry.type === "Polygon") {
    const [outer, ...holes] = geometry.coordinates;
    if (!pointInRing(point, outer)) {
      return false;
    }
    return holes.every((hole) => !pointInRing(point, hole));
  }

  if (geometry.type === "MultiPolygon") {
    return geometry.coordinates.some((polygon) => geometryContainsPoint({ type: "Polygon", coordinates: polygon }, point));
  }

  return false;
}

/** All places in catalog (WarnGen). Ignores map zoom / label visibility. */
function getAllPlaces() {
  return placesCatalog.features || [];
}

/** Places inside [west, south, east, north]. Zoom-independent. */
function getPlacesInBounds(bounds) {
  const [west, south, east, north] = bounds;
  return getAllPlaces().filter((feature) => {
    const [lng, lat] = feature.geometry.coordinates;
    return lng >= west && lng <= east && lat >= south && lat <= north;
  });
}

/** Places inside a GeoJSON Polygon/MultiPolygon. Zoom-independent for WarnGen. */
function getPlacesInPolygon(geometry) {
  return getAllPlaces().filter((feature) => geometryContainsPoint(geometry, feature.geometry.coordinates));
}

function normalizePlacesCatalog(payload) {
  const features = (payload.features || [])
    .map((feature) => {
      const props = feature.properties || {};
      const rank = Number(props.rank);
      const safeRank = Number.isFinite(rank) && rank >= 1 ? rank : 4;
      const minzoom = Number(props.minzoom);
      return {
        type: "Feature",
        properties: {
          ...props,
          name: String(props.name || "").trim(),
          state: String(props.state || "").trim(),
          rank: safeRank,
          minzoom: Number.isFinite(minzoom)
            ? minzoom
            : safeRank === 1
              ? 3
              : safeRank === 2
                ? 5
                : safeRank === 3
                  ? 6.5
                  : 8.5
        },
        geometry: feature.geometry
      };
    })
    .filter((feature) => feature.properties.name && feature.geometry && feature.geometry.type === "Point");

  return {
    type: "FeatureCollection",
    features
  };
}

const PLACE_LAYER_IDS = [
  // Low-priority places move first; major cities move last so they win
  // cross-layer label collisions instead of being displaced by hamlets.
  "place-labels-micro",
  "place-labels-hamlet",
  "place-labels-local",
  "place-labels-regional",
  "place-labels-major",
  "place-dots",
  "radar-site-dots",
  "radar-site-labels",
  "radar-site-active"
];

function placeHasUsableCoordinates(feature) {
  const coords = feature && feature.geometry && feature.geometry.coordinates;
  if (!coords || coords.length < 2) {
    return false;
  }
  const lng = Number(coords[0]);
  const lat = Number(coords[1]);
  // Drop broken gazetteer rows (old INTPTLONG parse left lon=0 for every place).
  if (!Number.isFinite(lng) || !Number.isFinite(lat)) {
    return false;
  }
  if (Math.abs(lng) < 0.05 || Math.abs(lat) < 0.05) {
    return false;
  }
  if (Math.abs(lat) > 90 || Math.abs(lng) > 180) {
    return false;
  }
  return true;
}

/** Map labels only — keep the map light. WarnGen still uses the full placesCatalog. */
function placeMeetsMapPopulationGate(feature) {
  const props = (feature && feature.properties) || {};
  const pop = Number(props.population);
  if (Number.isFinite(pop)) {
    return pop >= cityDensityProfile().minPopulation;
  }
  // Census rows often omit population. Keep only major/regional hubs so labels
  // still show for cities like Nashville without inventing a population.
  const rank = Number(props.rank);
  return rank === 1 || rank === 2;
}

/**
 * Map city source follows the operator's density setting (500–25k minimum,
 * or rank 1–2 if population is missing).
 * Full dense catalog stays in placesCatalog for WarnGen location / city lists.
 */
function buildMapDisplayPlaces(catalog) {
  const features = (catalog.features || []).filter((feature) => {
    if (!placeHasUsableCoordinates(feature)) {
      return false;
    }
    return placeMeetsMapPopulationGate(feature);
  });

  return {
    type: "FeatureCollection",
    features
  };
}

function applyCityDensity(targetMap) {
  if (!targetMap?.getStyle?.()) return;
  const profile = cityDensityProfile();
  const display = buildMapDisplayPlaces(placesCatalog);
  targetMap.getSource("cities")?.setData(display.features.length ? display : placeLabelsBootstrap);
  const zoomRanges = {
    "place-labels-major": 3,
    "place-labels-regional": profile.regionalZoom,
    "place-labels-local": profile.localZoom,
    "place-labels-hamlet": profile.hamletZoom,
    "place-labels-micro": profile.microZoom
  };
  Object.entries(zoomRanges).forEach(([layerId, minZoom]) => {
    if (targetMap.getLayer(layerId)) targetMap.setLayerZoomRange(layerId, minZoom, 24);
  });
}

function setCityDensity(mode, { persist = true } = {}) {
  cityDensityMode = CITY_DENSITY_PROFILES[mode] ? mode : "balanced";
  if (controls.cityDensitySelect) controls.cityDensitySelect.value = cityDensityMode;
  activePanelMaps().forEach(applyCityDensity);
  if (persist) savePreferences();
}

function setCityTextSize(value, { persist = true } = {}) {
  const numeric = Number(value);
  cityTextScale = Number.isFinite(numeric) ? Math.max(70, Math.min(160, Math.round(numeric / 5) * 5)) : 100;
  if (controls.cityTextSizeInput) controls.cityTextSizeInput.value = String(cityTextScale);
  if (controls.cityTextSizeValue) controls.cityTextSizeValue.textContent = `${cityTextScale}%`;
  const textSize = cityTextSizeExpression();
  activePanelMaps().forEach((targetMap) => {
    PLACE_LAYER_IDS.forEach((layerId) => {
      // Radar-site circles share the top-of-map layer list but are not text
      // layers. Only city-label symbols accept the text-size property.
      if (layerId.startsWith("place-labels-") && targetMap.getLayer(layerId)) {
        targetMap.setLayoutProperty(layerId, "text-size", textSize);
      }
    });
  });
  if (persist) savePreferences();
}

function applyCityLabelDisplay() {
  activePanelMaps().forEach((targetMap) => {
    PLACE_LAYER_IDS.filter((id) => id.startsWith("place-labels-")).forEach((layerId) => {
      if (!targetMap.getLayer(layerId)) return;
      targetMap.setLayoutProperty(layerId, "visibility", cityLabelsEnabled ? "visible" : "none");
      targetMap.setPaintProperty(layerId, "text-opacity", cityLabelsOpacity / 100);
    });
  });
  scheduleLayerStackApply();
}

function diagnosePlacesPayload(payload) {
  const features = (payload && payload.features) || [];
  let total = features.length;
  let usable = 0;
  let zeroLon = 0;
  let rankOk = 0;

  features.forEach((feature) => {
    const coords = feature && feature.geometry && feature.geometry.coordinates;
    const lng = coords ? Number(coords[0]) : NaN;
    if (Number.isFinite(lng) && Math.abs(lng) < 0.05) {
      zeroLon += 1;
    }
    if (placeHasUsableCoordinates(feature)) {
      usable += 1;
      const rank = Number(feature.properties && feature.properties.rank);
      if (rank >= 1 && rank <= 3) {
        rankOk += 1;
      }
    }
  });

  return { total, usable, zeroLon, rankOk };
}

function ensurePlaceLayersOnTop(targetMap = map) {
  if (!targetMap) {
    return;
  }

  const textSize = cityTextSizeExpression();
  PLACE_LAYER_IDS.forEach((layerId) => {
    if (!targetMap.getLayer(layerId)) {
      return;
    }
    try {
      if (layerId.startsWith("place-labels-")) {
        targetMap.setLayoutProperty(layerId, "visibility", cityLabelsEnabled ? "visible" : "none");
        targetMap.setPaintProperty(layerId, "text-opacity", cityLabelsOpacity / 100);
        targetMap.setLayoutProperty(layerId, "text-size", textSize);
        return;
      }
      targetMap.setLayoutProperty(layerId, "visibility", "visible");
      targetMap.moveLayer(layerId);
    } catch (error) {
      console.warn(`Unable to raise place layer ${layerId}`, error);
    }
  });
  // Raising labels and radar-site selectors must never leave operational
  // warning polygons underneath raster/custom radar layers.
  restackWarnGenAboveRadar(targetMap);
}

function setCitiesSourceData(featureCollection) {
  activePanelMaps().forEach((instance) => {
    if (!instance || !instance.getSource("cities")) {
      return;
    }
    instance.getSource("cities").setData(featureCollection);
    ensurePlaceLayersOnTop(instance);
    instance.triggerRepaint();
  });
}

async function loadPlacesCatalog() {
  // Fast path: slim map-cities (~1–2 MB) for labels. Full 38 MB gazetteer loads later for WarnGen.
  try {
    let response = await fetch(MAP_CITIES_GEOJSON_URL, { cache: "force-cache" });
    let usedSlim = response.ok;
    if (!response.ok) {
      response = await fetch(CITIES_GEOJSON_URL, { cache: "force-cache" });
      usedSlim = false;
    }

    if (!response.ok) {
      throw new Error(`Places geojson HTTP ${response.status}`);
    }

    const payload = await response.json();
    if (!payload || payload.type !== "FeatureCollection" || !Array.isArray(payload.features) || !payload.features.length) {
      throw new Error("Places geojson empty");
    }

    const diagnosis = diagnosePlacesPayload(payload);
    if (diagnosis.usable === 0) {
      throw new Error(
        diagnosis.zeroLon > 0
          ? `cities.geojson has invalid coordinates (${diagnosis.zeroLon}/${diagnosis.total} with lon≈0). On the server run: python3 scripts/prepare-place-labels.py`
          : "Places geojson had no usable coordinates for map labels"
      );
    }

    placesCatalog = normalizePlacesCatalog(payload);
    let displayPlaces = buildMapDisplayPlaces(placesCatalog);

    // Slim file is already pop-filtered — use as-is if gate drops everything oddly.
    if (!displayPlaces.features.length && diagnosis.usable > 0) {
      displayPlaces = {
        type: "FeatureCollection",
        features: placesCatalog.features.filter(placeHasUsableCoordinates).slice(0, 8000)
      };
    }

    if (!displayPlaces.features.length) {
      throw new Error(
        `Places geojson unusable after filter (total=${diagnosis.total}, usable=${diagnosis.usable}, rank1-3=${diagnosis.rankOk}, zeroLon=${diagnosis.zeroLon})`
      );
    }

    setCitiesSourceData(displayPlaces);
    console.info(
      `Map places ready (${displayPlaces.features.length}${usedSlim ? " slim" : " full"}). WarnGen catalog ${usedSlim ? "loading in background" : "ready"}.`
    );

    if (usedSlim) {
      loadFullPlacesCatalogInBackground();
    }

    return displayPlaces.features.length;
  } catch (error) {
    console.warn("Full places catalog unavailable; using bootstrap city set.", error);
    placesCatalog = placeLabelsBootstrap;
    setCitiesSourceData(placeLabelsBootstrap);
    return placeLabelsBootstrap.features.length;
  }
}

function loadFullPlacesCatalogInBackground() {
  window.setTimeout(async () => {
    try {
      const response = await fetch(CITIES_GEOJSON_URL, { cache: "force-cache" });
      if (!response.ok) {
        return;
      }
      const payload = await response.json();
      if (!payload || !Array.isArray(payload.features) || !payload.features.length) {
        return;
      }
      const diagnosis = diagnosePlacesPayload(payload);
      if (diagnosis.usable === 0) {
        return;
      }
      placesCatalog = normalizePlacesCatalog(payload);
      console.info(`[places] full WarnGen catalog ready (${placesCatalog.features.length})`);
    } catch (error) {
      console.warn("[places] full catalog background load failed", error);
    }
  }, 5000);
}

