// Safety net: any zone hazard definition not listed above still appears in HAZ.
Object.entries(GFE_HAZARDS).forEach(([code, hazard]) => {
  if (HAZARD_SERVICES_CATALOG.some((group) => group.products.some((product) => product.code === code))) return;
  const category = hazard.product === "WSW" ? "Winter"
    : hazard.product === "RFW" ? "Fire weather"
    : hazard.product === "FFA" ? "Flood"
    : hazard.product === "CFW" ? "Coastal / lakeshore"
    : "Non-precipitation";
  const group = HAZARD_SERVICES_CATALOG.find((entry) => entry.category === category);
  group?.products.push({ code, name: hazard.name, engine: "zone", zoneType: hazard.zoneType || "public" });
});

function renderHazardServicesZoneFields(hazard) {
  const host = document.querySelector("#hazZoneHazardFields");
  if (!host || !hazard) return;
  const fields = Array.isArray(hazard.fields) ? hazard.fields : [];
  host.innerHTML = fields.map(([key, label, type, placeholder = ""]) => `<label class="field"><span>${escapeHtml(label)} <small>Optional</small></span><input type="${escapeHtml(type)}" data-haz-zone-field="${escapeHtml(key)}" placeholder="${escapeHtml(placeholder)}" ${type === "number" ? 'step="0.1"' : ""}></label>`).join("");
  document.querySelector("#hazZoneImpacts").value = hazard.impacts || "";
  document.querySelector("#hazZoneAdditionalDetails").value = "";
}

function syncHazardServicesZoneFields() {
  // Rebuild legacy fields so every HAZ key exists before copy (covers newly added products).
  ensureGfeHazardSelectOptions();
  if (hazSelectedProduct?.engine === "zone" && controls.gfeHazardSelect && GFE_HAZARDS[hazSelectedProduct.code]) {
    controls.gfeHazardSelect.value = hazSelectedProduct.code;
  }
  renderGfeHazardFields({ preserve: true });
  document.querySelectorAll("[data-haz-zone-field]").forEach((input) => {
    const key = input.dataset.hazZoneField;
    if (!key) return;
    const legacy = controls.gfeHazardFields?.querySelector(`[data-gfe-field="${key}"]`);
    if (legacy) legacy.value = input.value;
  });
  if (controls.gfeImpactsInput) controls.gfeImpactsInput.value = document.querySelector("#hazZoneImpacts")?.value.trim() || selectedGfeHazard().impacts;
  if (controls.gfeDetailsInput) controls.gfeDetailsInput.value = document.querySelector("#hazZoneAdditionalDetails")?.value.trim() || "";
}

function renderHazardServicesCatalog() {
  const host = document.querySelector("#hazCategoryList");
  if (!host) return;
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem("zncave-haz-beta-draft") || "null"); } catch { saved = null; }
  const savedRow = saved?.product?.code ? `<div class="haz-category"><div class="haz-product-list"><button type="button" class="haz-product-button" data-haz-resume><span>Resume ${escapeHtml(saved.product.name || saved.product.code)}</span><small>${escapeHtml(String(saved.savedAt || "").slice(11, 16))}Z ›</small></button></div></div>` : "";
  host.innerHTML = savedRow + HAZARD_SERVICES_CATALOG.map((group, index) => `<details class="haz-category" ${index === 0 ? "open" : ""}><summary>${escapeHtml(group.category)}</summary><div class="haz-product-list">${group.products.map((product) => `<button type="button" class="haz-product-button" data-haz-product="${escapeHtml(product.code)}"><span>${escapeHtml(product.name)}</span><small>${["SMW", "MWS"].includes(product.code) ? "Polygon / Zones" : product.engine === "zone" ? "Zones" : "Polygon"} ›</small></button>`).join("")}</div></details>`).join("");
}

function findHazardServicesProduct(code) {
  for (const group of HAZARD_SERVICES_CATALOG) {
    const product = group.products.find((item) => item.code === code);
    if (product) return { ...product, category: group.category };
  }
  return null;
}

function isSmwZoneGeometryMode() {
  return (
    ["SMW", "MWS"].includes(String(warnState?.product || hazSelectedProduct?.code || "").toUpperCase()) &&
    String(warnState?.smw?.geometryMode || controls.warnSmwGeometryMode?.value || "polygon") === "zone"
  );
}

/** Frame-linked motion dots + speed/dir (SMW zone mode included — motion is optional wording/TML). */
function hazardServicesUsesStormTrack(code) {
  return ["TOR", "SVR", "SQW", "DSW", "DSY", "SPS", "SMW", "MWS"].includes(String(code || "").toUpperCase());
}

/** Storm marker / motion-built threat corridor (not used for SMW marine-zone geometry). */
function hazardServicesUsesPlaceStorm(code) {
  const c = String(code || "").toUpperCase();
  if (["SMW", "MWS"].includes(c) && isSmwZoneGeometryMode()) return false;
  return hazardServicesUsesStormTrack(c);
}

/** Switch SMW between freehand storm polygon and marine-zone click selection. */
function applySmwGeometryMode(mode, { silent = false } = {}) {
  if (!warnState) return;
  const next = mode === "zone" ? "zone" : "polygon";
  warnState.product = warnState.product === "MWS" ? "MWS" : "SMW";
  warnState.smw = { ...(warnState.smw || window.WarnGen?.createState?.(activeWfo)?.smw || {}), geometryMode: next };
  warnState.ugcBasis = "marine";
  if (controls.warnSmwGeometryMode) controls.warnSmwGeometryMode.value = next;
  const mirror = document.querySelector('[data-haz-mirror="warnSmwGeometryMode"]');
  if (mirror) mirror.value = next;

  void ensureWarnBoundaryData()
    .then(() => {
      applyMarineZoneDisplay(true);
      if (next === "zone") {
        // Keep motion track / speed if already set — zone geometry is independent of corridor poly
        warnState.lineStart = null;
        warnState.lineEnd = null;
        warnState.vertices = [];
        // Zones list is the geometry; rebuild union poly from selection
        if (window.WarnGen?.marineZonesToPolygon && warnState.zones?.length) {
          warnState.polygon = window.WarnGen.marineZonesToPolygon(warnState.zones);
          if (!warnState.location) {
            warnState.location = geometryCentroid(warnState.polygon) || null;
          }
        } else {
          warnState.polygon = null;
        }
        setWarnMode("selectMarineZones");
        updateSmwSelectedMarineGraphics();
        updateWarnMapGraphics();
        renderWarnAreas();
        updateSmwHazGeometryUi();
        // Seed frame-linked motion dots once we have a location seed (zone centroid)
        if (warnState.location || warnState.polygon) {
          ensureHazMotionTrackPoint();
          updateWarnMapGraphics();
        }
        if (!silent) {
          const n = window.WarnGen?.filterMarineZoneFeatures?.(warnMarineFc, activeWfo)?.length || 0;
          showBanner(
            n
              ? "Marine zone mode: click cyan zones to select waters. Optional: drag frame motion dots for speed/direction (TML)."
              : `No marine zones for ${activeWfo} — switch WFO to a coastal/Great Lakes office, or use polygon mode.`
          );
        }
      } else {
        setWarnMode("placeStorm");
        if (!warnState.location) {
          const center = map.getCenter();
          warnState.location = [center.lng, center.lat];
        }
        updateWarnMapGraphics();
        updateSmwHazGeometryUi();
        if (!silent) {
          showBanner("Storm polygon mode: drag the marker onto the cell (or draw). Marine zones under the poly become UGC.");
        }
      }
    })
    .catch((error) => {
      console.warn("[smw] geometry mode", error);
      if (!silent) showBanner("Could not load marine zones for SMW.");
    });
}

function updateSmwHazGeometryUi() {
  if (!["SMW", "MWS"].includes(hazSelectedProduct?.code)) return;
  const zoneMode = isSmwZoneGeometryMode();
  const placeBtn = document.querySelector("#hazPlaceStormButton");
  const placeLabel = document.querySelector("#hazPlaceStormLabel");
  const hint = document.querySelector("#hazGeometryHint");
  if (placeBtn) {
    placeBtn.hidden = false;
    placeBtn.classList.toggle("is-armed", zoneMode && warnState?.mode === "selectMarineZones");
  }
  if (placeLabel) {
    placeLabel.textContent = zoneMode ? "Click marine zones" : "Drag to storm";
  }
  if (hint) {
    hint.textContent = zoneMode
      ? `Marine zone mode for ${activeWfo}: click cyan outlines to select waters (orange = selected). Motion direction/speed fields and frame-linked dots still work for storm motion wording — they do not reshape the zones.`
      : "Storm placement is active. Drag the map marker onto the storm, or switch Geometry mode to Marine zone selection to click whole zones.";
  }
  // Keep compact geometry-mode control in sync
  const hazMode = document.querySelector("#hazSmwGeometryMode");
  if (hazMode) hazMode.value = zoneMode ? "zone" : "polygon";
}

function renderSmwGeometryModeInHazUi() {
  const section = document.querySelector("#hazPlaceStormButton")?.closest(".haz-form-section");
  if (!section) return;
  section.querySelector("#hazSmwGeometryField")?.remove();
  if (!["SMW", "MWS"].includes(hazSelectedProduct?.code)) return;
  const field = document.createElement("label");
  field.className = "field";
  field.id = "hazSmwGeometryField";
  field.innerHTML = `<span>Geometry mode</span>
    <select id="hazSmwGeometryMode">
      <option value="polygon">Storm-based polygon</option>
      <option value="zone">Marine zone selection</option>
    </select>
    <small class="hint">Zone mode: click marine zones on the map. Polygon mode: drag storm / freehand poly.</small>`;
  const hint = document.querySelector("#hazGeometryHint");
  if (hint) hint.before(field);
  else section.prepend(field);
  const select = field.querySelector("#hazSmwGeometryMode");
  select.value = isSmwZoneGeometryMode() ? "zone" : "polygon";
  select.addEventListener("change", () => {
    applySmwGeometryMode(select.value);
  });
}

function setHazardServicesStormShape(shape) {
  if (!warnState || !["TOR", "SVR"].includes(hazSelectedProduct?.code)) return;
  const next = shape === "line" ? "line" : "cell";
  warnState.stormType = next;
  if (controls.warnStormType) controls.warnStormType.value = next;
  warnState.motionTrack = [];
  warnState.motionTrackFit = [];
  warnState.motion1 = null;
  warnState.motion2 = null;
  warnState.motion = null;
  warnState.lineTrace = [];
  warnState.projectedLineTrace = [];
  const center = map.getCenter();
  if (next === "line") {
    const origin = warnState.location || [center.lng, center.lat];
    warnState.lineStart = null;
    warnState.lineEnd = null;
    warnState.location = [...origin];
    ensureHazMotionTrackPoint({ create: true, lngLat: origin });
    warnState.polygon = null;
    warnState.vertices = [];
    setWarnMode("traceLine");
    updateWarnMapGraphics();
    showBanner("Line mode: click along the storm line, then press Enter or double-click. Advance radar and click later storm positions to project the trace.");
  } else {
    warnState.lineStart = null;
    warnState.lineEnd = null;
    warnState.polygon = null;
    warnState.vertices = [];
    warnState.lineTrace = [];
    warnState.projectedLineTrace = [];
    warnState.location = [center.lng, center.lat];
    setWarnMode("placeStorm");
    updateWarnMapGraphics();
    showBanner("Single-storm mode: drag the storm marker onto the cell.");
  }
}

function renderHazardServicesStormShape(product) {
  const tools = document.querySelector(".haz-compact-tools");
  if (!tools) return;
  tools.querySelector("#hazStormShapeField")?.remove();
  if (!["TOR", "SVR"].includes(product?.code)) return;
  const field = document.createElement("label");
  field.className = "field haz-storm-shape-field";
  field.id = "hazStormShapeField";
  field.innerHTML = `<span>Storm shape</span><select id="hazStormShape"><option value="cell">Single storm</option><option value="line">Line</option></select>`;
  tools.prepend(field);
  field.querySelector("select").addEventListener("change", (event) => setHazardServicesStormShape(event.target.value));
}

function renderHazardServicesPolygonTemplateFields(product) {
  const section = document.querySelector("#hazProductTemplateFields");
  const host = document.querySelector("#hazProductTemplateFieldsBody");
  if (!section || !host) return;
  document.querySelector("#hazDetailsSection")?.after(section);
  if (!product || product.engine !== "polygon") { section.hidden = true; host.innerHTML = ""; return; }
  if (!product.ffwFamily) {
    const sourceCode = product.code === "MWS" ? "SMW" : product.code;
    const source = document.querySelector(`.warn-product-opts[data-product="${CSS.escape(sourceCode)}"]`);
    const excluded = new Set(product.code === "TOR"
      ? ["warnTorSource", "warnTorHail", "warnTorWind", "warnTorDamageThreat", "warnTorListCities"]
      : product.code === "SVR"
        ? ["warnBasisSelect", "warnWindSelect", "warnHailSelect"]
        : []);
    const controlsToMirror = source ? [...source.querySelectorAll("input[id], select[id], textarea[id]")].filter((input) => !excluded.has(input.id)) : [];
    section.hidden = controlsToMirror.length === 0;
    host.innerHTML = controlsToMirror.map((input) => {
      const label = input.closest("label")?.querySelector("span")?.textContent?.trim() || input.closest("label")?.textContent?.trim() || input.id;
      if (input.tagName === "SELECT") return `<label class="field"><span>${escapeHtml(label)}</span><select data-haz-mirror="${escapeHtml(input.id)}">${[...input.options].map((option) => `<option value="${escapeHtml(option.value)}" ${option.selected ? "selected" : ""}>${escapeHtml(option.textContent)}</option>`).join("")}</select></label>`;
      if (input.type === "checkbox" || input.type === "radio") return `<label class="toggle-row"><input type="${input.type}" data-haz-mirror="${escapeHtml(input.id)}" ${input.checked ? "checked" : ""}><span>${escapeHtml(label)}</span></label>`;
      return `<label class="field"><span>${escapeHtml(label)}</span><input type="${escapeHtml(input.type || "text")}" data-haz-mirror="${escapeHtml(input.id)}" value="${escapeHtml(input.value || "")}" placeholder="${escapeHtml(input.placeholder || "")}"></label>`;
    }).join("");
    if (["FAW", "FAY"].includes(product.code)) {
      const gauge = product.code === "FAW" ? warnState?.afw?.gauge : warnState?.fad?.gauge;
      host.insertAdjacentHTML("afterbegin", `<section class="haz-gauge-card" id="hazGaugeCard"><div><strong>River forecast point</strong><small id="hazGaugeStatus">${gauge ? escapeHtml(`${gauge.lid} · ${gauge.name}`) : "Click a river gauge on the map, then choose Use in Hazard Services."}</small></div><button type="button" class="button small" id="hazRefreshGauge" ${gauge?.lid ? "" : "disabled"}>Refresh gauge</button>${gauge ? hydroGaugeSummaryHtml(gauge) : ""}<label class="toggle-row"><input type="checkbox" id="hazGaugeConfirmed" ${gauge?.confirmed ? "checked" : ""} ${gauge ? "" : "disabled"}><span>I reviewed the observation, forecast, and timestamp</span></label></section>`);
    }
    return;
  }
  section.hidden = false;
  if (product.ffwFamily === "dam") {
    host.innerHTML = `<div class="field-grid"><label class="field"><span>Failure / flood cause</span><select id="hazDamCause"><option value="dam">Dam failure · occurring</option><option value="siteimminent">Dam failure · imminent</option><option value="sitefailed">Site-specific dam failure</option><option value="levee">Levee failure</option><option value="floodgate">Dam floodgate release</option><option value="icejam">Ice jam break</option><option value="glacier">Glacier-dammed lake outburst</option><option value="rain">Rain and snowmelt</option><option value="onlyMelt">Extremely rapid snowmelt</option><option value="volcano">Volcanic snowmelt</option><option value="volcanoLahar">Volcanic debris flow / lahar</option></select></label><label class="field"><span>Damage threat</span><select id="hazDamDamage"><option value="base">Base</option><option value="considerable">Considerable</option><option value="catastrophic">Catastrophic / Flash Flood Emergency</option></select></label></div><div class="field-grid"><label class="field"><span>Reporting source</span><select id="hazDamSource"><option value="county">County dispatch</option><option value="lawEnforcement">Law enforcement</option><option value="corps">Corps of Engineers</option><option value="damop">Dam operators</option><option value="bureau">Bureau of Reclamation</option><option value="public">Public</option><option value="onlyGauge">Gauges</option><option value="CAP">Civil Air Patrol</option><option value="alaskaVoc">Alaska Volcano Observatory</option><option value="cascadeVoc">Cascades Volcano Observatory</option></select></label><label class="field"><span>Dam / feature name</span><input id="hazDamName" placeholder="e.g. Example Dam"></label><label class="field"><span>River / drainage</span><input id="hazDamRiver" placeholder="e.g. Example River"></label><label class="field"><span>Downstream locations</span><input id="hazDamLocations" placeholder="communities or areas downstream"></label></div><label class="field"><span>Additional site-specific details</span><textarea id="hazDamDetails" rows="3"></textarea></label>`;
    return;
  }
  host.innerHTML = `<div class="field-grid"><label class="field"><span>Flooding source</span><select id="hazFfwSource"><option value="doppler">Doppler radar</option><option value="dopplerGauge">Radar and automated gauges</option><option value="trainedSpotters">Trained spotters</option><option value="lawEnforcement">Law enforcement</option><option value="emergencyManagement">Emergency management</option><option value="public">Public report</option><option value="satellite">Satellite estimates</option><option value="satelliteGauge">Satellite and gauges</option><option value="onlyGauge">Gauge reports</option></select></label><label class="field"><span>Rain already fallen</span><select id="hazFfwRainAmount"><option value="none">Not specified</option><option value="rain1">Up to 1 inch</option><option value="rain2">Up to 2 inches</option><option value="rain3">Up to 3 inches</option><option value="rainEdit">Custom amount</option></select></label></div><label class="field" id="hazFfwRainCustomField" hidden><span>Custom rainfall amount</span><input type="text" id="hazFfwRainCustom" placeholder="e.g. 2 to 3"></label><label class="toggle-row"><input type="checkbox" id="hazFfwThunder" checked><span>Thunderstorms producing heavy rain</span></label><label class="toggle-row"><input type="checkbox" id="hazFfwOccurring"><span>Flash flooding already occurring</span></label><label class="toggle-row"><input type="checkbox" id="hazFfwSnowmelt"><span>Rain and snowmelt</span></label><label class="toggle-row"><input type="checkbox" id="hazFfwBurnScar"><span>Burn scar / debris-flow threat</span></label><label class="toggle-row"><input type="checkbox" id="hazFfwAdditional"><span>Additional rainfall expected</span></label><label class="field" id="hazFfwAdditionalField" hidden><span>Additional rainfall amount</span><input type="text" id="hazFfwAdditionalAmount" placeholder="e.g. 1 to 2 inches"></label><label class="toggle-row"><input type="checkbox" id="hazFfwEmergency"><span>Flash Flood Emergency</span></label><label class="field" id="hazFfwEmergencyField" hidden><span>Emergency location(s)</span><input type="text" id="hazFfwEmergencyLocation" placeholder="e.g. downtown Minot"></label>`;
  if (product.ffwFamily === "convective") {
    host.insertAdjacentHTML("afterbegin", `<div class="field-grid"><label class="field"><span>Flash flood damage threat</span><select id="hazFfwDamage"><option value="base">Base</option><option value="considerable">Considerable</option><option value="catastrophic">Catastrophic / Emergency</option></select></label><label class="field"><span>Expected rainfall tag</span><select id="hazFfwExpectedRain"><option value="none">Not specified</option><option value="rain1">1–2 inches in 1 hour</option><option value="rain2">2–3 inches in 1 hour</option><option value="rain3">1–3 inches in 1 hour</option><option value="custom">Custom</option></select></label></div><label class="field" id="hazFfwExpectedRainCustomField" hidden><span>Custom expected rainfall amount and duration</span><input id="hazFfwExpectedRainCustom" placeholder="e.g. 2-4 INCHES IN 2 HOURS"></label>`);
  }
}

function syncHazardServicesTemplateMirrors() {
  document.querySelectorAll("[data-haz-mirror]").forEach((mirror) => {
    const target = document.getElementById(mirror.dataset.hazMirror);
    if (!target) return;
    if (mirror.type === "checkbox" || mirror.type === "radio") target.checked = mirror.checked;
    else target.value = mirror.value;
    target.dispatchEvent(new Event("change", { bubbles: true }));
  });
}

function validateHazardServicesText(product, text) {
  const value = String(text || "");
  const problems = [];
  if (value.length < 100) problems.push("generated product text is incomplete");
  if (!value.includes("$$")) problems.push("missing product terminator ($$)");
  const vtecByProduct = { SVR: ".SV.W.", TOR: ".TO.W.", FFW: ".FF.W.", FAW: ".FA.W.", FAY: ".FA.Y.", SQW: ".SQ.W.", DSW: ".DS.W.", DSY: ".DS.Y.", SMW: ".MA.W." };
  const requiredVtec = vtecByProduct[product?.code];
  if (requiredVtec && !value.includes(requiredVtec)) problems.push(`missing ${requiredVtec} VTEC`);
  if (["SVR", "TOR", "SQW"].includes(product?.code) && (warnState?.counties || []).length > 12) problems.push("SVR/TOR/SQW products are limited to 12 counties");
  if (product?.code === "SQW") {
    const duration = Number(warnState?.validMinutes || 0);
    if (duration < 30 || duration > 60) problems.push("SQW valid time must be 30 to 60 minutes");
    if (!value.includes("SNOW SQUALL...")) problems.push("missing SNOW SQUALL source tag");
    if (warnState?.sqw?.impact === "significant" && !value.includes("SNOW SQUALL IMPACT...SIGNIFICANT")) problems.push("missing SIGNIFICANT snow-squall impact tag");
  }
  if (["DSW", "DSY"].includes(product?.code)) {
    const duration = Number(warnState?.validMinutes || 0);
    if (duration < 20 || duration > 120) problems.push("Dust warning/advisory valid time must be 20 minutes to 2 hours");
  }
  if (product?.code === "MWS") {
    const duration = Number(warnState?.validMinutes || 0);
    if (duration < 1 || duration > 720) problems.push("MWS valid time cannot exceed 12 hours");
    if (["kt34", "kt40", "kt40plus", "kt50", "kt65"].includes(warnState?.smw?.windId)) problems.push("short-term MWS winds must be 33 knots or less; use SMW or MWW for stronger conditions");
  }
  if (product?.code === "SPS" && !["CAN", "EXP"].includes(String(warnState?.action || "NEW").toUpperCase())) {
    const duration = Number(warnState?.validMinutes || 0);
    if (duration < 1 || duration > 360) problems.push("SPS valid time cannot exceed 6 hours");
    const vertices = Array.isArray(warnState?.vertices) && warnState.vertices.length
      ? warnState.vertices.length
      : Number(warnState?.polygon?.coordinates?.[0]?.length || 1) - 1;
    if (vertices < 3 || vertices > 20) problems.push("impact-based SPS polygons must contain 3 to 20 vertices");
    if (warnState?.sps?.precipMode === "rain" && !warnState?.sps?.blankStatement) {
      ["HAZARD...", "SOURCE...", "IMPACT...", "LAT...LON", "TIME...MOT...LOC", "MAX HAIL SIZE...", "MAX WIND GUST..."].forEach((field) => {
        if (!value.includes(field)) problems.push(`missing ${field.replace("...", " ").trim()} SPS element`);
      });
      const orderedTags = ["LANDSPOUT...", "WATERSPOUT...", "MAX HAIL SIZE...", "MAX WIND GUST..."]
        .map((tag) => value.indexOf(tag)).filter((index) => index >= 0);
      if (orderedTags.some((index, position) => position > 0 && index < orderedTags[position - 1])) problems.push("SPS coded tags are out of order");
    }
  }
  if (product?.code === "FRW") {
    if (!String(warnState?.frw?.requestedBy || "").trim()) problems.push("missing requesting government/public-safety agency");
    if (!warnState?.frw?.authenticated) problems.push("alerting authority authentication has not been confirmed");
    const narrativeWords = [warnState?.frw?.details, warnState?.frw?.locations, warnState?.frw?.arrivalTime, warnState?.frw?.contact]
      .join(" ").trim().split(/\s+/).filter(Boolean).length;
    if (narrativeWords > 200) problems.push("NWEM free-text narrative exceeds the 200-word EAS limit");
    if (!/BULLETIN - (?:EAS ACTIVATION|IMMEDIATE BROADCAST) REQUESTED|URGENT - IMMEDIATE BROADCAST REQUESTED/.test(value)) {
      problems.push("missing authority-requested NWEM broadcast instruction");
    }
    if (!/The following message is being transmitted at the request of/i.test(value)) problems.push("missing alerting-authority relay statement");
  }
  if (product?.code === "SVR") {
    const requiredTags = ["HAIL THREAT...", "MAX HAIL SIZE...", "WIND THREAT...", "MAX WIND GUST..."];
    requiredTags.forEach((tag) => { if (!value.includes(tag)) problems.push(`missing ${tag.replace("...", " ").trim()} tag`); });
    const tagOrder = ["TORNADO...POSSIBLE", "THUNDERSTORM DAMAGE THREAT...", "HAIL THREAT...", "MAX HAIL SIZE...", "WIND THREAT...", "MAX WIND GUST..."]
      .map((tag) => value.indexOf(tag)).filter((index) => index >= 0);
    if (tagOrder.some((index, position) => position > 0 && index < tagOrder[position - 1])) problems.push("SVR IBW coded tags are out of order");
  }
  if (product?.code === "TOR") {
    if (!value.includes("TORNADO...")) problems.push("missing TORNADO status tag");
    if (!value.includes("MAX HAIL SIZE...")) problems.push("missing MAX HAIL SIZE tag");
    if (value.includes("MAX WIND GUST...")) problems.push("TOR products cannot contain an SVR MAX WIND GUST tag");
    const torTag = value.indexOf("TORNADO...");
    const damageTag = value.indexOf("TORNADO DAMAGE THREAT...");
    const hailTag = value.indexOf("MAX HAIL SIZE...");
    if (damageTag >= 0 && damageTag < torTag || hailTag >= 0 && hailTag < Math.max(torTag, damageTag)) problems.push("TOR IBW coded tags are out of order");
  }
  if (product?.code === "FFW") {
    ["HAZARD...", "SOURCE...", "IMPACT...", "LAT...LON", "FLASH FLOOD..."].forEach((field) => {
      if (!value.includes(field)) problems.push(`missing ${field.replace("...", " ").trim()}`);
    });
    const catastrophic = value.includes("FLASH FLOOD DAMAGE THREAT...CATASTROPHIC");
    const emergencyHeadline = /FLASH FLOOD EMERGENCY FOR/i.test(value);
    if (catastrophic && !emergencyHeadline) problems.push("catastrophic damage threat requires Flash Flood Emergency wording");
    if (emergencyHeadline && !catastrophic) problems.push("Flash Flood Emergency requires CATASTROPHIC damage threat");
    const damage = value.indexOf("FLASH FLOOD DAMAGE THREAT...");
    const rainfall = value.indexOf("EXPECTED RAINFALL...");
    const source = value.indexOf("FLASH FLOOD...");
    if (damage >= 0 && damage < source || rainfall >= 0 && rainfall < Math.max(source, damage)) problems.push("FFW coded tags are out of order");
  }
  const hydroAction = String(warnState?.action || "NEW").toUpperCase();
  if (product?.code === "FAW" && !["CAN", "EXP"].includes(hydroAction)) {
    ["* WHAT...", "* WHERE...", "* WHEN...", "* IMPACTS...", "* ADDITIONAL DETAILS...", "LAT...LON"].forEach((field) => {
      if (!value.includes(field)) problems.push(`missing ${field.replace("...", " ").trim()} section`);
    });
  }
  if (product?.code === "FAY" && !["CAN", "EXP"].includes(hydroAction)) {
    ["* WHAT...", "* WHERE...", "* WHEN...", "* IMPACTS...", "LAT...LON"].forEach((field) => {
      if (!value.includes(field)) problems.push(`missing ${field.replace("...", " ").trim()} section`);
    });
  }
  if (["SVR", "TOR", "FFW", "FAW", "FAY", "SQW", "DSW", "DSY"].includes(product?.code)) {
    const review = document.querySelector("#hazReviewText");
    let protectedEnvelope = null;
    try { protectedEnvelope = JSON.parse(review?.dataset.protectedEnvelope || "null"); } catch { protectedEnvelope = null; }
    if (protectedEnvelope) {
      // Use the same narrative boundary recognized by
      // protectHazardReviewEnvelope(). Hydro products begin with * WHAT...
      // rather than a convective "Warning for..." bullet.
      const firstBullet = value.search(/^\* (?:Severe Thunderstorm Warning for\.\.\.|Tornado Warning for\.\.\.|Flash Flood Warning for\.\.\.|Snow Squall Warning for\.\.\.|Dust Storm Warning for\.\.\.|Dust Advisory for\.\.\.|WHAT\.\.\.)/m);
      const tailStart = value.indexOf("LAT...LON");
      const currentPrefix = firstBullet >= 0 ? value.slice(0, firstBullet) : "";
      const currentTail = tailStart >= 0 ? value.slice(tailStart) : "";
      if (currentPrefix !== protectedEnvelope.prefix) problems.push("protected warning header was changed");
      if (currentTail !== protectedEnvelope.tail) problems.push("protected geometry or IBW coded-tag block was changed");
    }
  }
  const zoneProductFamily=GFE_HAZARDS[product?.code]?.product||"";
  const zoneVtecRequired=product?.engine==="zone"&&!['AQA','AQI'].includes(zoneProductFamily);
  if (zoneVtecRequired && !/\/O\.[A-Z]{3}\.K[A-Z]{3}\.[A-Z]{2}\.[WAYS]\./.test(value)) problems.push("missing or malformed zone VTEC");
  const awipsTokens = [...value.matchAll(/!\*\*([\s\S]*?)\*\*!/gi)]
    .map((match) => match[1].replace(/\s+/g, " ").trim())
    .filter(Boolean);
  if (awipsTokens.length) {
    const token = awipsTokens[0]
      .replace(/PLEASE RE-GENERATE(?: THIS WARNING)?/gi, "")
      .replace(/YOU (?:DID NOT|SELECTED)/gi, "")
      .replace(/\s+/g, " ")
      .trim();
    problems.push(`unresolved field: ${token || "template value"}`);
  }
  if (/\{\{[A-Z0-9_]+\}\}|\$\{[^}]+\}|<L>|<\/L>/i.test(value)) problems.push("contains unresolved template markup");
  if (/\b(?:INSERT|ENTER|EDIT)\s+(?:LOCATION|AMOUNT|DETAIL|REASON|RIVER|STREAM|AREA)/i.test(value)) problems.push("contains unresolved operator placeholders");
  return problems;
}

function protectHazardReviewEnvelope(product, text) {
  const review = document.querySelector("#hazReviewText");
  if (!review) return;
  delete review.dataset.protectedEnvelope;
  if (!["SVR", "TOR", "FFW", "FAW", "FAY", "SQW", "DSW", "DSY"].includes(product?.code)) return;
  const value = String(text || "");
  const firstBullet = value.search(/^\* (?:Severe Thunderstorm Warning for\.\.\.|Tornado Warning for\.\.\.|Flash Flood Warning for\.\.\.|Snow Squall Warning for\.\.\.|Dust Storm Warning for\.\.\.|Dust Advisory for\.\.\.|WHAT\.\.\.)/m);
  const tailStart = value.indexOf("LAT...LON");
  if (firstBullet < 0 || tailStart < 0) return;
  review.dataset.protectedEnvelope = JSON.stringify({ prefix: value.slice(0, firstBullet), tail: value.slice(tailStart) });
}

/** Restore protected generated content while retaining editable narrative. */
function restoreHazardReviewEnvelope(product, text) {
  if (!["SVR", "TOR", "FFW", "FAW", "FAY", "SQW", "DSW", "DSY"].includes(product?.code)) return { text: String(text || ""), restored: false };
  const review = document.querySelector("#hazReviewText");
  let envelope = null;
  try { envelope = JSON.parse(review?.dataset.protectedEnvelope || "null"); } catch { envelope = null; }
  if (!envelope?.prefix || !envelope?.tail) return { text: String(text || ""), restored: false };
  const value = String(text || "");
  const firstBullet = value.search(/^\* (?:Severe Thunderstorm Warning for\.\.\.|Tornado Warning for\.\.\.|Flash Flood Warning for\.\.\.|Snow Squall Warning for\.\.\.|Dust Storm Warning for\.\.\.|Dust Advisory for\.\.\.|WHAT\.\.\.)/m);
  const tailStart = value.indexOf("LAT...LON");
  if (firstBullet < 0 || tailStart < firstBullet) return { text: value, restored: false };
  const narrative = value.slice(firstBullet, tailStart);
  const restoredText = `${envelope.prefix}${narrative}${envelope.tail}`;
  return { text: restoredText, restored: restoredText !== value };
}

function setHazDraftState(state = "unsaved") {
  const host = document.querySelector("#hazDraftState");
  if (!host) return;
  const states = { new: ["New draft", "Complete the workflow, then save or review."], unsaved: ["Unsaved changes", "Save the draft before leaving this workflow."], saved: ["Draft saved", "No unsaved form changes."], ready: ["Ready for review", "Template and geometry checks passed."] };
  const [title, detail] = states[state] || states.unsaved;
  host.className = `haz-draft-state is-${state}`;
  host.querySelector("strong").textContent = title;
  host.querySelector("small").textContent = detail;
  if (state === "unsaved" && hazSelectedProduct) document.querySelector("#hazStatusBadge").textContent = "Unsaved";
  if (!workspaceSwitching && activeWorkspaceId) {
    const workspace = operationalWorkspaces.find((item) => item.id === activeWorkspaceId);
    if (workspace) {
      workspace.unsaved = state === "unsaved";
      workspace.hazard = workspace.hazard || {};
      workspace.hazard.draftState = state;
      workspace.hazard.productCode = hazSelectedProduct?.code || workspace.hazard.productCode || "";
      workspace.hazard.editorOpen = Boolean(hazSelectedProduct && !document.querySelector("#hazEditorView")?.hidden);
      renderOperationalWorkspaceTabs();
    }
  }
}

function hazardServicesChecklist(text = "") {
  const start = document.querySelector("#hazStartTime")?.value;
  const end = document.querySelector("#hazEndTime")?.value;
  const editingPolygon = hazSelectedProduct?.engine === "polygon" &&
    warnState?.status === "active" && Boolean(warnState?.warningId);
  const geometryReady = hazSelectedProduct?.engine === "zone" ? gfeSelectedZoneIds.size > 0 : Boolean(warnState?.polygon);
  const ffwDetailsReady = hazSelectedProduct?.code !== "FFW" || (document.querySelector("#hazFfwRainAmount")?.value !== "rainEdit" || Boolean(document.querySelector("#hazFfwRainCustom")?.value.trim())) && (!document.querySelector("#hazFfwAdditional")?.checked || Boolean(document.querySelector("#hazFfwAdditionalAmount")?.value.trim())) && (!document.querySelector("#hazFfwEmergency")?.checked || Boolean(document.querySelector("#hazFfwEmergencyLocation")?.value.trim()));
  const hydroGauge = hazSelectedProduct?.code === "FAY" ? warnState?.fad?.gauge : hazSelectedProduct?.code === "FAW" ? warnState?.afw?.gauge : null;
  const gaugeReady = !hydroGauge || Boolean(hydroGauge.confirmed);
  const items = [
    { label: "Valid start and expiration", ok: Boolean(start && (
      hazSelectedProduct?.engine !== "zone" && !editingPolygon ||
      end && new Date(end) > new Date(start)
    )) },
    { label: hazSelectedProduct?.engine === "zone" ? `${gfeSelectedZoneIds.size} selected zone${gfeSelectedZoneIds.size === 1 ? "" : "s"}` : "Warning polygon complete", ok: geometryReady },
    { label: "Required conditional template fields complete", ok: Boolean(hazSelectedProduct && ffwDetailsReady && gaugeReady) },
    { label: "Generated product text is complete", ok: text ? validateHazardServicesText(hazSelectedProduct, text).length === 0 : false }
  ];
  return items;
}

function renderHazInlineValidation(items) {
  const host = document.querySelector("#hazInlineValidation");
  if (!host) return;
  const failed = items.filter((item) => !item.ok);
  host.hidden = !failed.length;
  host.innerHTML = failed.length ? `<strong>Complete before review</strong><ul>${failed.map((item) => `<li>${escapeHtml(item.label)}</li>`).join("")}</ul>` : "";
}

function renderHazReviewChecklist(text) {
  const host = document.querySelector("#hazReviewChecklist");
  if (!host) return;
  const items = hazardServicesChecklist(text);
  host.innerHTML = items.map((item) => `<span class="${item.ok ? "is-ready" : "is-blocked"}"><i aria-hidden="true">${item.ok ? "✓" : "!"}</i>${escapeHtml(item.label)}</span>`).join("");
}

function renderHazIssueSummary() {
  const host = document.querySelector("#hazIssueSummary");
  if (!host || !hazSelectedProduct) return;
  const start = document.querySelector("#hazStartTime")?.value;
  const end = document.querySelector("#hazEndTime")?.value;
  const zoneNames = hazSelectedProduct.engine === "zone"
    ? [...gfeSelectedZoneIds].slice(0, 4).join(", ") + (gfeSelectedZoneIds.size > 4 ? ` +${gfeSelectedZoneIds.size - 4}` : "")
    : `${activeWfo || "—"} polygon`;
  const newestRadar = Math.max(...radarLoopFrames.map((frame) => Number(frame.timestampMs)).filter(Number.isFinite));
  const radarMinutes = Number.isFinite(newestRadar) ? Math.max(0, Math.round((Date.now() - newestRadar) / 60000)) : null;
  const radarLabel = radarMinutes == null ? "No radar time loaded" : radarMinutes > 15 ? `${radarMinutes} min old · STALE` : `${radarMinutes} min old`;
  const destinations = practiceModeEnabled ? "Ops store only" : "Public map · warning server · placefile · Mattermost";
  const rows = [
    ["Mode", practiceModeEnabled ? "PRACTICE — no external distribution" : "LIVE DISTRIBUTION"],
    ["Product", `${hazSelectedProduct.name} · ${hazSelectedProduct.code}`],
    ["Geography", zoneNames || "No area selected"],
    ["Valid", start && end ? `${start.replace("T", " ")} → ${end.replace("T", " ")}` : "Check start and expiration"],
    ["Radar", radarLabel],
    ["Destinations", destinations]
  ];
  host.className = `haz-issue-summary${practiceModeEnabled ? " is-practice" : ""}${radarMinutes != null && radarMinutes > 15 ? " has-stale-data" : ""}`;
  host.innerHTML = rows.map(([label, value]) => `<div><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></div>`).join("");
}

function initializeHazWorkflowSections() {
  const mappings = [
    ["validity", document.querySelector("#hazStartTime")?.closest(".haz-form-section")],
    ["geometry", document.querySelector("#hazPlaceStormButton")?.closest(".haz-form-section")],
    ["details", document.querySelector("#hazDetailsSection")],
    ["locations", document.querySelector('input[name="hazLocations"]')?.closest(".haz-form-section")],
    ["review", document.querySelector("#hazInlineValidation")]
  ];
  mappings.forEach(([stage, element]) => { if (element) element.dataset.hazWorkflowSection = stage; });
  [document.querySelector("#hazPolygonCtas")?.closest(".haz-form-section"), document.querySelector("#hazProductTemplateFields")]
    .filter(Boolean)
    .forEach((element) => { element.dataset.hazWorkflowSection = "details"; });
}

function setHiveBetaHazardStage(stage, { scroll = false } = {}) {
  if (!hiveBetaMode) return;
  const editor = document.querySelector("#hazEditorView");
  if (!editor || !["validity", "geometry", "details", "locations", "review"].includes(stage)) return;
  editor.dataset.hazActiveStage = stage;
  document.querySelectorAll("#hazWorkflow [data-haz-stage]").forEach((button) => {
    const active = button.dataset.hazStage === stage;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  const checklist = hazardServicesChecklist();
  const complete = { validity: checklist[0]?.ok, geometry: checklist[1]?.ok, details: checklist[2]?.ok };
  document.querySelectorAll("#hazWorkflow [data-haz-stage]").forEach((button) => {
    button.classList.toggle("is-complete", Boolean(complete[button.dataset.hazStage]));
  });
  let summary = editor.querySelector("#betaHazStageSummary");
  if (!summary) {
    summary = document.createElement("p");
    summary.id = "betaHazStageSummary";
    summary.className = "beta-haz-stage-summary";
    document.querySelector("#hazDraftState")?.after(summary);
  }
  const messages = {
    validity: "Set when the product begins and expires.",
    geometry: hazSelectedProduct?.engine === "zone" ? "Select the affected forecast zones on the map." : "Place the storm marker and confirm motion on the map.",
    details: "Set threats, source, impacts, product details, and protective actions.",
    locations: "Choose how affected locations appear in the product.",
    review: "Review validation and generated text, then use Review and issue below."
  };
  summary.textContent = messages[stage];
  if (scroll) summary.scrollIntoView?.({ behavior: "smooth", block: "start" });
}

function setHazDuration(minutes) {
  const value = Math.max(5, Math.min(360, Number(minutes) || 45));
  document.querySelector("#hazCustomDuration").value = String(value);
  if (controls.warnDuration) controls.warnDuration.value = String(value);
  if (warnState) warnState.validMinutes = value;
  const select = document.querySelector("#hazDurationSelect");
  const preset = [30, 45, 60].includes(value);
  if (select) select.value = preset ? String(value) : "custom";
  const customField = document.querySelector("#hazCustomDurationField");
  if (customField) customField.hidden = preset;
}

function setHazLifecycleMode(editing) {
  const isEditing = Boolean(editing);
  const cancelButton = document.querySelector("#hazCancelWarningButton");
  if (cancelButton) cancelButton.hidden = !isEditing;
  const reviewButton = document.querySelector("#hazReviewButton");
  if (reviewButton) reviewButton.textContent = isEditing ? "Review update" : "Review and issue";
  const endModeField = document.querySelector("#hazEndModeField");
  if (endModeField) endModeField.hidden = !isEditing;
  if (isEditing) {
    const initialEnd = hazSelectedProduct?.engine === "polygon"
      ? warnState?.expiresAt
      : gfeEditingEvent?.endTime;
    const endInput = document.querySelector("#hazEndTime");
    if (initialEnd && endInput) endInput.value = localDateTimeInputValue(new Date(initialEnd));
    if (endInput) endInput.dataset.initialEnd = endInput.value;
    setHazEndEditMode(false);
  } else if (document.querySelector("#hazEndTime")) {
    const endInput = document.querySelector("#hazEndTime");
    delete endInput.dataset.initialEnd;
    endInput.disabled = false;
  }
}

function setHazEndEditMode(allowEdit) {
  const endInput = document.querySelector("#hazEndTime");
  const endField = document.querySelector("#hazEndTimeField");
  const durationField = document.querySelector("#hazDurationField");
  const customDurationField = document.querySelector("#hazCustomDurationField");
  const editing = !document.querySelector("#hazEndModeField")?.hidden;
  if (!editing) return;
  if (endField) endField.hidden = false;
  if (durationField) durationField.hidden = true;
  if (customDurationField) customDurationField.hidden = true;
  if (endInput) {
    if (!allowEdit && endInput.dataset.initialEnd) endInput.value = endInput.dataset.initialEnd;
    endInput.disabled = !allowEdit;
  }
  document.querySelector("#hazKeepEndButton")?.classList.toggle("is-active", !allowEdit);
  document.querySelector("#hazEditEndButton")?.classList.toggle("is-active", allowEdit);
}

function hazardServicesPolygonUpdateTiming() {
  const current = new Date(warnState?.expiresAt || "");
  const endInput = document.querySelector("#hazEndTime");
  const requested = new Date(endInput?.value || endInput?.dataset.initialEnd || "");
  if (!Number.isFinite(requested.getTime())) return { error: "Enter a valid end date and time." };
  if (requested.getTime() <= Date.now()) return { error: "The end time must be in the future." };
  const action = Number.isFinite(current.getTime()) && requested.getTime() > current.getTime()
    ? "EXT"
    : "CON";
  return { action, expireAt: requested };
}

function openHazardServicesProduct(code) {
  const product = findHazardServicesProduct(code);
  if (!product) return;
  hazSelectedProduct = product;
  const hazHail = document.querySelector("#hazHail");
  if (hazHail && ![...hazHail.options].some((option) => option.value === "dvd")) hazHail.add(new Option("DVD · 5.00 in", "dvd"));
  document.querySelector("#hazCatalogView").hidden = true;
  document.querySelector("#hazEditorView").hidden = false;
  document.querySelector("#hazCategoryLabel").textContent = product.category;
  document.querySelector("#hazProductTitle").textContent = product.name;
  document.querySelector("#hazStatusBadge").textContent = "Draft";
  setHazLifecycleMode(false);
  document.querySelectorAll("#hazWorkflow [data-haz-stage]").forEach((button, index) => button.classList.toggle("is-active", index === 0));
  setHiveBetaHazardStage("validity");
  document.querySelector("#hazInlineValidation").hidden = true;
  setHazDraftState("new");
  const now = new Date();
  document.querySelector("#hazStartTime").value = localDateTimeInputValue(now);
  const geometrySection = document.querySelector("#hazPlaceStormButton").closest(".haz-form-section");
  const trackStormButton = document.querySelector("#hazTrackStormButton");
  const selectAllZonesButton = document.querySelector("#hazSelectAllZonesButton");
  const clearZonesButton = document.querySelector("#hazClearZonesButton");
  const detailsSection = document.querySelector("#hazImpactLevel").closest(".haz-form-section");
  const polygonDetails = document.querySelector("#hazPolygonDetails");
  const zoneDetails = document.querySelector("#hazZoneDetails");
  const polygonCtas = document.querySelector("#hazPolygonCtas");
  const zoneCtaNote = document.querySelector("#hazZoneCtaNote");
  document.querySelector("#hazWindField").hidden = !["SVR", "TOR"].includes(product.code);
  document.querySelector("#hazImpactField").hidden = product.code === "SVR";
  renderHazardServicesStormShape(product);
  if (product.engine === "zone") {
    renderHazardServicesPolygonTemplateFields(null);
    setGfeZoneType(product.zoneType, { clear: true });
    ensureGfeHazardSelectOptions();
    if (controls.gfeHazardSelect && GFE_HAZARDS[product.code]) controls.gfeHazardSelect.value = product.code;
    renderGfeHazardFields({ preserve: false });
    renderHazardServicesZoneFields(GFE_HAZARDS[product.code]);
    if (controls.gfeStartTime) controls.gfeStartTime.value = localDateTimeInputValue(now);
    if (controls.gfeEndTime) controls.gfeEndTime.value = localDateTimeInputValue(new Date(now.getTime() + 12 * 60 * 60_000));
    document.querySelector("#hazEndTime").value = localDateTimeInputValue(new Date(now.getTime() + 12 * 60 * 60_000));
    document.querySelector("#hazEndTimeField").hidden = false;
    document.querySelector("#hazDurationField").hidden = true;
    document.querySelector("#hazCustomDurationField").hidden = true;
    applyGfeZoneDisplay(false);
    document.querySelector("#hazPlaceStormButton").classList.remove("is-armed");
    document.querySelector("#hazPlaceStormButton").hidden = false;
    if (trackStormButton) trackStormButton.hidden = true;
    if (selectAllZonesButton) selectAllZonesButton.hidden = false;
    if (clearZonesButton) clearZonesButton.hidden = false;
    document.querySelector("#hazPlaceStormLabel").textContent = "Enable zone selection";
    document.querySelector("#hazGeometryHint").textContent = `Click complete ${product.zoneType === "fire" ? "fire-weather" : product.zoneType === "marine" ? "marine" : "public forecast"} zones in ${activeWfo}.`;
    geometrySection.querySelector(".field-grid").hidden = true;
    detailsSection.hidden = false;
    polygonDetails.hidden = true;
    zoneDetails.hidden = false;
    polygonCtas.hidden = true;
    zoneCtaNote.hidden = false;
  } else {
    applyGfeZoneDisplay(false);
    geometrySection.querySelector(".field-grid").hidden = false;
    detailsSection.hidden = false;
    polygonDetails.hidden = !["TOR", "SVR"].includes(product.code);
    zoneDetails.hidden = true;
    polygonCtas.hidden = !["TOR", "SVR"].includes(product.code);
    zoneCtaNote.hidden = true;
    renderHazardServicesPolygonTemplateFields(product);
    document.querySelector("#hazEndTimeField").hidden = true;
    document.querySelector("#hazDurationField").hidden = false;
    document.querySelector("#hazPlaceStormButton").classList.remove("is-armed");
    document.querySelector("#hazPlaceStormButton").hidden = true;
    if (selectAllZonesButton) selectAllZonesButton.hidden = true;
    if (clearZonesButton) clearZonesButton.hidden = true;
    document.querySelector("#hazPlaceStormLabel").textContent = "Drag to storm";
    const usesPlaceStorm = hazardServicesUsesPlaceStorm(product.code);
    const usesStormTrack = hazardServicesUsesStormTrack(product.code);
    if (trackStormButton) trackStormButton.hidden = !usesStormTrack;
    document.querySelector("#hazGeometryHint").textContent = usesPlaceStorm
      ? "Drag the red current-storm marker to the threat. Step back 3–4 scans and click the storm to add a blue prior position, then select Track storm."
      : "Area drawing is active. Click around the affected area, then press Enter or double-click to finish the polygon.";
    warnState = window.WarnGen.createState(activeWfo);
    warnState.product = product.engineCode || product.code;
    if (warnState.product === "FFW") warnState.ffw.family = product.ffwFamily || "convective";
    if (["SMW", "MWS"].includes(warnState.product)) {
      warnState.ugcBasis = "marine";
      warnState.smw = warnState.smw || {};
      if (warnState.product === "MWS") warnState.smw.windId = "kt30";
      // Keep default storm polygon unless operator already chose zone
      if (!warnState.smw.geometryMode) warnState.smw.geometryMode = "polygon";
    }
    warnState.validMinutes = product.duration || 45;
    if (controls.warnProductSelect) controls.warnProductSelect.value = product.engineCode || product.code;
    syncWarnFormFromState();
    setHazDuration(product.duration || 45);
    applyWarnProductUi(warnState.product);
    renderSmwGeometryModeInHazUi();
    if (["SMW", "MWS"].includes(warnState.product)) {
      applySmwGeometryMode(warnState.smw?.geometryMode || "polygon", { silent: false });
    } else {
      if (usesPlaceStorm && !warnState.location) {
        const center = map.getCenter();
        warnState.location = [center.lng, center.lat];
      }
      setWarnMode(usesPlaceStorm ? "placeStorm" : usesStormTrack ? "placeStorm" : "drawPoly");
      updateWarnMapGraphics();
    }
  }
  initializeHazWorkflowSections();
}

function hydrateHazardServicesFfwFields() {
  const locationMode = warnState?.locationMode || "cities";
  const locationChoice = document.querySelector(`input[name="hazLocations"][value="${CSS.escape(locationMode)}"]`);
  if (locationChoice) locationChoice.checked = true;
  const ffw = warnState?.ffw;
  if (!ffw) return;
  const set = (selector, value) => { const input = document.querySelector(selector); if (input && value != null) input.value = value; };
  if (ffw.family === "dam") {
    set("#hazDamCause", ffw.dam?.cause);
    set("#hazDamDamage", ffw.dam?.damageThreat);
    set("#hazDamSource", ffw.dam?.source);
    set("#hazDamName", ffw.dam?.damName);
    set("#hazDamRiver", ffw.dam?.riverName);
    set("#hazDamLocations", ffw.dam?.locations);
    set("#hazDamDetails", ffw.dam?.details);
  } else {
    set("#hazFfwDamage", ffw.damageThreat);
    set("#hazFfwExpectedRain", ffw.expectedRain);
    set("#hazFfwExpectedRainCustom", ffw.expectedRainCustom);
  }
}

function hazardServicesSourceValue(productCode, source) {
  const value = String(source || "doppler");
  if (productCode === "SVR") {
    return ({ trainedSpotters: "spotter", emergencyMgmt: "emergencyManagement", meteorologists: "doppler" })[value] || value;
  }
  if (productCode === "TOR") {
    if (["spotter", "lawEnforcement", "emergencyManagement", "public"].includes(value)) return value;
    return "doppler";
  }
  return value;
}

function hydrateHazardServicesPolygonFields() {
  if (!warnState || !hazSelectedProduct || hazSelectedProduct.engine !== "polygon") return;
  renderHazardServicesPolygonTemplateFields(hazSelectedProduct);
  const code = hazSelectedProduct.code;
  const tor = warnState.tor || {};
  const hail = code === "TOR" && Object.prototype.hasOwnProperty.call(tor, "hailId") ? tor.hailId : warnState.hailId;
  const wind = code === "TOR" && Object.prototype.hasOwnProperty.call(tor, "windId") ? tor.windId : warnState.windId;
  const originalSource = code === "TOR" ? tor.source || "doppler" : warnState.basis || "doppler";
  const source = hazardServicesSourceValue(code, originalSource);
  const sourceInput = document.querySelector(`input[name="hazSource"][value="${CSS.escape(source)}"]`);
  if (sourceInput) sourceInput.checked = true;
  const polygonDetails = document.querySelector("#hazPolygonDetails");
  if (polygonDetails) polygonDetails.dataset.loadedSource = originalSource;
  const setValue = (selector, value) => {
    const input = document.querySelector(selector);
    if (input && value != null && [...(input.options || [])].some((option) => option.value === String(value))) input.value = String(value);
  };
  setValue("#hazHail", hail || "none");
  setValue("#hazWind", wind || "none");
  if (code === "TOR") {
    const impact = tor.emergency || tor.damageThreat === "catastrophic" ? "emergency" : tor.damageThreat === "considerable" ? "considerable" : "base";
    setValue("#hazImpactLevel", impact);
  }
  setHazDuration(warnState.validMinutes || hazSelectedProduct.duration || 45);
  setValue("#hazStormShape", warnState.stormType === "line" ? "line" : "cell");
  const direction = document.querySelector("#hazMotionDirection");
  const speed = document.querySelector("#hazMotionSpeed");
  if (direction) direction.value = warnState.motionOverride?.dirText || warnState.motion?.directionText || "";
  if (speed) speed.value = warnState.motionOverride?.speedMph || warnState.motion?.speedMph || "";
  const ctas = code === "TOR" ? tor.ctas || {} : warnState.ctas || {};
  const setChecked = (selector, checked) => { const input = document.querySelector(selector); if (input) input.checked = Boolean(checked); };
  setChecked("#hazCtaPrimary", code === "TOR" ? ctas.defaultMobile : ctas.generic);
  setChecked("#hazCtaNight", ctas.nighttime);
  setChecked("#hazCtaVehicle", ctas.motorists);
  setChecked("#hazCtaReport", ctas.lawEnforcement);
}

function hydrateHazardServicesFields() {
  hydrateHazardServicesPolygonFields();
  hydrateHazardServicesFfwFields();
}

function syncHazardServicesToPolygonEngine() {
  if (!hazSelectedProduct || hazSelectedProduct.engine !== "polygon" || !warnState) return;
  const source = document.querySelector('input[name="hazSource"]:checked')?.value || "doppler";
  const impact = document.querySelector("#hazImpactLevel")?.value || "base";
  const hail = document.querySelector("#hazHail")?.value || "none";
  const wind = document.querySelector("#hazWind")?.value || "none";
  const duration = Number(document.querySelector("#hazCustomDuration")?.value) || hazSelectedProduct.duration || 45;
  syncHazardServicesTemplateMirrors();
  if (controls.warnStormType && document.querySelector("#hazStormShape")) controls.warnStormType.value = document.querySelector("#hazStormShape").value;
  setHazDuration(duration);
  if (controls.warnMotionDir) controls.warnMotionDir.value = document.querySelector("#hazMotionDirection")?.value || "";
  if (controls.warnMotionSpeed) controls.warnMotionSpeed.value = document.querySelector("#hazMotionSpeed")?.value || "";
  if (hazSelectedProduct.code === "TOR") {
    const loadedSource = document.querySelector("#hazPolygonDetails")?.dataset.loadedSource || "";
    const sourceUnchanged = source === hazardServicesSourceValue("TOR", loadedSource);
    if (controls.warnTorSource) controls.warnTorSource.value = sourceUnchanged && loadedSource ? loadedSource : source === "spotter" ? "spotter" : source;
    if (controls.warnTorHail) controls.warnTorHail.value = hail;
    if (controls.warnTorWind) controls.warnTorWind.value = wind;
    if (controls.warnTorDamageThreat) controls.warnTorDamageThreat.value = impact === "emergency" ? "catastrophic" : impact === "considerable" ? "considerable" : "base";
    if (controls.warnTorEmergency) controls.warnTorEmergency.checked = impact === "emergency";
    if (controls.warnTorCtaMobile) controls.warnTorCtaMobile.checked = document.querySelector("#hazCtaPrimary").checked;
    if (controls.warnTorCtaNight) controls.warnTorCtaNight.checked = document.querySelector("#hazCtaNight").checked;
    if (controls.warnTorCtaMotorists) controls.warnTorCtaMotorists.checked = document.querySelector("#hazCtaVehicle").checked;
    if (controls.warnTorCtaLE) controls.warnTorCtaLE.checked = document.querySelector("#hazCtaReport").checked;
  } else if (hazSelectedProduct.code === "SVR") {
    const loadedSource = document.querySelector("#hazPolygonDetails")?.dataset.loadedSource || "";
    const sourceUnchanged = source === hazardServicesSourceValue("SVR", loadedSource);
    const svrSource = sourceUnchanged && loadedSource ? loadedSource : ({ spotter: "trainedSpotters", emergencyManagement: "emergencyMgmt" })[source] || source;
    if (controls.warnBasisSelect) controls.warnBasisSelect.value = svrSource;
    if (controls.warnHailSelect) controls.warnHailSelect.value = hail;
    if (controls.warnWindSelect) controls.warnWindSelect.value = wind;
    if (controls.warnCtaGeneric) controls.warnCtaGeneric.checked = document.querySelector("#hazCtaPrimary").checked;
    if (controls.warnCtaLE) controls.warnCtaLE.checked = document.querySelector("#hazCtaReport").checked;
  } else if (hazSelectedProduct.ffwFamily === "dam") {
    warnState.ffw = {
      ...warnState.ffw,
      family: "dam",
      dam: {
        cause: document.querySelector("#hazDamCause")?.value || "dam",
        damageThreat: document.querySelector("#hazDamDamage")?.value || "base",
        source: document.querySelector("#hazDamSource")?.value || "county",
        damName: document.querySelector("#hazDamName")?.value || "",
        riverName: document.querySelector("#hazDamRiver")?.value || "",
        locations: document.querySelector("#hazDamLocations")?.value || "",
        details: document.querySelector("#hazDamDetails")?.value || ""
      }
    };
  } else if (hazSelectedProduct.code === "FFW") {
    warnState.ffw.family = "convective";
    warnState.ffw.damageThreat = document.querySelector("#hazFfwDamage")?.value || "base";
    warnState.ffw.expectedRain = document.querySelector("#hazFfwExpectedRain")?.value || "none";
    warnState.ffw.expectedRainCustom = document.querySelector("#hazFfwExpectedRainCustom")?.value || "";
    if (controls.warnFfwSource) controls.warnFfwSource.value = document.querySelector("#hazFfwSource")?.value || "doppler";
    if (controls.warnFfwRainAmount) controls.warnFfwRainAmount.value = document.querySelector("#hazFfwRainAmount")?.value || "none";
    if (controls.warnFfwRainEdit) controls.warnFfwRainEdit.value = document.querySelector("#hazFfwRainCustom")?.value || "";
    const thunder = Boolean(document.querySelector("#hazFfwThunder")?.checked);
    const occurring = Boolean(document.querySelector("#hazFfwOccurring")?.checked);
    const snowmelt = Boolean(document.querySelector("#hazFfwSnowmelt")?.checked);
    const burnScar = Boolean(document.querySelector("#hazFfwBurnScar")?.checked);
    const additional = Boolean(document.querySelector("#hazFfwAdditional")?.checked);
    const emergency = Boolean(document.querySelector("#hazFfwEmergency")?.checked) || warnState.ffw.damageThreat === "catastrophic";
    const setChecked = (selector, value) => { const input = document.querySelector(selector); if (input) input.checked = value; };
    setChecked("#warnFfwThunder", thunder);
    setChecked("#warnFfwPlainRain", !thunder);
    setChecked("#warnFfwFlash", occurring);
    setChecked("#warnFfwSnowMelt", snowmelt);
    setChecked("#warnFfwBurnScar", burnScar);
    setChecked("#warnFfwAddRain", additional);
    setChecked("#warnFfwEmergency", emergency);
    if (controls.warnFfwAddRainText) controls.warnFfwAddRainText.value = document.querySelector("#hazFfwAdditionalAmount")?.value || "";
    if (controls.warnFfwEmergencyLoc) controls.warnFfwEmergencyLoc.value = document.querySelector("#hazFfwEmergencyLocation")?.value || "";
  }
  const locationMode = document.querySelector('input[name="hazLocations"]:checked')?.value || "cities";
  warnState.locationMode = locationMode;
  const listCities = locationMode !== "pathcast";
  const listControl = hazSelectedProduct.code === "TOR" ? controls.warnTorListCities
    : hazSelectedProduct.code === "SQW" ? controls.warnSqwListLocations
      : ["DSW", "DSY"].includes(hazSelectedProduct.code) ? controls.warnDswListLocations
      : hazSelectedProduct.code === "SPS" ? controls.warnSpsListCities : null;
  if (listControl) listControl.checked = listCities;
  readWarnFormIntoState();
}

async function reviewHazardServicesProduct() {
  if (!hazSelectedProduct) return;
  const preliminary = hazardServicesChecklist();
  if (preliminary.some((item) => !item.ok && item.label !== "Generated product text is complete")) {
    renderHazInlineValidation(preliminary.filter((item) => item.label !== "Generated product text is complete"));
    return showBanner("Complete the highlighted HAZ requirements before review.");
  }
  if (hazSelectedProduct.engine === "zone") {
    if (!gfeSelectedZoneIds.size) return showBanner("Select at least one outlined zone before review.");
    syncHazardServicesZoneFields();
    if (controls.gfeStartTime) controls.gfeStartTime.value = document.querySelector("#hazStartTime").value;
    if (controls.gfeEndTime) controls.gfeEndTime.value = document.querySelector("#hazEndTime").value;
    if (gfeEditingEvent && controls.gfeActionSelect) {
      const originalEnd = new Date(gfeEditingEvent.endTime || "");
      const requestedEnd = new Date(document.querySelector("#hazEndTime").value || "");
      controls.gfeActionSelect.value =
        Number.isFinite(originalEnd.getTime()) && requestedEnd.getTime() > originalEnd.getTime()
          ? "EXT"
          : "CON";
    }
    const generatedText=generateGfeProductPreview();
    if(!generatedText)return;
    document.querySelector("#hazReviewText").value = generatedText;
  } else {
    syncHazardServicesToPolygonEngine();
    if (!warnState?.polygon) return showBanner("Drag the storm marker onto the map and finish the polygon before review.");
    await generateWarnDraft();
    if (warnState.status === "active" && warnState.warningId) {
      const timing = hazardServicesPolygonUpdateTiming();
      if (timing.error) return showBanner(timing.error);
      warnState.action = timing.action;
      warnState.expiresAt = timing.expireAt.toISOString();
      warnState.text = window.WarnGenTemplates.generateProductText(warnState, {
        now: new Date(),
        expireAt: timing.expireAt,
        keepExpire: timing.action === "CON"
      });
    }
    document.querySelector("#hazReviewText").value = warnState.text || "";
  }
  protectHazardReviewEnvelope(hazSelectedProduct, document.querySelector("#hazReviewText").value);
  const validationProblems = validateHazardServicesText(hazSelectedProduct, document.querySelector("#hazReviewText").value);
  if (validationProblems.length) { renderHazInlineValidation([{ label: `Template: ${validationProblems.join("; ")}`, ok: false }]); return showBanner(`Template check failed: ${validationProblems.join("; ")}.`); }
  renderHazInlineValidation([]);
  renderHazReviewChecklist(document.querySelector("#hazReviewText").value);
  renderHazIssueSummary();
  setHazDraftState("ready");
  document.querySelector("#hazReviewTitle").textContent = `Review ${hazSelectedProduct.name}`;
  const editing = hazSelectedProduct.engine === "zone"
    ? Boolean(gfeEditingEvent)
    : warnState?.status === "active" && Boolean(warnState?.warningId);
  const updateAction = editing && hazSelectedProduct.engine === "polygon"
    ? hazardServicesPolygonUpdateTiming().action || "CON"
    : "CON";
  document.querySelector("#hazIssueButton").textContent = editing
    ? `Publish ${updateAction} update`
    : `${practiceModeEnabled ? "Issue practice" : "Issue live"} ${hazSelectedProduct.code}`;
  document.querySelector("#hazReviewDialog").showModal();
}

function hazardServicesDraftSnapshot() {
  return {
    version: 1,
    savedAt: new Date().toISOString(),
    product: hazSelectedProduct,
    startTime: document.querySelector("#hazStartTime")?.value || "",
    endTime: document.querySelector("#hazEndTime")?.value || "",
    duration: document.querySelector("#hazCustomDuration")?.value || "",
    polygonState: hazSelectedProduct?.engine === "polygon" && warnState ? JSON.parse(JSON.stringify(warnState)) : null,
    zoneIds: hazSelectedProduct?.engine === "zone" ? [...gfeSelectedZoneIds] : [],
    zoneFields: Object.fromEntries([...document.querySelectorAll("[data-haz-zone-field]")].map((input) => [input.dataset.hazZoneField, input.value])),
    impacts: document.querySelector("#hazZoneImpacts")?.value || "",
    additionalDetails: document.querySelector("#hazZoneAdditionalDetails")?.value || ""
  };
}

function restoreHazardServicesDraft() {
  let saved;
  try { saved = JSON.parse(localStorage.getItem("zncave-haz-beta-draft") || "null"); } catch { saved = null; }
  if (!saved?.product?.code) return showBanner("No saved HAZ draft is available.");
  openHazardServicesProduct(saved.product.code);
  if (saved.startTime) document.querySelector("#hazStartTime").value = saved.startTime;
  if (saved.endTime) document.querySelector("#hazEndTime").value = saved.endTime;
  if (saved.duration) setHazDuration(saved.duration);
  if (saved.product.engine === "polygon" && saved.polygonState) {
    warnState = saved.polygonState;
    setWarnMode(warnState.polygon ? "editPoly" : "placeStorm");
    syncWarnFormFromState();
    hydrateHazardServicesFields();
    if (document.querySelector("#hazStormShape")) document.querySelector("#hazStormShape").value = warnState.stormType === "line" ? "line" : "cell";
    document.querySelectorAll("[data-haz-mirror]").forEach((mirror) => {
      const source = document.getElementById(mirror.dataset.hazMirror);
      if (!source) return;
      if (mirror.type === "checkbox" || mirror.type === "radio") mirror.checked = source.checked;
      else mirror.value = source.value;
    });
    if (saved.product.code === "FFW" && saved.polygonState.ffw) {
      const ffw = saved.polygonState.ffw;
      const setValue = (selector, value) => { const input = document.querySelector(selector); if (input && value != null) input.value = value; };
      const setChecked = (selector, value) => { const input = document.querySelector(selector); if (input) input.checked = Boolean(value); };
      setValue("#hazFfwSource", ffw.source);
      setValue("#hazFfwRainAmount", ffw.rainAmount);
      setValue("#hazFfwRainCustom", ffw.rainEditText);
      setChecked("#hazFfwThunder", ffw.withThunder);
      setChecked("#hazFfwOccurring", ffw.alreadyOccurring);
      setChecked("#hazFfwSnowmelt", ffw.snowMelt);
      setChecked("#hazFfwBurnScar", ffw.burnScar);
      setChecked("#hazFfwAdditional", ffw.addRainfall);
      setValue("#hazFfwAdditionalAmount", ffw.addRainfallText);
      setChecked("#hazFfwEmergency", ffw.emergency);
      setValue("#hazFfwEmergencyLocation", ffw.emergencyLoc);
      document.querySelector("#hazFfwRainCustomField").hidden = ffw.rainAmount !== "rainEdit";
      document.querySelector("#hazFfwAdditionalField").hidden = !ffw.addRainfall;
      document.querySelector("#hazFfwEmergencyField").hidden = !ffw.emergency;
    }
    updateWarnMapGraphics();
  } else if (saved.product.engine === "zone") {
    gfeSelectedZoneIds.clear();
    (saved.zoneIds || []).forEach((id) => gfeSelectedZoneIds.add(id));
    Object.entries(saved.zoneFields || {}).forEach(([key, value]) => {
      const input = document.querySelector(`[data-haz-zone-field="${CSS.escape(key)}"]`);
      if (input) input.value = value;
    });
    if (saved.impacts) document.querySelector("#hazZoneImpacts").value = saved.impacts;
    if (saved.additionalDetails) document.querySelector("#hazZoneAdditionalDetails").value = saved.additionalDetails;
    renderGfeSelectedZones();
  }
  document.querySelector("#hazStatusBadge").textContent = "Saved";
  setHazDraftState("saved");
  showBanner(`Resumed ${saved.product.name || saved.product.code} draft.`);
}

async function discardHazardServicesDraft() {
  setWarnMode("idle");
  warnMotionTrackDraggingIndex = -1;
  if (window.WarnGen) warnState = window.WarnGen.createState(activeWfo);
  gfeSelectedZoneIds.clear();
  applyGfeZoneDisplay(false);
  renderGfeSelectedZones();
  updateWarnMapGraphics();
  localStorage.removeItem("zncave-haz-beta-draft");
  renderHazardServicesCatalog();
  await clearWarnDraftFromServer();
  hazSelectedProduct = null;
  document.querySelector("#hazEditorView").hidden = true;
  document.querySelector("#hazCatalogView").hidden = false;
  document.querySelector("#hazStatusBadge").textContent = "Select";
  showBanner("Hazard draft discarded.");
}

function resetHazardServicesAfterAction() {
  setWarnMode("idle");
  warnMotionTrackDraggingIndex = -1;
  if (window.WarnGen) warnState = window.WarnGen.createState(activeWfo);
  selectedActiveWarningId = null;
  gfeSelectedZoneIds.clear();
  gfeEditingEvent = null;
  gfeSelectedEventId = "";
  applyGfeZoneDisplay(false);
  renderGfeSelectedZones();
  updateWarnMapGraphics();
  syncWarnFormFromState();
  localStorage.removeItem("zncave-haz-beta-draft");
  void clearWarnDraftFromServer();
  hazSelectedProduct = null;
  const reviewText = document.querySelector("#hazReviewText");
  if (reviewText) { reviewText.value = ""; delete reviewText.dataset.protectedEnvelope; }
  const reviewChecklist = document.querySelector("#hazReviewChecklist");
  if (reviewChecklist) reviewChecklist.replaceChildren();
  const editor = document.querySelector("#hazEditorView");
  const catalog = document.querySelector("#hazCatalogView");
  if (editor) editor.hidden = true;
  if (catalog) catalog.hidden = false;
  renderHazardServicesCatalog();
  setHazLifecycleMode(false);
  const statusBadge = document.querySelector("#hazStatusBadge");
  if (statusBadge) statusBadge.textContent = "Select";
  setHazDraftState("new");
}

function registerCustomZoneHazard(code, template) {
  const phen = String(code || "").trim().toUpperCase();
  if (!/^[A-Z]{2}\.[A-Z]$/.test(phen) || !template?.isCustom || !template.name) return false;
  const product = String(template.product || "NPW").toUpperCase() || "NPW";
  const zoneType = template.zoneType === "fire" || product === "RFW" ? "fire" : "public";
  const style = template.style === "rfw" || product === "RFW" ? "rfw" : "standard";
  // Default optional fields for standard / fire weather drafting
  const fields = style === "rfw"
    ? [
        ["direction", "Wind direction", "text", "west"],
        ["windMin", "Sustained wind minimum (mph)", "number"],
        ["windMax", "Sustained wind maximum (mph)", "number"],
        ["gust", "Peak gust (mph)", "number"],
        ["humidityMin", "Minimum humidity (%)", "number"],
        ["humidityMax", "Maximum humidity (%)", "number"],
        ["temperatures", "Temperatures", "text", ""],
        ["affectedArea", "Affected-area wording", "text", ""],
        ["counties", "Counties affected", "text", ""],
        ["fuels", "Fuels", "text", "critically dry"]
      ]
    : [
        ["direction", "Wind direction", "text", ""],
        ["sustained", "Sustained wind (mph)", "number"],
        ["gust", "Peak gust (mph)", "number"],
        ["temperature", "Temperature (°F)", "number"],
        ["visibility", "Visibility", "text", ""]
      ];
  GFE_HAZARDS[phen] = {
    name: String(template.name).slice(0, 80),
    product,
    color: /^#[0-9A-Fa-f]{6}$/.test(String(template.color || "")) ? template.color : "#FFA500",
    priority: Math.max(1, Math.min(999, Number(template.priority) || 200)),
    zoneType,
    fields,
    impacts: String(template.impacts || `${template.name} conditions expected.`),
    isCustom: true
  };
  // Ensure catalog entry under Custom or mapped group
  const category = product === "WSW" ? "Winter"
    : product === "RFW" ? "Fire weather"
    : product === "FFA" ? "Flood"
    : product === "CFW" ? "Coastal / lakeshore"
    : String(template.group || "Custom").trim() || "Custom";
  let group = HAZARD_SERVICES_CATALOG.find((entry) => entry.category === category);
  if (!group) {
    group = { category, products: [] };
    HAZARD_SERVICES_CATALOG.push(group);
  }
  if (!group.products.some((p) => p.code === phen)) {
    group.products.push({
      code: phen,
      name: GFE_HAZARDS[phen].name,
      engine: "zone",
      zoneType
    });
  }
  return true;
}

async function loadHazardServiceTemplateOverrides() {
  try {
    const response = await fetch("/api/ops/admin/hazard-templates", { cache: "no-store", credentials: "same-origin" });
    if (!response.ok) return;
    const data = await response.json();
    Object.entries(data.templates || {}).forEach(([code, template]) => {
      if (template?.isCustom) registerCustomZoneHazard(code, template);
      if (!GFE_HAZARDS[code]) return;
      GFE_HAZARDS[code].adminSections = template.sections || {};
      if (Number.isFinite(Number(template.priority))) GFE_HAZARDS[code].priority = Math.max(1, Math.min(999, Number(template.priority)));
      if (Array.isArray(template.fields) && (template.fields.length || template.isCustom)) {
        const configured = new Map(template.fields.filter((field) => field?.key).map((field) => [String(field.key), field]));
        // A custom product's admin field list is authoritative. Retaining the
        // generic starter fields here made unrelated wind/temperature inputs
        // appear on products such as Air Quality Alert.
        const remaining = template.isCustom
          ? []
          : (GFE_HAZARDS[code].fields || []).filter(([key]) => !configured.has(String(key)));
        GFE_HAZARDS[code].fields = [
          ...template.fields.filter((field) => field?.enabled !== false && field?.key).map((field) => [String(field.key), String(field.label || field.key), field.type === "number" ? "number" : "text", String(field.placeholder || "")]),
          ...remaining
        ];
        GFE_HAZARDS[code].adminFields = template.fields;
      }
      if (template.what) GFE_HAZARDS[code].adminWhat = template.what;
      else delete GFE_HAZARDS[code].adminWhat;
      if (template.where) GFE_HAZARDS[code].adminWhere = template.where;
      else delete GFE_HAZARDS[code].adminWhere;
      if (template.when) GFE_HAZARDS[code].adminWhen = template.when;
      else delete GFE_HAZARDS[code].adminWhen;
      if (template.impacts) {
        GFE_HAZARDS[code].impacts = template.impacts;
        GFE_HAZARDS[code].adminImpactsTemplate = template.impacts;
      } else delete GFE_HAZARDS[code].adminImpactsTemplate;
      if (template.details) GFE_HAZARDS[code].adminDetails = template.details;
      else delete GFE_HAZARDS[code].adminDetails;
      if (template.cta) GFE_HAZARDS[code].adminCta = template.cta;
      if (template.fullTemplate) GFE_HAZARDS[code].adminFullTemplate = template.fullTemplate;
      // RFW body (Red Flag / Fire Weather Watch bullet narrative)
      if (template.bodyTemplate) GFE_HAZARDS[code].adminBodyTemplate = template.bodyTemplate;
      else delete GFE_HAZARDS[code].adminBodyTemplate;
    });
    ensureGfeHazardSelectOptions();
    if (typeof renderHazardServicesCatalog === "function") renderHazardServicesCatalog();
  } catch (error) {
    console.warn("Hazard template overrides unavailable", error);
  }
}

async function initializeHazardServicesBeta() {
  await loadHazardServiceTemplateOverrides();
  ensureGfeHazardSelectOptions();
  const updateZuluClock = () => {
    const clock = document.querySelector("#zuluClock");
    const now = new Date();
    const value = `${String(now.getUTCHours()).padStart(2, "0")}:${String(now.getUTCMinutes()).padStart(2, "0")}:${String(now.getUTCSeconds()).padStart(2, "0")}Z`;
    if (clock) clock.textContent = value;
    const statusClock = document.querySelector("#opsZuluStatus");
    if (statusClock) statusClock.textContent = value;
    const cwa = document.querySelector("#opsCwaStatus");
    if (cwa) cwa.textContent = activeWfo || "—";
    const warningCount = document.querySelector("#mapActiveWarningsCount")?.textContent || "0";
    const warningStatus = document.querySelector("#opsWarningStatus");
    if (warningStatus) warningStatus.textContent = `${warningCount} active`;
    const radarStatus = document.querySelector("#opsRadarStatus");
    if (radarStatus) {
      const newest = Math.max(...radarLoopFrames.map((frame) => Number(frame.timestampMs)).filter(Number.isFinite));
      if (!Number.isFinite(newest)) radarStatus.textContent = "No loop";
      else {
        const age = Math.max(0, Math.round((Date.now() - newest) / 60000));
        radarStatus.textContent = age > 15 ? `${age}m stale` : `${age}m old`;
        radarStatus.closest(".ops-status-item")?.classList.toggle("is-alert", age > 15);
      }
    }
    const satStatus = document.querySelector("#opsSatStatus");
    if (satStatus) {
      if (!activeSatelliteLayer || activeSatelliteLayer === "none") {
        satStatus.textContent = "Off";
        satStatus.closest(".ops-status-item")?.classList.remove("is-alert");
      } else {
        const satMaps = activePanelMaps().filter((targetMap) => targetMap?.__zncaveSatelliteLayer && targetMap.__zncaveSatelliteLayer !== "none");
        const newest = Math.max(
          ...[
            ...satMaps.map((targetMap) => Number(targetMap.__zncaveDataTime)),
            ...satLoopFrames.map((frame) => Number(frame.time))
          ].filter(Number.isFinite)
        );
        const shortLabel = activeSatelliteLayer === "native"
          ? (nativeGoesSettings.product === "geocolor" ? "Native" : `B${String(nativeGoesSettings.band).padStart(2, "0")}`)
          : activeSatelliteLayer === "geocolor" || activeSatelliteLayer === "animated"
            ? (satLoopFrames.length ? `GC ${satLoopFrames.length}f` : "GeoColor")
            : activeSatelliteLayer === "abi13"
              ? (satLoopFrames.length ? `IR ${satLoopFrames.length}f` : "IR")
              : activeSatelliteLayer === "abi10"
                ? (satLoopFrames.length ? `WV ${satLoopFrames.length}f` : "WV")
                : "Sat";
        if (!Number.isFinite(newest)) satStatus.textContent = shortLabel;
        else {
          const age = Math.max(0, Math.round((Date.now() - newest) / 60000));
          satStatus.textContent = age > 20 ? `${shortLabel} ${age}m` : shortLabel;
          satStatus.closest(".ops-status-item")?.classList.toggle("is-alert", age > 20);
        }
      }
    }
  };
  updateZuluClock();
  window.setInterval(updateZuluClock, 1000);
  renderHazardServicesCatalog();
  document.querySelector("#hazWorkflow")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-haz-stage]");
    if (!button) return;
    if (hiveBetaMode) {
      setHiveBetaHazardStage(button.dataset.hazStage, { scroll: true });
      if (button.dataset.hazStage === "review") document.querySelector("#hazReviewButton")?.focus();
      return;
    }
    document.querySelectorAll("#hazWorkflow [data-haz-stage]").forEach((item) => item.classList.toggle("is-active", item === button));
    if (button.dataset.hazStage === "review") return document.querySelector("#hazReviewButton")?.focus();
    const section = document.querySelector(`[data-haz-workflow-section="${button.dataset.hazStage}"]`);
    section?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
  document.querySelector("#hazEditorView")?.addEventListener("input", (event) => {
    if (event.target.closest("button")) return;
    setHazDraftState("unsaved");
    document.querySelector("#hazInlineValidation").hidden = true;
    if (hiveBetaMode) setHiveBetaHazardStage(document.querySelector("#hazEditorView")?.dataset.hazActiveStage || "validity");
  });
  document.querySelector("#hazEditorView")?.addEventListener("change", () => {
    setHazDraftState("unsaved");
    if (hiveBetaMode) setHiveBetaHazardStage(document.querySelector("#hazEditorView")?.dataset.hazActiveStage || "validity");
  });
  document.querySelector("#hazReviewText")?.addEventListener("input", (event) => renderHazReviewChecklist(event.target.value));
  document.querySelector("#hazCategoryList")?.addEventListener("click", (event) => {
    if (event.target.closest("[data-haz-resume]")) return restoreHazardServicesDraft();
    const button = event.target.closest("[data-haz-product]");
    if (button) openHazardServicesProduct(button.dataset.hazProduct);
  });
  document.querySelector("#hazBackButton")?.addEventListener("click", () => {
    setWarnMode("idle");
    applyGfeZoneDisplay(false);
    hazSelectedProduct = null;
    document.querySelector("#hazEditorView").hidden = true;
    document.querySelector("#hazCatalogView").hidden = false;
    document.querySelector("#hazStatusBadge").textContent = "Select";
  });
  document.querySelector("#hazDurationSelect")?.addEventListener("change", (event) => {
    const custom = event.target.value === "custom";
    document.querySelector("#hazCustomDurationField").hidden = !custom;
    if (!custom) setHazDuration(event.target.value);
  });
  document.querySelector("#hazCustomDuration")?.addEventListener("input", (event) => setHazDuration(event.target.value));
  document.querySelector("#hazKeepEndButton")?.addEventListener("click", () => {
    setHazEndEditMode(false);
    setHazDraftState("unsaved");
  });
  document.querySelector("#hazEditEndButton")?.addEventListener("click", () => {
    setHazEndEditMode(true);
    document.querySelector("#hazEndTime")?.focus();
    setHazDraftState("unsaved");
  });
  document.querySelector("#hazProductTemplateFields")?.addEventListener("change", (event) => {
    if (event.target.id === "hazGaugeConfirmed") {
      const gauge = hazSelectedProduct?.code === "FAY" ? warnState?.fad?.gauge : warnState?.afw?.gauge;
      if (gauge) gauge.confirmed = event.target.checked;
      setHazDraftState("unsaved");
    }
    if (event.target.id === "hazFfwRainAmount") document.querySelector("#hazFfwRainCustomField").hidden = event.target.value !== "rainEdit";
    if (event.target.id === "hazFfwAdditional") document.querySelector("#hazFfwAdditionalField").hidden = !event.target.checked;
    if (event.target.id === "hazFfwEmergency") document.querySelector("#hazFfwEmergencyField").hidden = !event.target.checked;
    if (event.target.id === "hazFfwExpectedRain") document.querySelector("#hazFfwExpectedRainCustomField").hidden = event.target.value !== "custom";
    if (event.target.id === "hazFfwDamage" && event.target.value === "catastrophic") {
      const emergency = document.querySelector("#hazFfwEmergency");
      if (emergency) emergency.checked = true;
      const field = document.querySelector("#hazFfwEmergencyField");
      if (field) field.hidden = false;
    }
  });
  document.querySelector("#hazPlaceStormButton")?.addEventListener("click", (event) => {
    if (hazSelectedProduct?.engine === "zone") {
      const enabled = !event.currentTarget.classList.contains("is-armed");
      event.currentTarget.classList.toggle("is-armed", enabled);
      applyGfeZoneDisplay(enabled);
      if (enabled) showBanner("Zone selection enabled. Click outlined zones to add or remove them.");
      return;
    }
    if (["SMW", "MWS"].includes(hazSelectedProduct?.code) && isSmwZoneGeometryMode()) {
      const enabled = warnState?.mode !== "selectMarineZones";
      event.currentTarget.classList.toggle("is-armed", enabled);
      if (enabled) {
        applySmwGeometryMode("zone", { silent: false });
      } else {
        setWarnMode("idle");
        showBanner("Marine zone selection paused. Click the button again or use Geometry mode to resume.");
      }
      return;
    }
    const enabled = warnState?.mode !== "placeStorm";
    event.currentTarget.classList.toggle("is-armed", enabled);
    setWarnMode(enabled ? "placeStorm" : "idle");
  });
  document.querySelector("#hazTrackStormButton")?.addEventListener("click", () => {
    trackHazardServicesStorm();
  });
  document.querySelector("#hazSelectAllZonesButton")?.addEventListener("click", async (event) => {
    if (hazSelectedProduct?.engine !== "zone") return;
    event.currentTarget.disabled = true;
    let zones;
    try {
      zones = await ensureActiveGfeZoneFeatures();
    } catch (error) {
      console.warn("[hazards] select all zones", error);
      showBanner("Could not load the zone boundaries. Try again.");
      event.currentTarget.disabled = false;
      return;
    }
    zones.forEach((feature) => gfeSelectedZoneIds.add(gfeZoneFeatureId(feature)));
    const selectButton = document.querySelector("#hazPlaceStormButton");
    selectButton?.classList.add("is-armed");
    applyGfeZoneDisplay(true);
    renderGfeSelectedZones();
    setHazDraftState("unsaved");
    showBanner(`Selected all ${gfeSelectedZoneIds.size} ${gfeZoneType === "fire" ? "fire-weather" : gfeZoneType === "marine" ? "marine" : "public forecast"} zones in ${activeWfo}.`);
    event.currentTarget.disabled = false;
  });
  document.querySelector("#hazClearZonesButton")?.addEventListener("click", () => {
    if (hazSelectedProduct?.engine !== "zone") return;
    gfeSelectedZoneIds.clear();
    renderGfeSelectedZones();
    setHazDraftState("unsaved");
    showBanner("Cleared all selected zones.");
  });
  document.querySelector("#hazSaveDraftButton")?.addEventListener("click", async () => {
    try {
      if (!hazSelectedProduct) return showBanner("Choose a hazard before saving a draft.");
      if (hazSelectedProduct.engine === "polygon") {
        syncHazardServicesToPolygonEngine();
        await publishWarnDraft();
      } else {
        syncHazardServicesZoneFields();
      }
      localStorage.setItem("zncave-haz-beta-draft", JSON.stringify(hazardServicesDraftSnapshot()));
      renderHazardServicesCatalog();
      document.querySelector("#hazStatusBadge").textContent = "Saved";
      setHazDraftState("saved");
      showBanner(`${hazSelectedProduct.name} draft saved at ${new Date().toISOString().slice(11, 16)}Z.`);
    } catch (error) {
      console.error("HAZ draft save failed", error);
      showBanner(`Could not save draft: ${error.message || error}`);
    }
  });
  document.querySelector("#hazDiscardButton")?.addEventListener("click", () => { void discardHazardServicesDraft(); });
  document.querySelector("#hazCancelWarningButton")?.addEventListener("click", async () => {
    if (!hazSelectedProduct) return;
    const cancellationTarget = hazSelectedProduct.engine === "polygon" ? warnState : hazSelectedProduct;
    const cancelReason = await requestWarningCancellation(cancellationTarget, hazSelectedProduct.name);
    if (!cancelReason) return;
    let cancelled = false;
    if (hazSelectedProduct.engine === "zone") {
      if (!gfeEditingEvent) return showBanner("Load an active zone hazard before cancellation.");
      controls.gfeActionSelect.value = "CAN";
      cancelled = await issueGfeProduct();
      if (cancelled) void releaseWarningEditLock();
    } else {
      cancelled = cancelWarnProduct(cancelReason);
    }
    if (!cancelled) return;
    resetHazardServicesAfterAction();
    panelDock.classList.add("is-collapsed");
    railButtons.forEach((button) => button.classList.remove("is-active"));
    applyGfeZoneDisplay(false);
    syncDockLayout();
  });
  document.querySelector("#hazReviewButton")?.addEventListener("click", () => {
    reviewHazardServicesProduct().catch((error) => {
      console.error("HAZ review failed", error);
      showBanner(`Could not build review: ${error.message || error}`);
    });
  });
  document.querySelector("#hazReviewForm")?.addEventListener("submit", (event) => {
    if (event.submitter?.id === "hazIssueButton") event.preventDefault();
  });
  document.querySelector("#hazIssueButton")?.addEventListener("click", async (event) => {
    event.preventDefault();
    const issueButton = document.querySelector("#hazIssueButton");
    const feedback = document.querySelector("#hazIssueFeedback");
    if (issueButton?.classList.contains("is-issuing")) return;
    const idleLabel = issueButton?.textContent || "Issue";
    const productLabel = hazSelectedProduct?.code || "product";
    if (issueButton) {
      issueButton.classList.add("is-issuing");
      issueButton.disabled = true;
      issueButton.setAttribute("aria-busy", "true");
      issueButton.textContent = `Issuing ${productLabel}…`;
    }
    if (feedback) {
      feedback.hidden = false;
      feedback.className = "haz-issue-feedback is-working";
      feedback.textContent = `Issuing ${productLabel}… Do not close this window.`;
    }
    showBanner(`Issuing ${productLabel}… validating and saving the product.`);
    try {
      const reviewTextControl = document.querySelector("#hazReviewText");
      const protectedResult = restoreHazardReviewEnvelope(hazSelectedProduct, reviewTextControl.value);
      const reviewedText = protectedResult.text;
      if (protectedResult.restored) {
        reviewTextControl.value = reviewedText;
        if (feedback) {
          feedback.className = "haz-issue-feedback is-working";
          feedback.textContent = "Protected header, geometry, and IBW tags were restored. Issuing the product…";
        }
      }
      const updatingActiveWarning = hazSelectedProduct?.engine === "polygon" && warnState?.status === "active" && Boolean(warnState.warningId);
      if (!reviewedText.trim()) {
        if (feedback) { feedback.className = "haz-issue-feedback is-error"; feedback.textContent = "Cannot issue: warning text is empty."; }
        return showBanner("Warning text cannot be empty.");
      }
      const validationProblems = validateHazardServicesText(hazSelectedProduct, reviewedText);
      if (validationProblems.length) {
        const message = `Cannot issue: ${validationProblems.join("; ")}.`;
        if (feedback) { feedback.className = "haz-issue-feedback is-error"; feedback.textContent = message; }
        return showBanner(message);
      }
      let issued = false;
      if (hazSelectedProduct?.engine === "zone") {
        if (controls.gfeProductText) controls.gfeProductText.value = reviewedText;
        issued = await issueGfeProduct({ textOverride: reviewedText });
      } else if (updatingActiveWarning) {
        const timing = hazardServicesPolygonUpdateTiming();
        if (timing.error) return showBanner(timing.error);
        issued = await updateWarnProduct(timing.action, {
          expireAt: timing.expireAt,
          textOverride: reviewedText
        });
      } else {
        issued = await issueWarnProduct({ textOverride: reviewedText, startTime: document.querySelector("#hazStartTime")?.value });
      }
      if (!issued) {
        if (feedback) { feedback.className = "haz-issue-feedback is-error"; feedback.textContent = "Issuance stopped. Review the message shown here and correct the product."; }
        return;
      }
      // Hazard Services may be closed while the radar is pinned on an older
      // tracking frame. Restore the operational display to the newest scan
      // before leaving the editor.
      returnToLatestRadarScan();
      document.querySelector("#hazReviewDialog").close();
      resetHazardServicesAfterAction();
      panelDock.classList.add("is-collapsed");
      railButtons.forEach((button) => button.classList.remove("is-active"));
      applyGfeZoneDisplay(false);
      syncDockLayout();
    } catch (error) {
      console.error("HAZ issue failed", error);
      if (feedback) { feedback.className = "haz-issue-feedback is-error"; feedback.textContent = `Issue failed: ${error.message || error}`; }
      showBanner(`Issue failed: ${error.message || error}`);
    } finally {
      if (issueButton) {
        issueButton.classList.remove("is-issuing");
        issueButton.disabled = false;
        issueButton.removeAttribute("aria-busy");
        issueButton.textContent = idleLabel;
      }
    }
  });
}

void initializeHazardServicesBeta();

// NHC tropical forecast authoring. This is intentionally independent from
// WarnGen/GFE/HAZ; it creates a forecast track and derived uncertainty cone.
const NHC_FORECAST_HOURS = [0, 6, 12, 24, 36, 48, 72, 96, 120, 144];
const NHC_CONE_RADIUS_NM = { 0: 0, 6: 18, 12: 26, 24: 41, 36: 55, 48: 69, 72: 99, 96: 127, 120: 151, 144: 175 };
const NHC_EMPTY = { type: "FeatureCollection", features: [] };
let nhcTracksEnabled = true;
/** In-session NHC editor draft only — durable saves go to shared server desk. */
let nhcEditorDraft = null;

function nhcForecastRows() {
  const rows = NHC_FORECAST_HOURS.map((hour) => {
    const prefix = hour === 0 ? "OBS" : `F${String(hour).padStart(3, "0")}`;
    const obsClass = hour === 0 ? " is-obs" : "";
    return `<div class="nhc-forecast-row${obsClass}" data-nhc-hour="${hour}">
      <strong title="${hour === 0 ? "Observed position" : `Forecast hour ${hour}`}">${prefix}</strong>
      <label><span>Lat</span><input type="number" step="0.1" min="-90" max="90" inputmode="decimal" placeholder="°N" data-nhc-lat="${hour}" aria-label="${prefix} latitude"></label>
      <label><span>Lon</span><input type="number" step="0.1" min="-180" max="180" inputmode="decimal" placeholder="°E" data-nhc-lon="${hour}" aria-label="${prefix} longitude"></label>
      <label><span>Wind</span><input type="number" step="5" min="0" max="200" inputmode="numeric" placeholder="kt" data-nhc-wind="${hour}" aria-label="${prefix} wind in knots"></label>
      <span class="nhc-wind-chip is-empty" data-nhc-class="${hour}" title="Saffir–Simpson class from wind">—</span>
    </div>`;
  }).join("");
  return `<div class="nhc-forecast-columns" aria-hidden="true"><span>Hour</span><span>Lat</span><span>Lon</span><span>Wind kt</span><span>Class</span></div>${rows}`;
}

function nhcUpdateRowState(hour) {
  const row = document.querySelector(`.nhc-forecast-row[data-nhc-hour="${hour}"]`);
  if (!row) return;
  const lat = document.querySelector(`[data-nhc-lat="${hour}"]`)?.value.trim() || "";
  const lon = document.querySelector(`[data-nhc-lon="${hour}"]`)?.value.trim() || "";
  const windRaw = document.querySelector(`[data-nhc-wind="${hour}"]`)?.value.trim() || "";
  const filled = lat !== "" && lon !== "";
  row.classList.toggle("is-filled", filled);
  const chip = row.querySelector(`[data-nhc-class="${hour}"]`);
  if (!chip) return;
  if (windRaw === "" || !Number.isFinite(Number(windRaw))) {
    chip.textContent = "—";
    chip.className = "nhc-wind-chip is-empty";
    chip.style.background = "";
    chip.style.color = "";
    return;
  }
  const classification = nhcStormClass(Number(windRaw));
  chip.textContent = classification.short;
  chip.className = "nhc-wind-chip";
  chip.style.background = classification.color;
  chip.style.color = Number(windRaw) >= 64 && Number(windRaw) < 96 ? "#111" : "#0b1220";
  chip.title = `${classification.label} · ${windRaw} kt`;
}

function nhcUpdateTrackStats() {
  const points = nhcReadForecast();
  const stats = document.querySelector("#nhcTrackStats");
  if (stats) {
    if (!points.length) stats.textContent = "0 positions";
    else stats.textContent = `${points.length} pos · thru F${String(points.at(-1).hour).padStart(3, "0")}`;
  }
}

let nhcAutoGenerateTimer = 0;
function nhcScheduleAutoGenerate() {
  window.clearTimeout(nhcAutoGenerateTimer);
  nhcAutoGenerateTimer = window.setTimeout(() => {
    const points = nhcReadForecast();
    if (points.length >= 2 && points[0].hour === 0) {
      nhcGenerateForecast({ fit: false, silent: true });
    } else {
      nhcUpdateTrackStats();
    }
  }, 450);
}

function nhcReadForecast() {
  return NHC_FORECAST_HOURS.map((hour) => {
    const latValue = document.querySelector(`[data-nhc-lat="${hour}"]`)?.value.trim() || "";
    const lonValue = document.querySelector(`[data-nhc-lon="${hour}"]`)?.value.trim() || "";
    const windValue = document.querySelector(`[data-nhc-wind="${hour}"]`)?.value.trim() || "";
    return { hour, lat: latValue === "" ? NaN : Number(latValue), lon: lonValue === "" ? NaN : Number(lonValue), wind: windValue === "" ? 0 : Number(windValue) };
  }).filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lon) && point.lat >= -90 && point.lat <= 90 && point.lon >= -180 && point.lon <= 180);
}

function nhcStormClass(wind) {
  if (wind >= 137) return { label: "Category 5", short: "C5", color: "#a855f7" };
  if (wind >= 113) return { label: "Category 4", short: "C4", color: "#e879f9" };
  if (wind >= 96) return { label: "Category 3", short: "C3", color: "#ef4444" };
  if (wind >= 83) return { label: "Category 2", short: "C2", color: "#fb923c" };
  if (wind >= 64) return { label: "Category 1", short: "C1", color: "#facc15" };
  if (wind >= 34) return { label: "Tropical storm", short: "TS", color: "#22d3ee" };
  return { label: "Tropical depression", short: "TD", color: "#38bdf8" };
}

function nhcBuildGeoJson(points, meta = {}) {
  const rawLine = turf.lineString(points.map((point) => [point.lon, point.lat]));
  const smoothed = points.length > 2 ? turf.bezierSpline(rawLine, { resolution: Math.max(6000, points.length * 1200), sharpness: 0.82 }) : rawLine;
  const line = turf.feature(smoothed.geometry, { kind: "track" });
  const stormName =
    String(meta.name || document.querySelector("#nhcStormName")?.value || "")
      .trim()
      .toUpperCase() || "UNNAMED";
  const initialValue = meta.initialTime || document.querySelector("#nhcInitialTime")?.value || "";
  const initialTime = initialValue ? new Date(`${initialValue}:00Z`) : null;
  const pointFeatures = points.map((point) => {
    const classification = nhcStormClass(point.wind || 0);
    const valid = initialTime && !Number.isNaN(initialTime.getTime()) ? new Date(initialTime.getTime() + point.hour * 3600_000) : null;
    const zuluLabel = valid ? `${String(valid.getUTCDate()).padStart(2, "0")}/${String(valid.getUTCHours()).padStart(2, "0")}Z` : `${point.hour === 0 ? "OBS" : `F${String(point.hour).padStart(3, "0")}`}`;
    const localLabel = valid ? valid.toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit", timeZoneName: "short" }) : zuluLabel;
    const label = point.hour === 0 ? `${stormName} · OBS ${localLabel} (${zuluLabel})` : `${localLabel} (${zuluLabel}) · F${String(point.hour).padStart(3, "0")} · ${classification.short}`;
    return turf.point([point.lon, point.lat], { kind: "forecast-point", hour: point.hour, wind: point.wind || 0, classification: classification.label, color: classification.color, label });
  });
  const totalLength = Math.max(0.001, turf.length(line, { units: "nauticalmiles" }));
  const rawDistances = [0];
  for (let index = 1; index < points.length; index += 1) rawDistances.push(rawDistances[index - 1] + turf.distance([points[index - 1].lon, points[index - 1].lat], [points[index].lon, points[index].lat], { units: "nauticalmiles" }));
  const rawTotal = Math.max(0.001, rawDistances.at(-1));
  const samples = Math.max(36, points.length * 10);
  const left = [], right = [];
  let finalBearing = 0;
  for (let index = 0; index <= samples; index += 1) {
    const fraction = index / samples;
    const distance = totalLength * fraction;
    const center = turf.along(line, distance, { units: "nauticalmiles" }).geometry.coordinates;
    const before = turf.along(line, Math.max(0, distance - totalLength / samples), { units: "nauticalmiles" }).geometry.coordinates;
    const after = turf.along(line, Math.min(totalLength, distance + totalLength / samples), { units: "nauticalmiles" }).geometry.coordinates;
    const bearing = turf.bearing(before, after);
    finalBearing = bearing;
    const rawDistance = rawTotal * fraction;
    let segment = 0;
    while (segment < rawDistances.length - 2 && rawDistances[segment + 1] < rawDistance) segment += 1;
    const segmentSpan = Math.max(0.001, rawDistances[segment + 1] - rawDistances[segment]);
    const segmentFraction = Math.max(0, Math.min(1, (rawDistance - rawDistances[segment]) / segmentSpan));
    const radiusA = NHC_CONE_RADIUS_NM[points[segment].hour] ?? points[segment].hour * 1.25;
    const radiusB = NHC_CONE_RADIUS_NM[points[segment + 1].hour] ?? points[segment + 1].hour * 1.25;
    const radius = radiusA + (radiusB - radiusA) * segmentFraction;
    left.push(turf.destination(center, radius, bearing - 90, { units: "nauticalmiles" }).geometry.coordinates);
    right.push(turf.destination(center, radius, bearing + 90, { units: "nauticalmiles" }).geometry.coordinates);
  }
  const finalPoint = line.geometry.coordinates.at(-1);
  const finalRadius = NHC_CONE_RADIUS_NM[points.at(-1).hour] ?? points.at(-1).hour * 1.25;
  const endCap = [];
  for (let angle = -75; angle <= 75; angle += 15) endCap.push(turf.destination(finalPoint, finalRadius, finalBearing + angle, { units: "nauticalmiles" }).geometry.coordinates);
  const ring = [...left, ...endCap, ...right.reverse(), left[0]];
  const features = [turf.polygon([ring], { kind: "cone" }), line, ...pointFeatures];
  return { type: "FeatureCollection", features };
}

function nhcGraticuleSpacing(zoom) {
  if (zoom < 3) return 10;
  if (zoom < 4) return 5;
  if (zoom < 5) return 2;
  if (zoom < 6) return 1;
  if (zoom < 7) return 0.5;
  if (zoom < 8) return 0.2;
  return 0.1;
}

function nhcCoordinateLabel(value, spacing, axis) {
  const decimals = spacing < 1 ? 1 : 0;
  const normalized = Math.abs(value) < spacing / 100 ? 0 : value;
  return `${normalized.toFixed(decimals)}°${axis}`;
}

function nhcGraticuleGeoJson(targetMap) {
  const bounds = targetMap.getBounds();
  const spacing = nhcGraticuleSpacing(targetMap.getZoom());
  const south = Math.max(-85, bounds.getSouth());
  const north = Math.min(85, bounds.getNorth());
  let west = bounds.getWest();
  let east = bounds.getEast();
  if (east < west) east += 360;
  const features = [];
  const firstLon = Math.ceil(west / spacing) * spacing;
  for (let lon = firstLon; lon <= east + spacing / 100; lon += spacing) {
    const wrapped = ((lon + 180) % 360 + 360) % 360 - 180;
    features.push(turf.lineString([[wrapped, south], [wrapped, north]], { label: nhcCoordinateLabel(wrapped, spacing, "") }));
  }
  const firstLat = Math.ceil(south / spacing) * spacing;
  for (let lat = firstLat; lat <= north + spacing / 100; lat += spacing) {
    features.push(turf.lineString([[west, lat], [east, lat]], { label: nhcCoordinateLabel(lat, spacing, "") }));
  }
  return { type: "FeatureCollection", features };
}

function updateNhcGraticule(targetMap) {
  const visible = nhcGraticuleEnabled && ((nhcTracksEnabled && nhcReadForecast().length >= 2) || (nhcGuidanceEnabled && Boolean(nhcGuidanceData?.features?.length)));
  ["nhc-graticule-lines", "nhc-graticule-labels"].forEach((id) => {
    if (targetMap?.getLayer(id)) targetMap.setLayoutProperty(id, "visibility", visible ? "visible" : "none");
  });
  if (visible) targetMap?.getSource("nhc-graticule")?.setData(nhcGraticuleGeoJson(targetMap));
}

function ensureNhcGraticule(targetMap) {
  if (!targetMap?.getStyle()) return;
  if (!targetMap.getSource("nhc-graticule")) targetMap.addSource("nhc-graticule", { type: "geojson", data: NHC_EMPTY });
  if (!targetMap.getLayer("nhc-graticule-lines")) targetMap.addLayer({ id: "nhc-graticule-lines", type: "line", source: "nhc-graticule", paint: { "line-color": "#cbd5e1", "line-opacity": 0.34, "line-width": 0.8 } });
  if (!targetMap.getLayer("nhc-graticule-labels")) targetMap.addLayer({ id: "nhc-graticule-labels", type: "symbol", source: "nhc-graticule", layout: { "symbol-placement": "line", "symbol-spacing": 260, "text-field": ["get", "label"], "text-size": ["interpolate", ["linear"], ["zoom"], 3, 9, 8, 11], "text-allow-overlap": false, "text-ignore-placement": false }, paint: { "text-color": "#f8fafc", "text-halo-color": "#111827", "text-halo-width": 1.5 } });
  if (!targetMap.__zncaveNhcGraticuleBound) {
    targetMap.__zncaveNhcGraticuleBound = true;
    targetMap.on("moveend", () => updateNhcGraticule(targetMap));
  }
  updateNhcGraticule(targetMap);
}

function ensureNhcLayers(targetMap) {
  if (!targetMap?.getStyle()) return;
  if (!targetMap.getSource("nhc-forecast")) targetMap.addSource("nhc-forecast", { type: "geojson", data: NHC_EMPTY });
  if (!targetMap.getLayer("nhc-cone-fill")) targetMap.addLayer({ id: "nhc-cone-fill", type: "fill", source: "nhc-forecast", filter: ["==", ["get", "kind"], "cone"], paint: { "fill-color": "#f8fafc", "fill-opacity": 0.18 } });
  if (!targetMap.getLayer("nhc-cone-line")) targetMap.addLayer({ id: "nhc-cone-line", type: "line", source: "nhc-forecast", filter: ["==", ["get", "kind"], "cone"], layout: { "line-join": "round", "line-cap": "round" }, paint: { "line-color": "#e2e8f0", "line-opacity": 0.92, "line-width": ["interpolate", ["linear"], ["zoom"], 3, 1.4, 8, 2.4] } });
  if (!targetMap.getLayer("nhc-track-casing")) targetMap.addLayer({ id: "nhc-track-casing", type: "line", source: "nhc-forecast", filter: ["==", ["get", "kind"], "track"], layout: { "line-join": "round", "line-cap": "round" }, paint: { "line-color": "#111827", "line-opacity": 0.9, "line-width": ["interpolate", ["linear"], ["zoom"], 3, 3.8, 8, 6] } });
  if (!targetMap.getLayer("nhc-track-line")) targetMap.addLayer({ id: "nhc-track-line", type: "line", source: "nhc-forecast", filter: ["==", ["get", "kind"], "track"], layout: { "line-join": "round", "line-cap": "round" }, paint: { "line-color": "#f8fafc", "line-width": ["interpolate", ["linear"], ["zoom"], 3, 1.8, 8, 3] } });
  if (!targetMap.getLayer("nhc-track-points")) targetMap.addLayer({ id: "nhc-track-points", type: "circle", source: "nhc-forecast", filter: ["==", ["get", "kind"], "forecast-point"], paint: { "circle-radius": ["interpolate", ["linear"], ["zoom"], 3, 5, 8, 8], "circle-color": ["get", "color"], "circle-stroke-color": "#111827", "circle-stroke-width": 2, "circle-opacity": 0.98 } });
  if (!targetMap.getLayer("nhc-track-labels")) targetMap.addLayer({ id: "nhc-track-labels", type: "symbol", source: "nhc-forecast", minzoom: 5.25, filter: ["==", ["get", "kind"], "forecast-point"], layout: { "text-field": ["get", "label"], "text-size": ["interpolate", ["linear"], ["zoom"], 5.25, 10, 8, 12], "text-offset": [0, 1.25], "text-anchor": "top", "text-allow-overlap": false, "text-padding": 5, visibility: document.querySelector("#nhcShowLabels")?.checked === false ? "none" : "visible" }, paint: { "text-color": "#ffffff", "text-halo-color": "#111827", "text-halo-width": 1.8 } });
  ensureNhcGraticule(targetMap);
  setNhcLayerVisibility(targetMap);
}

function setNhcLayerVisibility(targetMap) {
  const visibility = nhcTracksEnabled ? "visible" : "none";
  ["nhc-cone-fill", "nhc-cone-line", "nhc-track-casing", "nhc-track-line", "nhc-track-points"].forEach((id) => {
    if (targetMap?.getLayer(id)) targetMap.setLayoutProperty(id, "visibility", visibility);
  });
  if (targetMap?.getLayer("nhc-track-labels")) targetMap.setLayoutProperty("nhc-track-labels", "visibility", nhcTracksEnabled && document.querySelector("#nhcShowLabels")?.checked !== false ? "visible" : "none");
  updateNhcGraticule(targetMap);
  updateNhcLegendVisibility();
}

function nhcPointsFromSnapshot(snapshot) {
  if (!snapshot || !Array.isArray(snapshot.points)) return [];
  return snapshot.points
    .map((point) => ({
      hour: Number(point.hour),
      lat: point.lat === "" || point.lat == null ? NaN : Number(point.lat),
      lon: point.lon === "" || point.lon == null ? NaN : Number(point.lon),
      wind: point.wind === "" || point.wind == null ? 0 : Number(point.wind)
    }))
    .filter(
      (point) =>
        Number.isFinite(point.hour) &&
        Number.isFinite(point.lat) &&
        Number.isFinite(point.lon) &&
        point.lat >= -90 &&
        point.lat <= 90 &&
        point.lon >= -180 &&
        point.lon <= 180
    )
    .sort((a, b) => a.hour - b.hour);
}

function nhcPaintPointsOnMap(points, options = {}) {
  if (!points || points.length < 2 || points[0].hour !== 0) return null;
  let data;
  try {
    data = nhcBuildGeoJson(points, {
      name: options.name,
      initialTime: options.initialTime
    });
  } catch (error) {
    console.warn("[nhc] cone build failed", error);
    return null;
  }
  activePanelMaps().forEach((targetMap) => {
    ensureNhcLayers(targetMap);
    targetMap.getSource("nhc-forecast")?.setData(data);
    setNhcLayerVisibility(targetMap);
  });
  scheduleLayerStackApply();
  if (options.fit) {
    try {
      const bounds = turf.bbox(data);
      panelMap()?.fitBounds([[bounds[0], bounds[1]], [bounds[2], bounds[3]]], {
        padding: 70,
        duration: 700,
        maxZoom: 7
      });
    } catch { /* ignore fit errors */ }
  }
  return data;
}

/**
 * When ZWS-NHC Tracks is on, paint the cone without requiring the NHC panel.
 * Prefers form → local draft → shared desk cache → server fetch.
 */
async function ensureNhcZwsTracksOnMap(options = {}) {
  if (!nhcTracksEnabled) {
    activePanelMaps().forEach((targetMap) => {
      ensureNhcLayers(targetMap);
      setNhcLayerVisibility(targetMap);
    });
    return false;
  }

  // Already have track geometry on the primary map.
  try {
    const primary = panelMap() || map;
    const source = primary?.getSource?.("nhc-forecast");
    const existing = source?._data;
    if (existing?.features?.length >= 2) {
      activePanelMaps().forEach((targetMap) => {
        ensureNhcLayers(targetMap);
        if (targetMap !== primary && existing) {
          targetMap.getSource("nhc-forecast")?.setData(existing);
        }
        setNhcLayerVisibility(targetMap);
      });
      scheduleLayerStackApply();
      return true;
    }
  } catch { /* fall through and rebuild */ }

  let points = nhcReadForecast();
  let meta = {
    name: document.querySelector("#nhcStormName")?.value || "",
    initialTime: document.querySelector("#nhcInitialTime")?.value || ""
  };

  if (points.length < 2) {
    try {
      const draft = nhcEditorDraft;
      const draftPoints = nhcPointsFromSnapshot(draft);
      if (draftPoints.length >= 2) {
        points = draftPoints;
        meta = { name: draft.name || "", initialTime: draft.initialTime || "" };
        // Keep editor in sync when painting from draft
        if (document.querySelector("#nhcForecastTable") && !nhcReadForecast().length) {
          try {
            nhcApplySnapshot(draft);
          } catch { /* ignore */ }
        }
      }
    } catch { /* ignore */ }
  }

  if (points.length < 2) {
    if (!nhcForecastCache.length && !options.skipFetch) {
      try {
        await loadNhcForecastsFromBackend({ skipMigrate: true });
      } catch (error) {
        console.warn("[nhc] could not load shared forecasts for map", error);
      }
    }
    const shared = [...(nhcForecastCache || [])].sort((a, b) =>
      String(b.updatedAt || b.savedAt || "").localeCompare(String(a.updatedAt || a.savedAt || ""))
    )[0];
    const sharedPoints = nhcPointsFromSnapshot(shared);
    if (sharedPoints.length >= 2) {
      points = sharedPoints;
      meta = { name: shared.name || "", initialTime: shared.initialTime || "" };
    }
  }

  if (points.length < 2) {
    activePanelMaps().forEach((targetMap) => {
      ensureNhcLayers(targetMap);
      setNhcLayerVisibility(targetMap);
    });
    if (!options.silent) {
      showBanner("ZWS-NHC Tracks is on, but no track is loaded. Open NHC and save a forecast, or load one from the shared desk.");
    }
    return false;
  }

  const painted = nhcPaintPointsOnMap(points, {
    name: meta.name,
    initialTime: meta.initialTime,
    fit: Boolean(options.fit)
  });
  return Boolean(painted);
}

function ensureNhcGuidanceLayers(targetMap) {
  if (!targetMap?.getStyle()) return;
  if (!targetMap.getSource("nhc-guidance")) targetMap.addSource("nhc-guidance", { type: "geojson", data: NHC_EMPTY });
  if (!targetMap.getLayer("nhc-guidance-casing")) targetMap.addLayer({ id: "nhc-guidance-casing", type: "line", source: "nhc-guidance", layout: { "line-join": "round", "line-cap": "round" }, paint: { "line-color": "#0b0f14", "line-opacity": Math.min(.55, nhcGuidanceOpacity / 100), "line-width": ["interpolate", ["linear"], ["zoom"], 3, 1.5, 8, 3.2] } });
  if (!targetMap.getLayer("nhc-guidance-lines")) targetMap.addLayer({ id: "nhc-guidance-lines", type: "line", source: "nhc-guidance", layout: { "line-join": "round", "line-cap": "round" }, paint: { "line-color": ["get", "color"], "line-opacity": nhcGuidanceOpacity / 100, "line-width": ["interpolate", ["linear"], ["zoom"], 3, .8, 8, 1.8] } });
  ensureNhcGraticule(targetMap);
  setNhcGuidanceVisibility(targetMap);
}

function nhcOfficialColorExpression(product) {
  if (product === "cone") return "#ffffff";
  if (product === "track" || product === "history") return product === "track" ? "#ffffff" : "#38bdf8";
  if (product === "radii") return ["case", ["in", "64", ["downcase", ["get", "name"]]], "#ef4444", ["in", "50", ["downcase", ["get", "name"]]], "#fb923c", "#facc15"];
  if (product === "warnings") return ["case", ["in", "hurricane warning", ["downcase", ["get", "name"]]], "#ef4444", ["in", "hurricane watch", ["downcase", ["get", "name"]]], "#f472b6", ["in", "tropical storm warning", ["downcase", ["get", "name"]]], "#3b82f6", "#facc15"];
  if (product.startsWith("arrival")) return product === "arrival-earliest" ? "#c084fc" : "#22d3ee";
  return "#e2e8f0";
}

function ensureNhcOfficialLayers(targetMap, product) {
  const sourceId = `nhc-official-${product}`;
  if (!targetMap.getSource(sourceId)) targetMap.addSource(sourceId, { type: "geojson", data: NHC_EMPTY });
  const color = nhcOfficialColorExpression(product);
  if (!targetMap.getLayer(`${sourceId}-fill`)) targetMap.addLayer({ id: `${sourceId}-fill`, type: "fill", source: sourceId, filter: ["==", ["geometry-type"], "Polygon"], paint: { "fill-color": color, "fill-opacity": product === "cone" ? 0.16 : 0.24 } });
  if (!targetMap.getLayer(`${sourceId}-line`)) targetMap.addLayer({ id: `${sourceId}-line`, type: "line", source: sourceId, paint: { "line-color": color, "line-opacity": 0.95, "line-width": ["interpolate", ["linear"], ["zoom"], 3, 1.3, 8, 2.8] } });
  if (!targetMap.getLayer(`${sourceId}-point`)) targetMap.addLayer({ id: `${sourceId}-point`, type: "circle", source: sourceId, filter: ["==", ["geometry-type"], "Point"], paint: { "circle-color": color, "circle-radius": ["interpolate", ["linear"], ["zoom"], 3, 4, 8, 7], "circle-stroke-color": "#111827", "circle-stroke-width": 1.5 } });
  if (!targetMap.getLayer(`${sourceId}-label`)) targetMap.addLayer({ id: `${sourceId}-label`, type: "symbol", source: sourceId, minzoom: 4.5, layout: { "text-field": ["get", "name"], "text-size": 10, "text-offset": [0, 1.1], "text-anchor": "top", "text-allow-overlap": false }, paint: { "text-color": "#ffffff", "text-halo-color": "#111827", "text-halo-width": 1.4 } });
}

function setNhcOfficialVisibility(targetMap, product, visible = nhcOfficialEnabled[product]) {
  ["fill", "line", "point", "label"].forEach((suffix) => { const id = `nhc-official-${product}-${suffix}`; if (targetMap?.getLayer(id)) targetMap.setLayoutProperty(id, "visibility", visible ? "visible" : "none"); });
}

async function loadNhcOfficialProduct(product) {
  if (!nhcOfficialStorm) throw new Error("Select an active NHC storm first");
  const response = await fetch(`/api/nhc/official?storm=${encodeURIComponent(nhcOfficialStorm)}&product=${encodeURIComponent(product)}`, { cache: "no-store" });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.detail || data.error || `HTTP ${response.status}`);
  activePanelMaps().forEach((targetMap) => { ensureNhcOfficialLayers(targetMap, product); targetMap.getSource(`nhc-official-${product}`)?.setData(data); setNhcOfficialVisibility(targetMap, product, true); });
  scheduleLayerStackApply();
  renderLayerControls();
  showBanner(`Official NHC ${product.replaceAll("-", " ")} · ${data.storm?.name || nhcOfficialStorm.toUpperCase()} advisory ${data.storm?.advisory || ""}.`);
}

async function loadNhcOfficialCatalog() {
  const response = await fetch("/api/nhc/official?catalog=1", { cache: "no-store" });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.detail || data.error || `HTTP ${response.status}`);
  nhcOfficialStorms = data.storms || [];
  if (!nhcOfficialStorm && nhcOfficialStorms.length === 1) nhcOfficialStorm = nhcOfficialStorms[0].id;
  if (nhcOfficialStorm && userPrefsReady) schedulePreferencesSave();
  renderLayerControls();
  await Promise.all(nhcOfficialProducts.filter((product) => nhcOfficialEnabled[product]).map((product) => loadNhcOfficialProduct(product).catch((error) => console.warn(`Official NHC ${product} load failed`, error))));
}

function setNhcGuidanceVisibility(targetMap) {
  const visibility = nhcGuidanceEnabled && nhcGuidanceStorm && nhcGuidanceData?.features?.length ? "visible" : "none";
  ["nhc-guidance-casing", "nhc-guidance-lines"].forEach((id) => { if (targetMap?.getLayer(id)) targetMap.setLayoutProperty(id, "visibility", visibility); });
  updateNhcGraticule(targetMap);
}

async function loadNhcGuidanceCatalog() {
  const response = await fetch("/api/nhc/guidance/catalog", { cache: "no-store" });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  nhcGuidanceCatalog = (await response.json()).storms || [];
  if (nhcGuidanceStorm && !nhcGuidanceCatalog.includes(nhcGuidanceStorm)) nhcGuidanceStorm = "";
  renderLayerControls();
  if (nhcGuidanceEnabled && nhcGuidanceStorm) await loadNhcGuidance();
}

async function loadNhcGuidance() {
  if (!nhcGuidanceStorm) throw new Error("Select an ATCF storm first");
  const response = await fetch(`/api/nhc/guidance?storm=${encodeURIComponent(nhcGuidanceStorm)}`, { cache: "no-store" });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.detail || data.error || `HTTP ${response.status}`);
  nhcGuidanceData = data;
  if (data.stormName) nhcGuidanceNames.set(nhcGuidanceStorm, data.stormName);
  activePanelMaps().forEach((targetMap) => { ensureNhcGuidanceLayers(targetMap); targetMap.getSource("nhc-guidance")?.setData(data); setNhcGuidanceVisibility(targetMap); });
  scheduleLayerStackApply();
  renderLayerControls();
  updateNhcLegendVisibility();
  showBanner(`${data.stormName ? `${data.stormName} · ` : ""}${nhcGuidanceStorm.toUpperCase()}: ${data.modelCount || data.features?.length || 0} guidance tracks · cycle ${data.cycle || "unknown"}Z.`);
  return data;
}

function updateNhcLegendVisibility(hasForecast = null) {
  activePanelMaps().forEach((targetMap) => updateNhcGraticule(targetMap));
  renderRadarLegend();
}

function nhcGenerateForecast(options = {}) {
  const points = nhcReadForecast();
  if (points.length < 2 || points[0].hour !== 0) {
    if (!options.silent) showBanner("Enter an OBS position and at least one forecast position.");
    nhcUpdateTrackStats();
    return null;
  }
  nhcTracksEnabled = true;
  nhcEditorDraft = nhcSnapshot();
  const data = nhcPaintPointsOnMap(points, {
    name: document.querySelector("#nhcStormName")?.value || "",
    initialTime: document.querySelector("#nhcInitialTime")?.value || "",
    fit: options.fit !== false
  });
  if (!data) {
    if (!options.silent) showBanner("Could not build cone from the current positions.");
    return null;
  }
  const peak = Math.max(...points.map((point) => Number(point.wind) || 0));
  const peakClass = nhcStormClass(peak);
  document.querySelector("#nhcStatusBadge").textContent = options.fromSave ? "Saved" : "Generated";
  document.querySelector("#nhcSaveState").textContent =
    `${points.length} positions · thru F${String(points.at(-1).hour).padStart(3, "0")} · peak ${peakClass.short}`;
  nhcUpdateTrackStats();
  NHC_FORECAST_HOURS.forEach((hour) => nhcUpdateRowState(hour));
  return data;
}

function nhcSnapshot() {
  return { name: document.querySelector("#nhcStormName")?.value || "", advisory: document.querySelector("#nhcAdvisoryNumber")?.value || "1", type: document.querySelector("#nhcStormType")?.value, initialTime: document.querySelector("#nhcInitialTime")?.value, basin: document.querySelector("#nhcBasin")?.value, showLabels: document.querySelector("#nhcShowLabels")?.checked, points: NHC_FORECAST_HOURS.map((hour) => ({ hour, lat: document.querySelector(`[data-nhc-lat="${hour}"]`)?.value || "", lon: document.querySelector(`[data-nhc-lon="${hour}"]`)?.value || "", wind: document.querySelector(`[data-nhc-wind="${hour}"]`)?.value || "" })) };
}

let nhcForecastCache = [];

function nhcSavedForecasts() {
  return nhcForecastCache;
}

async function loadNhcForecastsFromBackend(options = {}) {
  const response = await fetch("/api/nhc/forecasts", {
    credentials: "same-origin",
    cache: "no-store"
  });
  if (response.status === 401) {
    throw new Error("Sign in to load saved NHC forecasts");
  }
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const payload = await response.json().catch(() => ({}));
  const backend = Array.isArray(payload.forecasts) ? payload.forecasts : [];
  // Shared desk is server-only — no browser migrate path.
  nhcForecastCache = backend;
  renderNhcSavedForecasts();
  return nhcForecastCache;
}

function nhcApplySnapshot(saved) {
  if (!saved) return;
  document.querySelector("#nhcStormName").value = saved.name || "";
  document.querySelector("#nhcAdvisoryNumber").value = saved.advisory || 1;
  document.querySelector("#nhcStormType").value = saved.type || "Tropical Storm";
  if (saved.initialTime) document.querySelector("#nhcInitialTime").value = saved.initialTime;
  document.querySelector("#nhcBasin").value = saved.basin || "atlantic";
  document.querySelector("#nhcShowLabels").checked = saved.showLabels !== false;
  NHC_FORECAST_HOURS.forEach((hour) => {
    const point = (saved.points || []).find((item) => Number(item.hour) === hour) || {};
    const latInput = document.querySelector(`[data-nhc-lat="${hour}"]`);
    const lonInput = document.querySelector(`[data-nhc-lon="${hour}"]`);
    const windInput = document.querySelector(`[data-nhc-wind="${hour}"]`);
    if (latInput) latInput.value = point.lat ?? "";
    if (lonInput) lonInput.value = point.lon ?? "";
    if (windInput) windInput.value = point.wind ?? "";
    nhcUpdateRowState(hour);
  });
  nhcUpdateTrackStats();
}

function renderNhcSavedForecasts() {
  const host = document.querySelector("#nhcSavedList");
  if (!host) return;
  const forecasts = nhcSavedForecasts();
  host.innerHTML = forecasts.length ? forecasts.map((forecast) => {
    const populated = (forecast.points || []).filter((point) => point.lat !== "" && point.lon !== "");
    const through = populated.length ? Math.max(...populated.map((point) => Number(point.hour) || 0)) : 0;
    const winds = populated.map((point) => Number(point.wind) || 0);
    const peak = winds.length ? Math.max(...winds) : 0;
    const peakClass = nhcStormClass(peak);
    const savedTime = forecast.savedAt
      ? new Date(forecast.savedAt).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })
      : "Saved";
    const by = forecast.savedBy || forecast.createdBy || "";
    return `<article class="nhc-saved-card">
      <button type="button" class="nhc-saved-main" data-nhc-load="${escapeHtml(forecast.id)}">
        <strong>${escapeHtml(forecast.name || "Unnamed storm")}</strong>
        <span>${escapeHtml(forecast.type || "Tropical cyclone")} · Adv ${escapeHtml(String(forecast.advisory || 1))} · ${escapeHtml(peakClass.short)}</span>
        <small>Thru F${String(through).padStart(3, "0")} · ${escapeHtml(savedTime)}${by ? ` · ${escapeHtml(by)}` : ""}</small>
      </button>
      <button type="button" class="nhc-saved-delete" data-nhc-delete="${escapeHtml(forecast.id)}" aria-label="Delete ${escapeHtml(forecast.name || "forecast")}">×</button>
    </article>`;
  }).join("") : '<p class="hint">No shared forecasts yet. Generate a cone, then Save — all ops users will see it.</p>';
}

function initializeNhcForecastTool() {
  const table = document.querySelector("#nhcForecastTable");
  if (!table) return;
  table.innerHTML = nhcForecastRows();
  const now = new Date();
  now.setUTCMinutes(0, 0, 0);
  const initialTime = document.querySelector("#nhcInitialTime");
  if (initialTime) initialTime.value = now.toISOString().slice(0, 16);

  if (nhcEditorDraft) {
    try {
      nhcApplySnapshot(nhcEditorDraft);
      const restoreCone = () => nhcGenerateForecast({ fit: false, silent: true });
      if (map?.loaded()) restoreCone();
      else map?.once("load", restoreCone);
      document.querySelector("#nhcStatusBadge").textContent = "Draft";
    } catch { /* ignore invalid in-session draft */ }
  }

  NHC_FORECAST_HOURS.forEach((hour) => nhcUpdateRowState(hour));
  nhcUpdateTrackStats();

  table.addEventListener("input", (event) => {
    const hour = event.target?.dataset?.nhcLat ?? event.target?.dataset?.nhcLon ?? event.target?.dataset?.nhcWind;
    if (hour == null) return;
    nhcUpdateRowState(Number(hour));
    nhcUpdateTrackStats();
    nhcScheduleAutoGenerate();
  });
  document.querySelector("#nhcStormName")?.addEventListener("input", nhcUpdateTrackStats);
  document.querySelector("#nhcBasin")?.addEventListener("change", () => nhcScheduleAutoGenerate());

  document.querySelector("#nhcGenerateButton")?.addEventListener("click", () => nhcGenerateForecast());
  document.querySelector("#nhcShowLabels")?.addEventListener("change", () => nhcGenerateForecast({ fit: false, silent: true }));

  document.querySelector("#nhcSaveButton")?.addEventListener("click", async () => {
    const snapshot = nhcSnapshot();
    const validPoints = snapshot.points.filter((point) => point.lat !== "" && point.lon !== "");
    if (!snapshot.name.trim()) return showBanner("Enter a storm name before saving the forecast.");
    if (validPoints.length < 2) return showBanner("Enter OBS and at least one forecast position before saving.");
    const existing = nhcForecastCache.find(
      (item) => item.name.toLowerCase() === snapshot.name.toLowerCase() && String(item.advisory) === String(snapshot.advisory)
    );
    try {
      const response = await fetch("/api/nhc/forecasts", {
        method: "PUT",
        credentials: "same-origin",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...snapshot, id: existing?.id })
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.detail || payload.error || `HTTP ${response.status}`);
      nhcForecastCache = payload.forecasts || [];
      nhcEditorDraft = snapshot;
      nhcGenerateForecast({ fit: false, fromSave: true, silent: true });
      renderNhcSavedForecasts();
      document.querySelector("#nhcStatusBadge").textContent = "Saved";
      document.querySelector("#nhcSaveState").textContent = `Saved ${new Date().toISOString().slice(11, 16)}Z · ${validPoints.length} positions`;
      showBanner(`${snapshot.name} advisory ${snapshot.advisory} saved to the shared tropical desk.`);
      nhcUpdateTrackStats();
    } catch (error) {
      document.querySelector("#nhcStatusBadge").textContent = "Error";
      showBanner(`NHC forecast was not saved: ${error.message}`);
    }
  });

  document.querySelector("#nhcClearButton")?.addEventListener("click", () => {
    table.querySelectorAll("input").forEach((input) => { input.value = ""; });
    const name = document.querySelector("#nhcStormName");
    if (name) name.value = "";
    const advisory = document.querySelector("#nhcAdvisoryNumber");
    if (advisory) advisory.value = "1";
    nhcEditorDraft = null;
    activePanelMaps().forEach((targetMap) => targetMap.getSource("nhc-forecast")?.setData(NHC_EMPTY));
    updateNhcLegendVisibility(false);
    scheduleLayerStackApply();
    renderLayerControls();
    NHC_FORECAST_HOURS.forEach((hour) => nhcUpdateRowState(hour));
    document.querySelector("#nhcStatusBadge").textContent = "New";
    document.querySelector("#nhcSaveState").textContent = "Add OBS + one forecast hour, then generate.";
    nhcUpdateTrackStats();
  });

  document.querySelector("#nhcSavedList")?.addEventListener("click", async (event) => {
    const loadButton = event.target.closest("[data-nhc-load]");
    const deleteButton = event.target.closest("[data-nhc-delete]");
    if (loadButton) {
      const saved = nhcSavedForecasts().find((item) => item.id === loadButton.dataset.nhcLoad);
      if (saved) {
        nhcApplySnapshot(saved);
        nhcGenerateForecast({ fit: true, silent: true });
        document.querySelector("#nhcStatusBadge").textContent = "Loaded";
        document.querySelector("#nhcSaveState").textContent = `Loaded ${saved.name || "forecast"} · Adv ${saved.advisory || 1}`;
        nhcUpdateTrackStats();
      }
    } else if (deleteButton) {
      try {
        const response = await fetch(`/api/nhc/forecasts?id=${encodeURIComponent(deleteButton.dataset.nhcDelete)}`, { method: "DELETE" });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        nhcForecastCache = (await response.json()).forecasts || [];
        renderNhcSavedForecasts();
        showBanner("Forecast deleted.");
      } catch (error) {
        showBanner(`Could not delete NHC forecast: ${error.message}`);
      }
    }
  });

  renderNhcSavedForecasts();
  loadNhcForecastsFromBackend().catch((error) => showBanner(`Saved NHC forecasts unavailable: ${error.message}`));
  loadNhcGuidanceCatalog().catch((error) => showBanner(`NHC guidance catalog unavailable: ${error.message}`));
  loadNhcOfficialCatalog().catch((error) => showBanner(`Official NHC catalog unavailable: ${error.message}`));
  window.setInterval(() => {
    if (nhcGuidanceEnabled && nhcGuidanceStorm) loadNhcGuidance().catch((error) => console.warn("NHC guidance refresh failed", error));
    loadNhcOfficialCatalog().catch((error) => console.warn("Official NHC refresh failed", error));
  }, 5 * 60_000);
}

function initializeSystemWarning() {
  const dialog = document.querySelector("#systemWarningDialog");
  const continueButton = document.querySelector("#systemWarningContinue");
  if (!dialog || !continueButton) return;

  dialog.addEventListener("cancel", (event) => event.preventDefault());
  continueButton.addEventListener("click", async () => {
    continueButton.disabled = true;
    try {
      const response = await fetch("/api/access/acknowledge", { method: "POST", credentials: "same-origin" });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
    } catch (error) {
      console.warn("Access acknowledgement could not be recorded:", error);
    }
    dialog.close();
  });
  dialog.showModal();
  continueButton.focus();
}

function initializeAccessActivityAudit() {
  const startedAt = Date.now();
  const pageSessionId = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const clientContext = {
    page: `${window.location.pathname}${window.location.search}`.slice(0, 500),
    pageSessionId,
    language: navigator.language || "",
    platform: navigator.userAgentData?.platform || navigator.platform || "",
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "",
    screen: `${window.screen.width}x${window.screen.height}@${window.devicePixelRatio || 1}`
  };

  const sendActivity = (event, extra = {}, beacon = false) => {
    const payload = JSON.stringify({
      event,
      ...clientContext,
      durationSeconds: Math.round((Date.now() - startedAt) / 1000),
      ...extra
    });
    if (beacon && navigator.sendBeacon) {
      navigator.sendBeacon("/api/access/activity", new Blob([payload], { type: "application/json" }));
      return;
    }
    fetch("/api/access/activity", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: payload,
      keepalive: true
    }).catch((error) => console.warn("Activity audit could not be recorded:", error));
  };

  sendActivity("page-view");
  document.addEventListener("click", (event) => {
    const toolButton = event.target.closest("[data-panel-target]");
    if (toolButton) sendActivity("tool-open", { tool: toolButton.dataset.panelTarget || toolButton.title || "unknown" });
  });
  window.setInterval(() => {
    if (document.visibilityState === "visible") sendActivity("heartbeat");
  }, 60_000);
  window.addEventListener("pagehide", () => sendActivity("page-exit", {}, true));
}

function initializeHiveBetaDeferredTools() {
  let modelsReady = false;
  let nhcReady = false;
  const startModels = () => {
    if (modelsReady) return;
    modelsReady = true;
    initializeOpsModels();
  };
  const startNhc = () => {
    if (nhcReady) return;
    nhcReady = true;
    initializeNhcForecastTool();
  };
  document.querySelector('[data-panel-target="modelsPanel"]')?.addEventListener("pointerdown", startModels, { once: true });
  document.querySelector('[data-panel-target="nhcPanel"]')?.addEventListener("pointerdown", startNhc, { once: true });
  const startWhenIdle = () => {
    startModels();
    startNhc();
  };
  if (typeof window.requestIdleCallback === "function") {
    window.requestIdleCallback(startWhenIdle, { timeout: 4000 });
  } else {
    window.setTimeout(startWhenIdle, 2500);
  }
}

function initializeHiveBetaTimelineTray() {
  const chrome = document.querySelector("#radarChrome");
  if (!chrome || chrome.querySelector(".beta-timeline-toolbar")) return;
  const timelines = [
    ["radar", "Radar", "#radarTimeline"],
    ["model", "Model", "#modelMapTimeline"],
    ["satellite", "Satellite", "#satTimeline"],
    ["forecast", "Forecast", "#ndfdTimeline"],
    ["smoke", "Smoke", "#smokeTimeline"],
    ["qpf", "QPF", "#qpfTimeline"]
  ].map(([key, label, selector]) => ({ key, label, element: document.querySelector(selector) })).filter((item) => item.element);
  const toolbar = document.createElement("div");
  toolbar.className = "beta-timeline-toolbar";
  toolbar.innerHTML = `<div class="beta-timeline-tabs" role="tablist" aria-label="Active data timelines"></div><label class="beta-timeline-speed" title="Animation speed for radar, satellite, and models"><span>Speed</span><select aria-label="Unified animation speed"><option value="1400">Slow</option><option value="850" selected>Normal</option><option value="500">Fast</option><option value="320">Max</option></select></label><button type="button" class="beta-timeline-detail" aria-pressed="false" title="Show detailed timeline controls">•••</button><button type="button" class="beta-timeline-collapse" aria-expanded="true" title="Minimize timeline">⌄</button>`;
  chrome.prepend(toolbar);
  const tabHost = toolbar.querySelector(".beta-timeline-tabs");
  const collapseButton = toolbar.querySelector(".beta-timeline-collapse");
  const detailButton = toolbar.querySelector(".beta-timeline-detail");
  const speedSelect = toolbar.querySelector(".beta-timeline-speed select");
  const savedDensity = localStorage.getItem("hive-beta-timeline-density");
  const compact = savedDensity !== "expanded";
  chrome.classList.toggle("is-beta-compact", compact);
  document.body.classList.toggle("beta-timeline-compact", compact);
  detailButton.setAttribute("aria-pressed", String(!compact));
  detailButton.title = compact ? "Show detailed timeline controls" : "Use compact timeline";
  const isVisible = ({ element }) => element.classList.contains("is-visible") && !element.hidden;
  const select = (key) => {
    if (!timelines.some((item) => item.key === key && isVisible(item))) return;
    chrome.dataset.betaActiveTimeline = key;
    tabHost.querySelectorAll("button").forEach((button) => {
      const selected = button.dataset.timelineKey === key;
      button.classList.toggle("is-active", selected);
      button.setAttribute("aria-selected", String(selected));
      button.tabIndex = selected ? 0 : -1;
    });
  };
  const sync = () => {
    const visible = timelines.filter(isVisible);
    tabHost.innerHTML = visible.map(({ key, label, element }) => `<button type="button" role="tab" data-timeline-key="${key}" aria-controls="${element.id}">${label}</button>`).join("");
    const selected = visible.some((item) => item.key === chrome.dataset.betaActiveTimeline)
      ? chrome.dataset.betaActiveTimeline
      : visible[0]?.key;
    if (selected) select(selected);
    chrome.classList.toggle("has-multiple-timelines", visible.length > 1);
  };
  tabHost.addEventListener("click", (event) => {
    const button = event.target.closest("[data-timeline-key]");
    if (button) select(button.dataset.timelineKey);
  });
  speedSelect.addEventListener("change", () => {
    hiveBetaAnimationSpeedMs = Number(speedSelect.value) || 850;
    applySatAnimationSpeed(hiveBetaAnimationSpeedMs);
    if (radarLoopPlaying) setRadarLoopPlaying(true);
  });
  detailButton.addEventListener("click", () => {
    const nextCompact = !chrome.classList.contains("is-beta-compact");
    chrome.classList.toggle("is-beta-compact", nextCompact);
    document.body.classList.toggle("beta-timeline-compact", nextCompact);
    detailButton.setAttribute("aria-pressed", String(!nextCompact));
    detailButton.title = nextCompact ? "Show detailed timeline controls" : "Use compact timeline";
    localStorage.setItem("hive-beta-timeline-density", nextCompact ? "compact" : "expanded");
  });
  collapseButton.addEventListener("click", () => {
    const collapsed = chrome.classList.toggle("is-beta-collapsed");
    document.body.classList.toggle("beta-timeline-collapsed", collapsed);
    collapseButton.textContent = collapsed ? "⌃" : "⌄";
    collapseButton.title = collapsed ? "Expand timeline" : "Minimize timeline";
    collapseButton.setAttribute("aria-expanded", String(!collapsed));
    localStorage.setItem("hive-beta-timeline-minimized", collapsed ? "1" : "0");
  });
  const observer = new MutationObserver(sync);
  timelines.forEach(({ element }) => observer.observe(element, { attributes: true, attributeFilter: ["class", "hidden"] }));
  if (localStorage.getItem("hive-beta-timeline-minimized") === "1") collapseButton.click();
  sync();
}

function initializeHiveBetaReadinessStatus() {
  const footer = document.querySelector("#opsStatusStrip");
  const system = document.querySelector("#opsSystemStatus");
  if (!footer || footer.querySelector("#opsFeedReadiness")) return;
  const item = document.createElement("span");
  item.className = "ops-status-item beta-feed-readiness";
  item.id = "opsFeedReadiness";
  item.tabIndex = 0;
  item.setAttribute("role", "button");
  item.dataset.footerPanel = "dataPanel";
  item.title = "Open live feed readiness";
  item.innerHTML = "<small>Feeds</small><b>Checking…</b>";
  footer.insertBefore(item, system);
  const storageItem = document.createElement("span");
  storageItem.className = "ops-status-item beta-storage-readiness";
  storageItem.id = "opsStorageStatus";
  storageItem.tabIndex = 0;
  storageItem.setAttribute("role", "button");
  storageItem.dataset.footerPanel = "dataPanel";
  storageItem.innerHTML = "<small>Storage</small><b>Checking…</b>";
  footer.insertBefore(storageItem, system);
  const memoryItem = document.createElement("span");
  memoryItem.className = "ops-status-item beta-browser-memory";
  memoryItem.id = "opsBrowserMemoryStatus";
  memoryItem.tabIndex = 0;
  memoryItem.setAttribute("role", "button");
  memoryItem.dataset.footerPanel = "dataPanel";
  memoryItem.innerHTML = "<small>Browser Mem</small><b>Checking…</b>";
  footer.insertBefore(memoryItem, system);
  let lastRadarRecoveryAt = 0;
  let lastSatelliteRecoveryAt = 0;
  let lastModelRecoveryAt = 0;
  let lastStorageCheckAt = 0;
  let storageBand = "normal";
  const update = () => {
    const browserMemory = performance.memory;
    if (browserMemory?.usedJSHeapSize) {
      const usedMiB = browserMemory.usedJSHeapSize / 1024 ** 2;
      const limitMiB = browserMemory.jsHeapSizeLimit / 1024 ** 2;
      const percent = limitMiB ? usedMiB / limitMiB * 100 : 0;
      memoryItem.querySelector("b").textContent = `${Math.round(usedMiB)} MB`;
      memoryItem.title = `Browser JavaScript heap ${Math.round(usedMiB)} MB of ${Math.round(limitMiB)} MB (${percent.toFixed(1)}%). Includes decoded radar gate and mesh data retained by Hive.`;
      memoryItem.classList.toggle("is-degraded", percent >= 70);
    } else {
      memoryItem.querySelector("b").textContent = "Unavailable";
      memoryItem.title = "This browser does not expose live JavaScript heap usage.";
    }
    const newestRadar = Math.max(...radarLoopFrames.map((frame) => Number(frame.timestampMs)).filter(Number.isFinite));
    const newestSat = Math.max(...satLoopFrames.map((frame) => Number(frame.time)).filter(Number.isFinite));
    const radarAge = Number.isFinite(newestRadar) ? Math.max(0, Math.round((Date.now() - newestRadar) / 60_000)) : null;
    const satAge = Number.isFinite(newestSat) ? Math.max(0, Math.round((Date.now() - newestSat) / 60_000)) : null;
    const modelFreshness = document.querySelector("#opsModelFreshness")?.textContent?.trim() || "Idle";
    const warningPush = document.body.classList.contains("warning-stream-online");
    const radarText = radarAge == null ? "R—" : `R${radarAge}m`;
    const satText = activeSatelliteLayer === "none" ? "S off" : satAge == null ? "S…" : `S${satAge}m`;
    const radarDegraded = radarAge != null && radarAge > 15;
    const satelliteDegraded = satAge != null && satAge > 20;
    const radarFailed = countFramesByStatus("error");
    const satelliteFailed = satLoopFrames.filter((frame) => frame.status === "error").length;
    const model = opsModelWorkspaceController?.status?.();
    const modelFailed = Number(model?.failed || 0);
    const degradedFeeds = [radarDegraded ? "RADAR" : "", satelliteDegraded ? "SAT" : "", !warningPush ? "WARN PUSH" : ""].filter(Boolean);
    item.querySelector("b").textContent = degradedFeeds.length
      ? `DEGRADED ${degradedFeeds.join("+")} · retrying`
      : `${radarText} · ${satText} · W live`;
    item.title = `Radar ${radarAge == null ? "not loaded" : `${radarAge} minutes old`}; Satellite ${activeSatelliteLayer === "none" ? "off" : satAge == null ? "loading" : `${satAge} minutes old via ${satelliteActiveProvider}`}; Models ${modelFreshness}; Warnings ${warningPush ? "real-time" : "polling fallback"}`;
    item.classList.toggle("is-alert", degradedFeeds.length > 0);
    const now = Date.now();
    if (now - lastStorageCheckAt >= 30_000) {
      lastStorageCheckAt = now;
      void fetch("/api/system/health", { cache: "no-store" }).then((response) => response.ok ? response.json() : null).then((health) => {
        const percent = Number(health?.server?.disk?.percent);
        if (!Number.isFinite(percent)) return;
        const nextBand = percent >= 85 ? "critical" : percent >= 75 ? "warning" : "normal";
        storageItem.querySelector("b").textContent = `${percent.toFixed(0)}%${nextBand === "critical" ? " · CLEANING" : ""}`;
        storageItem.title = nextBand === "critical" ? `Storage ${percent.toFixed(1)}% used · accelerated intermediate cleanup active` : `Storage ${percent.toFixed(1)}% used`;
        storageItem.classList.toggle("is-warning", nextBand === "warning");
        storageItem.classList.toggle("is-critical", nextBand === "critical");
        if (nextBand !== storageBand) {
          if (nextBand === "warning") showBanner(`Storage is ${percent.toFixed(0)}% full. Model cache cleanup is monitoring capacity.`);
          else if (nextBand === "critical") showBanner(`Storage is ${percent.toFixed(0)}% full. Accelerated intermediate cleanup is active; live operations remain available.`);
          else if (storageBand !== "normal") showBanner(`Storage recovered to ${percent.toFixed(0)}% used.`);
          storageBand = nextBand;
        }
      }).catch(() => {});
    }
    if ((radarDegraded || radarFailed) && radarLayerEnabled && !radarLoopRefreshing && now - lastRadarRecoveryAt > 30_000) {
      lastRadarRecoveryAt = now;
      void refreshRadarLoop({ silent: true });
    }
    if ((satelliteDegraded || satelliteFailed) && activeSatelliteLayer !== "none" && !satLoopRefreshing && now - lastSatelliteRecoveryAt > 45_000) {
      lastSatelliteRecoveryAt = now;
      void refreshSatellitePanels();
    }
    if (modelFailed && model?.enabled && now - lastModelRecoveryAt > 60_000) {
      lastModelRecoveryAt = now;
      void opsModelWorkspaceController?.retry?.();
    }
    updateHiveBetaWorkspaceHealthBadges();
  };
  update();
  window.setInterval(update, 5_000);
}

function initializeHiveBetaDataOverview() {
  const panel = document.querySelector("#dataPanel");
  if (!panel || panel.querySelector("#betaDataOverview")) return;
  const section = document.createElement("section");
  section.className = "ops-section beta-data-overview";
  section.id = "betaDataOverview";
  section.innerHTML = `<header class="ops-section-head"><div><h3>Operational data</h3><p>Current workspace · live recovery controls</p></div></header><div class="ops-section-body"><div class="beta-data-feed-grid" id="betaDataFeedGrid"></div><div class="beta-navigation-summary" id="betaNavigationSummary"></div><div class="beta-model-prewarm" id="betaModelPrewarm"><small>Model prewarm</small><span>Loading worker status…</span></div><div class="beta-model-retention" id="betaModelRetention"><small>Retained model runs</small><span>Loading inventory…</span></div><div class="beta-cache-summary" id="betaCacheSummary"></div></div>`;
  const header = panel.querySelector(":scope > .panel-header");
  header?.after(section);
  const grid = section.querySelector("#betaDataFeedGrid");
  const cacheSummary = section.querySelector("#betaCacheSummary");
  const navigationSummary = section.querySelector("#betaNavigationSummary");
  const retentionSummary = section.querySelector("#betaModelRetention");
  const prewarmSummary = section.querySelector("#betaModelPrewarm");
  let prewarmStatus = null;
  const shortFrameLabel = (label) => {
    const [source, run, product, region, hour] = String(label || "").split(":");
    if (!source) return "Waiting for next frame";
    return `${source.toUpperCase()} · ${product || "frame"} · ${region || "national"} · ${hour || ""}`;
  };
  const renderPrewarm = () => {
    if (!prewarmStatus) return;
    const status = prewarmStatus;
    const batchTotal = Math.max(0, Number(status.batchTotal) || Math.min(120, Number(status.total) || 0));
    const processed = Math.max(0, Number(status.processed) || 0);
    const progress = batchTotal ? Math.min(100, processed / batchTotal * 100) : 100;
    const failed = Number(status.failed) || 0;
    const state = failed ? "degraded" : status.running ? "running" : Number(status.queued) ? "waiting" : "ready";
    const breakdown = status.breakdown || {};
    const breakdownGroup = (title, values, limit = 6) => `<span><strong>${title}</strong><em>${Object.entries(values || {}).sort((a, b) => b[1] - a[1]).slice(0, limit).map(([key, value]) => `${escapeHtml(key)} ${Number(value).toLocaleString()}`).join(" · ") || "None"}</em></span>`;
    const updated = status.updatedAt ? Math.max(0, Math.round((Date.now() - Date.parse(status.updatedAt)) / 1000)) : null;
    prewarmSummary.className = `beta-model-prewarm is-${state}`;
    prewarmSummary.innerHTML = `<header><div><small>Model prewarm · ${escapeHtml(breakdown.phase || "idle")}</small><b>${status.running ? "WORKING" : Number(status.queued) ? "BETWEEN PASSES" : "READY"}</b></div><time>${updated == null ? "No status" : `${updated}s ago`}</time></header><div class="beta-prewarm-progress"><i style="width:${progress.toFixed(1)}%"></i></div><div class="beta-prewarm-metrics"><span><small>Pass</small><strong>${processed}/${batchTotal}</strong></span><span><small>Queue</small><strong>${Number(status.queued || 0).toLocaleString()}</strong></span><span><small>Rate</small><strong>${Number(status.framesPerMinute || 0).toFixed(1)}/m</strong></span><span><small>Cooldown</small><strong>${Number(status.cooldowns || 0)}</strong></span></div><p title="${escapeHtml(status.current || "")}">${status.current ? `Now · ${escapeHtml(shortFrameLabel(status.current))}` : status.lastSuccess ? `Last · ${escapeHtml(shortFrameLabel(status.lastSuccess.label))}` : "Waiting for the next pass"}</p>${failed || Number(status.deferred) ? `<div class="beta-prewarm-alert">${failed ? `${failed} failed this pass` : ""}${failed && Number(status.deferred) ? " · " : ""}${Number(status.deferred) ? `${Number(status.deferred)} deferred by cooldown` : ""}</div>` : ""}<details><summary>Queue breakdown</summary><div>${breakdownGroup("Sources", breakdown.sources, 4)}${breakdownGroup("Products", breakdown.products)}${breakdownGroup("Regions", breakdown.regions)}</div>${status.lastFailure ? `<p class="beta-prewarm-failure" title="${escapeHtml(status.lastFailure.error || "")}">Last failure · ${escapeHtml(shortFrameLabel(status.lastFailure.label))}</p>` : ""}</details>`;
  };
  const refreshPrewarm = () => fetch("/api/system/model-prewarm", { cache: "no-store" })
    .then((response) => response.ok ? response.json() : Promise.reject(new Error("prewarm unavailable")))
    .then((status) => { prewarmStatus = status; renderPrewarm(); })
    .catch(() => { prewarmSummary.innerHTML = `<small>Model prewarm</small><span>Worker status temporarily unavailable</span>`; });
  let retentionInventory = null;
  const compactBytes = (bytes) => {
    const value = Number(bytes) || 0;
    return value >= 1024 ** 3 ? `${(value / 1024 ** 3).toFixed(1)} GB` : `${Math.round(value / 1024 ** 2)} MB`;
  };
  const renderRetention = () => {
    if (!retentionInventory) return;
    const sources = retentionInventory.sources || {};
    const groups = [
      ["HRRR", sources.hrrr || []],
      ["GFS", sources.gfs || []],
      ["WRF", sources.wrf || []]
    ];
    retentionSummary.innerHTML = `<header><small>Retained model runs · newest 3</small><b>${compactBytes(retentionInventory.totalBytes)}</b></header><div>${groups.map(([label, runs]) => `<span><strong>${label}</strong><em>${runs.length ? runs.map((run) => `${run.domain ? `${run.domain} ` : ""}${String(run.run).replace(/^(\d{8})(\d{2})$/, "$1 $2Z")} · ${compactBytes(run.bytes)}`).join("<br>") : "Awaiting inventory"}</em></span>`).join("")}</div>`;
  };
  const refreshRetention = () => fetch("/api/system/model-retention", { cache: "no-store" })
    .then((response) => response.ok ? response.json() : Promise.reject(new Error("retention unavailable")))
    .then((inventory) => { retentionInventory = inventory; renderRetention(); })
    .catch(() => { retentionSummary.innerHTML = `<small>Retained model runs</small><span>Inventory temporarily unavailable</span>`; });
  const ageLabel = (stamp) => {
    const value = Number(stamp);
    if (!Number.isFinite(value)) return "Not loaded";
    const minutes = Math.max(0, Math.round((Date.now() - value) / 60_000));
    return minutes < 1 ? "Current" : `${minutes} min old`;
  };
  const render = () => {
    const radarReady = getReadyFrameIndexes().length;
    const radarFailed = countFramesByStatus("error");
    const newestRadar = Math.max(...radarLoopFrames.map((frame) => Number(frame.timestampMs)).filter(Number.isFinite));
    const satReady = getReadySatFrameIndexes().length;
    const satFailed = satLoopFrames.filter((frame) => frame.status === "error").length;
    const newestSat = Math.max(...satLoopFrames.map((frame) => Number(frame.time)).filter(Number.isFinite));
    const model = opsModelWorkspaceController?.status?.() || { enabled: false, ready: 0, total: 0, failed: 0, label: "Models", freshness: "Idle" };
    const warningLive = document.body.classList.contains("warning-stream-online");
    const feeds = [
      { key: "radar", label: "Radar", state: radarLoopRefreshing ? "Loading" : radarFailed ? "Degraded" : radarReady ? "Ready" : "Idle", detail: `${radarReady}/${radarLoopFrames.length} frames · ${ageLabel(newestRadar)}`, failed: radarFailed },
      { key: "satellite", label: "Satellite", state: satLoopLoading || satLoopRefreshing ? "Loading" : satFailed ? "Degraded" : satReady ? "Ready" : activeSatelliteLayer === "none" ? "Off" : "Idle", detail: `${satReady}/${satLoopFrames.length} frames · ${ageLabel(newestSat)}`, failed: satFailed },
      { key: "model", label: "Models", state: model.failed ? "Degraded" : model.enabled && model.ready ? "Ready" : model.enabled ? "Loading" : "Off", detail: model.enabled ? `${model.ready}/${model.total} frames · ${model.freshness}` : "No model overlay", failed: model.failed },
      { key: "warnings", label: "Warnings", state: warningLive ? "Live" : "Polling", detail: warningLive ? "Real-time stream connected" : "Polling fallback active", failed: warningLive ? 0 : 1 }
    ];
    grid.innerHTML = feeds.map((feed) => `<article class="beta-data-feed is-${feed.state.toLowerCase()}"><span class="beta-data-feed-dot"></span><div><strong>${feed.label}</strong><small>${escapeHtml(feed.detail)}</small>${feed.failed ? `<em>${feed.failed} failed</em>` : ""}</div><b>${feed.state}</b><button type="button" data-beta-feed-retry="${feed.key}">Retry</button></article>`).join("");
    const stats = hiveBetaPerformance.cacheStats;
    const navigation = hiveBetaPerformance.navigation;
    const recentLongTasks = hiveBetaPerformance.longTasks.filter((entry) => Date.now() - entry.at < 60_000);
    const initializedMaps = [map, map2, map3, map4].filter(Boolean);
    const suspendedMaps = initializedMaps.filter((targetMap) => targetMap.__zncaveRenderSuspended).length;
    const fpsState = navigation.fps >= 50 ? "smooth" : navigation.fps >= 35 ? "fair" : navigation.fps > 0 ? "slow" : "idle";
    navigationSummary.className = `beta-navigation-summary is-${fpsState}`;
    navigationSummary.innerHTML = `<span><small>Navigation FPS</small><strong>${navigation.fps ? navigation.fps.toFixed(1) : "Move map"}</strong></span><span><small>Long tasks · 60s</small><strong>${recentLongTasks.length}</strong></span><span><small>Rendering panes</small><strong>${initializedMaps.length - suspendedMaps}/${initializedMaps.length}</strong></span>`;
    cacheSummary.textContent = `Cache · radar ${hiveBetaRadarProductJobs.size} · model ${hiveBetaModelBlobCache.size} · satellite ${hiveBetaSatelliteBlobCache.size} · persistent hits ${stats.persistentHits}`;
  };
  section.addEventListener("click", (event) => {
    const button = event.target.closest("[data-beta-feed-retry]");
    if (!button) return;
    button.disabled = true;
    button.textContent = "Retrying…";
    const jobs = {
      radar: () => refreshRadarLoop({ silent: false }),
      satellite: () => refreshSatellitePanels(),
      model: () => opsModelWorkspaceController?.retry?.(),
      warnings: () => restartHiveBetaWarningStream()
    };
    Promise.resolve(jobs[button.dataset.betaFeedRetry]?.()).catch((error) => showBanner(`Retry failed: ${error.message || error}`)).finally(() => {
      button.disabled = false;
      button.textContent = "Retry";
      render();
    });
  });
  render();
  void refreshPrewarm();
  void refreshRetention();
  window.setInterval(render, 5_000);
  window.setInterval(refreshPrewarm, 5_000);
  window.setInterval(refreshRetention, 30_000);
}

function initializeHiveBetaMapContext() {
  const footer = document.querySelector("#opsStatusStrip");
  if (!footer || footer.querySelector("#betaMapContext")) return;
  const context = document.createElement("span");
  context.className = "beta-map-context";
  context.id = "betaMapContext";
  context.tabIndex = 0;
  context.setAttribute("role", "button");
  context.title = "Shortcuts: Alt+1–8 workspaces · Alt+R/S/M/H/D/L panels · Alt+Shift+←/→ map panels · Alt+Shift+1–5 warning stages";
  footer.querySelector("#opsModeStatus")?.after(context);
  ["#opsCwaStatus", "#opsRadarStatus", "#opsSatStatus"].forEach((selector) => document.querySelector(selector)?.closest(".ops-status-item")?.classList.add("beta-context-replaced"));
  const showShortcuts = () => showBanner("Shortcuts · Alt+1–8 workspaces · Alt+R radar · Alt+S satellite · Alt+M models · Alt+H warnings · Alt+D data · Alt+L layers · Alt+Shift+←/→ panels · Alt+Shift+1–5 warning stages");
  context.addEventListener("click", showShortcuts);
  context.addEventListener("keydown", (event) => {
    if (["Enter", " "].includes(event.key)) { event.preventDefault(); showShortcuts(); }
  });
  const update = () => {
    const panelIndex = Math.max(0, activePanelIndex - 1);
    const products = [panelLayoutCount < 2 ? activeRadarProductId : panel1ProductId, panel2ProductId, panel3ProductId, panel4ProductId];
    const sites = panelSiteIds || [];
    const productId = products[panelIndex] || activeRadarProductId;
    const productLabel = radarProductDefinitions[productId]?.shortLabel || radarProductDefinitions[productId]?.label || productId;
    const newestRadar = Math.max(...radarLoopFrames.map((frame) => Number(frame.timestampMs)).filter(Number.isFinite));
    const radarAge = Number.isFinite(newestRadar) ? `${Math.max(0, Math.round((Date.now() - newestRadar) / 60_000))}m` : "—";
    const satellite = activeSatelliteLayer === "none" ? "SAT OFF" : activeSatelliteLayer === "native"
      ? nativeGoesSettings.product === "geocolor" ? "SAT GC" : `SAT B${String(nativeGoesSettings.band).padStart(2, "0")}`
      : `SAT ${String(activeSatelliteLayer).toUpperCase()}`;
    const model = opsModelWorkspaceController?.status?.();
    const modelText = model?.enabled ? `MODEL ${model.ready}/${model.total}` : "MODEL OFF";
    context.innerHTML = `<b>P${activePanelIndex}</b><span>${escapeHtml(activeWfo || "—")}</span><span>${escapeHtml(sites[panelIndex] || radarLoopSite || "NO RADAR")} · ${escapeHtml(productLabel)} · ${radarAge}</span><span>${escapeHtml(satellite)}</span><span>${escapeHtml(modelText)}</span><kbd>⌥?</kbd>`;
  };
  update();
  window.setInterval(update, 2_000);
}

function initializeHiveBetaKeyboardOperations() {
  document.addEventListener("keydown", (event) => {
    if (!hiveBetaMode || !event.altKey || event.ctrlKey || event.metaKey) return;
    if (/INPUT|TEXTAREA|SELECT/.test(event.target?.tagName || "") || event.target?.isContentEditable) return;
    const key = event.key.toLowerCase();
    if (event.shiftKey && /^[1-5]$/.test(key) && !document.querySelector("#hazEditorView")?.hidden) {
      event.preventDefault();
      event.stopImmediatePropagation();
      const stages = ["validity", "geometry", "details", "locations", "review"];
      setHiveBetaHazardStage(stages[Number(key) - 1], { scroll: true });
      return;
    }
    if (event.shiftKey && ["arrowleft", "arrowright"].includes(key)) {
      event.preventDefault();
      event.stopImmediatePropagation();
      if (panelLayoutCount < 2) return;
      const direction = key === "arrowleft" ? -1 : 1;
      const count = panelLayoutCount >= 4 ? 4 : 2;
      selectMapPanel(((activePanelIndex - 1 + direction + count) % count) + 1, { silent: true });
      return;
    }
    if (!event.shiftKey && /^[1-8]$/.test(key)) {
      const workspace = operationalWorkspaces[Number(key) - 1];
      if (workspace) {
        event.preventDefault();
        event.stopImmediatePropagation();
        void switchOperationalWorkspace(workspace.id);
      }
      return;
    }
    const panels = { r: "radarPanel", s: "satellitePanel", m: "modelsPanel", h: "hazardsPanel", d: "dataPanel", l: "layersPanel" };
    if (!event.shiftKey && panels[key]) {
      event.preventDefault();
      event.stopImmediatePropagation();
      openToolPanel(panels[key]);
    }
  }, { capture: true });
}

const hiveBetaPopoutWindows = new Map();

function openHiveBetaPanelPopout(panelId, label) {
  if (!hiveBetaMode || !["radarPanel", "dataPanel"].includes(panelId)) return;
  if (panelId === "radarPanel") return openHiveBetaMapPopout();
  const existing = hiveBetaPopoutWindows.get(panelId);
  if (existing?.popup && !existing.popup.closed) return existing.popup.focus();
  const popup = window.open("", `zncave-${panelId}`, "popup=yes,width=430,height=820,resizable=yes,scrollbars=yes");
  if (!popup) return showBanner("Pop-out blocked. Allow pop-ups for Hive Beta and try again.");
  const sourcePanel = document.getElementById(panelId);
  if (!sourcePanel) { popup.close(); return; }
  popup.document.open();
  popup.document.write(`<!doctype html><html data-theme="${escapeHtml(document.documentElement.dataset.theme || "light")}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(label)} · Hive Beta</title><link rel="stylesheet" href="/styles.css?v=20260810-hive-beta45-no-scrollbars"></head><body class="hive-beta popout-panel-body"><header class="popout-panel-header"><div><small>HIVE BETA · LIVE REMOTE</small><strong>${escapeHtml(label)}</strong></div><button type="button" id="popoutClose">×</button></header><main class="panel-dock popout-panel-dock"><div id="popoutPanelHost"></div></main></body></html>`);
  popup.document.close();
  const host = popup.document.getElementById("popoutPanelHost");
  const clone = sourcePanel.cloneNode(true);
  clone.classList.add("is-active");
  clone.querySelectorAll("[data-beta-popout]").forEach((button) => button.remove());
  host.append(clone);
  const findSource = (target) => {
    if (target.id) return document.getElementById(target.id);
    for (const attribute of ["data-beta-radar-product", "data-beta-feed-retry"]) {
      if (target.hasAttribute?.(attribute)) return sourcePanel.querySelector(`[${attribute}="${CSS.escape(target.getAttribute(attribute))}"]`);
    }
    if (target.classList?.contains("beta-radar-all-products")) return sourcePanel.querySelector(".beta-radar-all-products");
    return null;
  };
  popup.document.addEventListener("click", (event) => {
    if (event.target.closest("#popoutClose")) return popup.close();
    const button = event.target.closest("button");
    if (!button) return;
    const source = findSource(button);
    if (source) { event.preventDefault(); source.click(); }
  });
  ["input", "change"].forEach((type) => popup.document.addEventListener(type, (event) => {
    const source = findSource(event.target);
    if (!source || !("value" in source)) return;
    source.value = event.target.value;
    if ("checked" in source) source.checked = event.target.checked;
    source.dispatchEvent(new Event(type, { bubbles: true }));
  }));
  const sync = () => {
    if (popup.closed) return;
    popup.document.documentElement.dataset.theme = document.documentElement.dataset.theme || "light";
    clone.querySelectorAll("[id]").forEach((copy) => {
      const source = document.getElementById(copy.id);
      if (!source) return;
      copy.hidden = source.hidden;
      copy.className = source.className;
      if ("disabled" in copy) copy.disabled = source.disabled;
      if (/INPUT|SELECT|TEXTAREA/.test(copy.tagName)) {
        if (popup.document.activeElement !== copy) copy.value = source.value;
        if ("checked" in copy) copy.checked = source.checked;
      } else if (["betaDataFeedGrid", "betaNavigationSummary", "betaModelPrewarm", "betaModelRetention", "betaCacheSummary", "serverHealthSummary", "feedHealthList", "radarSummary", "radarPanelContext"].includes(copy.id)) {
        copy.innerHTML = source.innerHTML;
      } else if (!copy.children.length && copy.textContent !== source.textContent) {
        copy.textContent = source.textContent;
      }
    });
    clone.querySelectorAll("[data-beta-radar-product]").forEach((copy) => {
      const source = sourcePanel.querySelector(`[data-beta-radar-product="${CSS.escape(copy.dataset.betaRadarProduct)}"]`);
      if (source) copy.className = source.className;
    });
  };
  const timer = window.setInterval(sync, 750);
  const cleanup = () => {
    window.clearInterval(timer);
    hiveBetaPopoutWindows.delete(panelId);
    document.querySelector(`[data-beta-popout="${panelId}"]`)?.classList.remove("is-active");
  };
  popup.addEventListener("beforeunload", cleanup, { once: true });
  hiveBetaPopoutWindows.set(panelId, { popup, timer });
  document.querySelector(`[data-beta-popout="${panelId}"]`)?.classList.add("is-active");
  sync();
}

function betaMapPopoutState() {
  const targetMap = panelMap?.() || map;
  const center = targetMap?.getCenter?.();
  const panelIndex = Math.max(0, activePanelIndex - 1);
  const products = [panelLayoutCount < 2 ? activeRadarProductId : panel1ProductId, panel2ProductId, panel3ProductId, panel4ProductId];
  return {
    workspaceId: activeWorkspaceId,
    wfo: activeWfo,
    radarEnabled: panelLayoutCount < 2 ? radarLayerEnabled : Boolean(panelRadarEnabled[panelIndex]),
    radarSource: panelLayoutCount < 2 ? opsRadarSource : panelRadarSources[panelIndex] || "local",
    radarSite: panelSiteIds[panelIndex] || radarLoopSite,
    radarProduct: products[panelIndex] || activeRadarProductId,
    radarFile: radarLoopFrames[activeRadarFrameIndex]?.file || "",
    satellite: activeSatelliteLayer,
    satelliteSettings: { ...nativeGoesSettings },
    satelliteFrameTime: satLoopFrames[activeSatFrameIndex]?.time || null,
    model: opsModelWorkspaceController?.capture?.() || { enabled: false },
    layers: workspaceClone(panelLayerPreferences[panelIndex] || layerPreferences),
    view: center ? { center: [center.lng, center.lat], zoom: targetMap.getZoom(), bearing: targetMap.getBearing(), pitch: targetMap.getPitch() } : null
  };
}
window.ZNCaveBetaMapState = betaMapPopoutState;

function openHiveBetaMapPopout() {
  const existing = hiveBetaPopoutWindows.get("radarPanel");
  if (existing?.popup && !existing.popup.closed) return existing.popup.focus();
  const popup = window.open("/hive-beta?mapPopout=1", "zncave-live-map", "popup=yes,width=1100,height=780,resizable=yes,scrollbars=no");
  if (!popup) return showBanner("Second-map pop-out blocked. Allow pop-ups for Hive Beta and try again.");
  hiveBetaPopoutWindows.set("radarPanel", { popup });
  document.querySelector('[data-beta-popout="radarPanel"]')?.classList.add("is-active");
  const watch = window.setInterval(() => {
    if (!popup.closed) return;
    window.clearInterval(watch);
    hiveBetaPopoutWindows.delete("radarPanel");
    document.querySelector('[data-beta-popout="radarPanel"]')?.classList.remove("is-active");
  }, 1000);
}

function initializeHiveBetaMapPopoutMode() {
  if (!hiveBetaMapPopoutMode) return;
  document.body.classList.add("beta-map-popout-mode");
  let followMain = true;
  let viewLinked = true;
  let lastRadarSignature = "";
  let lastSatelliteSignature = "";
  let lastModelSignature = "";
  let lastLayerSignature = "";
  const chrome = document.createElement("header");
  chrome.className = "beta-map-popout-header";
  chrome.innerHTML = `<div class="beta-map-popout-title"><small>HIVE BETA · SECOND MAP</small><strong id="betaMapPopoutTitle">Waiting for main workspace…</strong></div><div class="beta-map-popout-controls"><label><input id="betaMapFollowMain" type="checkbox" checked><span>Follow main</span></label><label><input id="betaMapLinkView" type="checkbox" checked><span>Link view</span></label><input id="betaMapRadarSite" aria-label="Independent radar site" title="Radar site" maxlength="4" placeholder="Radar" disabled><select id="betaMapRadarProduct" aria-label="Independent radar product" title="Radar product" disabled><option value="reflectivitylevel3">Reflectivity</option><option value="velocitylevel3">Velocity</option><option value="correlation">Correlation</option><option value="precip1h">1h Rain</option><option value="mesh60">MESH</option></select><select id="betaMapSatellite" aria-label="Independent satellite" title="Satellite" disabled><option value="none">Satellite off</option><option value="ir">Clean IR</option><option value="water">Water vapor</option><option value="geocolor">GeoColor</option><option value="visible">Visible</option></select><select id="betaMapModel" aria-label="Independent model" title="Model" disabled><option value="none">Model off</option><option value="hrrr:refc">HRRR reflectivity</option><option value="hrrr:mucape">HRRR MUCAPE</option><option value="hrrr:gust">HRRR wind gust</option><option value="ncep:refc">WRF reflectivity</option><option value="ncep:zasSevere">WRF severe signal</option></select></div><button type="button" title="Close second map">×</button>`;
  document.body.append(chrome);
  const followToggle = chrome.querySelector("#betaMapFollowMain");
  const viewToggle = chrome.querySelector("#betaMapLinkView");
  const siteInput = chrome.querySelector("#betaMapRadarSite");
  const productSelect = chrome.querySelector("#betaMapRadarProduct");
  const satelliteSelect = chrome.querySelector("#betaMapSatellite");
  const modelSelect = chrome.querySelector("#betaMapModel");
  const independentControls = [siteInput, productSelect, satelliteSelect, modelSelect];
  followToggle.addEventListener("change", () => {
    followMain = followToggle.checked;
    independentControls.forEach((control) => { control.disabled = followMain; });
    if (followMain) lastRadarSignature = lastSatelliteSignature = lastModelSignature = lastLayerSignature = "";
    chrome.classList.toggle("is-independent", !followMain);
  });
  viewToggle.addEventListener("change", () => { viewLinked = viewToggle.checked; });
  chrome.querySelector("button").addEventListener("click", () => window.close());
  const applyRadarSelection = () => {
    if (followMain) return;
    const site = String(siteInput.value || radarLoopSite || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4);
    if (site.length === 4) {
      siteInput.value = site;
      radarLoopSite = site;
      panelSiteIds[0] = site;
      syncRadarInput(site);
    }
    setPrimaryRadarProduct(productSelect.value);
  };
  siteInput.addEventListener("keydown", (event) => { if (event.key === "Enter") applyRadarSelection(); });
  siteInput.addEventListener("change", applyRadarSelection);
  productSelect.addEventListener("change", applyRadarSelection);
  satelliteSelect.addEventListener("change", () => {
    if (followMain) return;
    const preset = satelliteSelect.value;
    if (preset === "none") return setSatelliteLayer("none", { silent: true });
    const settings = preset === "geocolor" ? { product: "geocolor", band: 13 }
      : preset === "water" ? { product: "band", band: 9 }
        : preset === "visible" ? { product: "band", band: 2 }
          : { product: "band", band: 13 };
    nativeGoesSettings = { ...nativeGoesSettings, ...settings };
    setSatelliteLayer("native", { silent: true });
  });
  modelSelect.addEventListener("change", () => {
    if (followMain) return;
    if (modelSelect.value === "none") return opsModelWorkspaceController?.clear?.();
    const [source, product] = modelSelect.value.split(":");
    if (!opsModelWorkspaceController) return showBanner("Model controls are still initializing. Try again in a moment.");
    void opsModelWorkspaceController.restore({ enabled: true, source, product, region: "", hour: 0 });
  });
  const sync = async () => {
    const source = window.opener?.ZNCaveBetaMapState?.();
    if (!source || !map?.loaded?.()) return;
    if (!siteInput.value) siteInput.value = source.radarSite || "";
    if (followMain) productSelect.value = source.radarProduct || "reflectivitylevel3";
    chrome.querySelector("strong").textContent = `${source.wfo} · ${source.radarSite || "No radar"} · ${radarProductDefinitions[source.radarProduct]?.label || source.radarProduct}`;
    if (!followMain) {
      chrome.querySelector("strong").textContent = `Independent · ${radarLoopSite || "No radar"} · ${radarProductDefinitions[activeRadarProductId]?.label || activeRadarProductId}`;
      if (viewLinked && source.view) map.jumpTo(source.view);
      return;
    }
    const radarSignature = JSON.stringify([source.workspaceId, source.wfo, source.radarEnabled, source.radarSource, source.radarSite, source.radarProduct]);
    const satelliteSignature = JSON.stringify([source.workspaceId, source.satellite, source.satelliteSettings]);
    const modelSignature = JSON.stringify([source.workspaceId, source.model]);
    const layerSignature = JSON.stringify([source.workspaceId, source.layers]);
    if (layerSignature !== lastLayerSignature) {
      lastLayerSignature = layerSignature;
      layerPreferences = normalizePreferences(workspaceClone(source.layers || layerPreferences));
      panelLayerPreferences[0] = layerPreferences;
      applyLayerPreferences();
    }
    if (radarSignature !== lastRadarSignature) {
      lastRadarSignature = radarSignature;
      if (activeWfo !== source.wfo) setActiveWfo(source.wfo, { radar: source.radarSite, fit: false, animate: false, skipRadar: true, quiet: true });
      if (source.radarEnabled) {
        radarLoopSite = source.radarSite;
        panelSiteIds[0] = source.radarSite;
        syncRadarInput(source.radarSite);
        if (source.radarSource !== opsRadarSource) setOpsRadarSource(source.radarSource || "local", { skipLoad: true, fit: false });
        if (source.radarSource === "local") setPrimaryRadarProduct(source.radarProduct);
        else setOpsRadarSource(source.radarSource, { fit: false });
      } else if (radarLayerEnabled) {
        stopSiteRadarLoop("second-map source disabled");
      }
    }
    if (satelliteSignature !== lastSatelliteSignature) {
      lastSatelliteSignature = satelliteSignature;
      nativeGoesSettings = { ...nativeGoesSettings, ...(source.satelliteSettings || {}) };
      setSatelliteLayer(source.satellite || "none", { silent: true });
    }
    if (modelSignature !== lastModelSignature && (!source.model?.enabled || opsModelWorkspaceController)) {
      lastModelSignature = modelSignature;
      if (source.model?.enabled) void opsModelWorkspaceController?.restore?.(source.model);
      else opsModelWorkspaceController?.clear?.();
    }
    if (source.radarFile) {
      const index = radarLoopFrames.findIndex((frame) => frame.file === source.radarFile && frame.status === "ready");
      if (index >= 0 && index !== activeRadarFrameIndex) void showRadarLoopFrame(index, { userAction: true, force: true });
    }
    if (source.satelliteFrameTime) {
      const index = satLoopFrames.findIndex((frame) => Math.abs(Number(frame.time) - Number(source.satelliteFrameTime)) < 10_000 && frame.status === "ready");
      if (index >= 0 && index !== activeSatFrameIndex) showSatelliteLoopFrame(index, { exact: true, force: true });
    }
    if (viewLinked && source.view) map.jumpTo(source.view);
  };
  mapReady.then(async () => {
    await setPanelLayout(1, { skipRadar: true, quiet: true });
    window.setInterval(() => void sync(), 750);
    void sync();
  });
}

function initializeHiveBetaPanelPopouts() {
  const targets = [
    ["radarPanel", "Radar", document.querySelector("#betaRadarQuickPick .ops-section-head")],
    ["dataPanel", "Data Status", document.querySelector("#dataPanel .panel-header")]
  ];
  targets.forEach(([panelId, label, host]) => {
    if (!host || host.querySelector(`[data-beta-popout="${panelId}"]`)) return;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "compact-button beta-popout-button";
    button.dataset.betaPopout = panelId;
    button.title = `Open ${label} on another monitor`;
    button.textContent = "Pop out ↗";
    button.addEventListener("click", () => openHiveBetaPanelPopout(panelId, label));
    host.append(button);
  });
}

function initializeHiveBetaSatellitePanel() {
  const panel = document.querySelector("#satellitePanel");
  const nativeSection = document.querySelector("#satNativeSection");
  if (!panel || panel.querySelector("#betaSatelliteQuickPick")) return;
  const legacyProductSection = panel.firstElementChild;
  legacyProductSection?.classList.add("beta-satellite-legacy");
  controls.satLoadButton?.closest(".ops-section")?.classList.add("beta-satellite-legacy");
  const section = document.createElement("section");
  section.className = "ops-section beta-satellite-quick";
  section.id = "betaSatelliteQuickPick";
  section.innerHTML = `
    <header class="ops-section-head"><div><h3>Operational imagery</h3><p>NOAA AWS primary · automatic fallback</p></div></header>
    <div class="ops-section-body">
      <div class="beta-sat-presets" role="radiogroup" aria-label="Satellite imagery purpose">
        <button type="button" data-beta-sat-preset="geocolor"><strong>GeoColor</strong><small>Clouds and surface · day/night</small></button>
        <button type="button" data-beta-sat-preset="ir" class="is-recommended"><strong>Clean IR</strong><small>Storm tops · best for severe ops</small><i>Recommended</i></button>
        <button type="button" data-beta-sat-preset="water"><strong>Water vapor</strong><small>Mid-level moisture and waves</small></button>
        <button type="button" data-beta-sat-preset="visible"><strong>Visible</strong><small>Highest detail during daylight</small></button>
        <button type="button" data-beta-sat-preset="fire"><strong>Fire / fog</strong><small>Hot spots and low clouds</small></button>
      </div>
      <div class="field-grid beta-sat-simple-settings">
        <label class="field"><span>Satellite</span><select id="betaSatCoverage"><option value="auto" selected>Automatic · based on map</option><option value="east">GOES-19 East</option><option value="west">GOES-18 West</option></select></label>
        <label class="field"><span>View</span><select id="betaSatView"><option value="conus" selected>Regional US</option><option value="full">Full disk</option><option value="m1">Meso 1 · 1-minute</option><option value="m2">Meso 2 · 1-minute</option></select></label>
      </div>
      <label class="width-label beta-sat-opacity"><span>Satellite opacity <strong id="betaSatOpacityValue">${Math.round(SAT_MAP_OPACITY * 100)}%</strong></span><input id="betaSatOpacity" type="range" min="10" max="100" step="5" value="${Math.round(SAT_MAP_OPACITY * 100)}"></label>
      <p class="beta-sat-view-note" id="betaSatViewNote" hidden>Mesoscale sectors move with active weather and may not cover your current map.</p>
      <div class="beta-sat-actions"><button type="button" class="compact-button" id="betaSatOff">Turn satellite off</button><span id="betaSatProvider">Source selected automatically</span></div>
    </div>`;
  panel.insertBefore(section, panel.firstElementChild);
  panel.classList.add("has-beta-satellite-controls");
  const presets = {
    geocolor: { product: "geocolor", band: 13, display: "full" },
    ir: { product: "band", band: 13, display: "full" },
    water: { product: "band", band: 9, display: "full" },
    visible: { product: "band", band: 2, display: "full" },
    fire: { product: "band", band: 7, display: "full" }
  };
  const coverage = section.querySelector("#betaSatCoverage");
  const view = section.querySelector("#betaSatView");
  const provider = section.querySelector("#betaSatProvider");
  const viewNote = section.querySelector("#betaSatViewNote");
  const opacity = section.querySelector("#betaSatOpacity");
  const opacityValue = section.querySelector("#betaSatOpacityValue");
  const simpleSettings = section.querySelector(".beta-sat-simple-settings");
  [document.querySelector("#satLoopDurationField"), document.querySelector("#satAnimationSpeedField")].forEach((field) => {
    if (field) simpleSettings.append(field);
  });
  const resolveSatellite = () => coverage.value === "auto"
    ? ((map?.getCenter?.().lng ?? -95) <= -105 ? "west" : "east")
    : coverage.value;
  const activePreset = () => nativeGoesSettings.product === "geocolor" ? "geocolor"
    : nativeGoesSettings.band === 2 ? "visible"
      : nativeGoesSettings.band === 7 ? "fire"
        : nativeGoesSettings.band === 9 || nativeGoesSettings.band === 10 ? "water" : "ir";
  const sync = () => {
    section.querySelectorAll("[data-beta-sat-preset]").forEach((button) => button.classList.toggle("is-active", activeSatelliteLayer === "native" && button.dataset.betaSatPreset === activePreset()));
    view.value = nativeGoesSettings.sector || "conus";
    viewNote.hidden = !["m1", "m2"].includes(view.value);
    const readyFrames = getReadySatFrameIndexes().length;
    const frameSpan = readyFrames > 1 ? Math.max(1, Math.round((Number(satLoopFrames.at(-1)?.time) - Number(satLoopFrames[0]?.time)) / 60_000)) : 0;
    provider.textContent = activeSatelliteLayer === "none" ? "Satellite off" : `${satelliteActiveProvider === "off" ? "Selecting source" : satelliteActiveProvider} · ${nativeGoesSettings.satellite === "west" ? "GOES-West" : "GOES-East"}${readyFrames ? ` · ${readyFrames} frames / ${frameSpan}m` : ""}`;
  };
  section.addEventListener("click", (event) => {
    const button = event.target.closest("[data-beta-sat-preset]");
    if (button) {
      const preset = presets[button.dataset.betaSatPreset];
      nativeGoesSettings = { ...nativeGoesSettings, ...preset, satellite: resolveSatellite(), sector: view.value || "conus" };
      controls.satProductSelect.value = "native";
      setSatelliteLayer("native");
      sync();
      return;
    }
    if (event.target.closest("#betaSatOff")) {
      controls.satProductSelect.value = "none";
      setSatelliteLayer("none");
      sync();
    }
  });
  [coverage, view].forEach((select) => select.addEventListener("change", () => {
    nativeGoesSettings.satellite = resolveSatellite();
    nativeGoesSettings.sector = view.value;
    nativeGoesSettings.display = "full";
    if (activeSatelliteLayer === "native") setSatelliteLayer("native");
    sync();
  }));
  opacity.addEventListener("input", () => {
    SAT_MAP_OPACITY = Math.max(0.1, Math.min(1, Number(opacity.value) / 100));
    opacityValue.textContent = `${Math.round(SAT_MAP_OPACITY * 100)}%`;
    activePanelMaps().forEach((targetMap) => {
      ["ops-sat-loop-layer", "ops-satellite-layer", ...(targetMap.__zncaveAnimatedSatelliteLayerIds || [])].forEach((id) => {
        if (targetMap.getLayer(id)) targetMap.setPaintProperty(id, "raster-opacity", SAT_MAP_OPACITY);
      });
    });
  });
  opacity.addEventListener("change", () => { savePreferences(); renderLayerControls(); });
  window.setInterval(sync, 5_000);
  if (nativeSection) nativeSection.dataset.betaAdvanced = "true";
  sync();
}

function syncHiveBetaRadarPresets() {
  if (!hiveBetaMode) return;
  document.querySelectorAll("[data-beta-radar-product]").forEach((button) => {
    const active = button.dataset.betaRadarProduct === activeRadarProductId;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));
  });
}

function initializeHiveBetaRadarPanel() {
  const panel = document.querySelector("#radarPanel");
  if (!panel || panel.querySelector("#betaRadarQuickPick")) return;
  const section = document.createElement("section");
  section.className = "ops-section beta-radar-quick";
  section.id = "betaRadarQuickPick";
  section.innerHTML = `
    <header class="ops-section-head"><div><h3>Quick products</h3><p>Applies to the selected map panel</p></div></header>
    <div class="ops-section-body">
      <div class="beta-radar-presets" role="group" aria-label="Operational radar product presets">
        <button type="button" data-beta-radar-product="reflectivitylevel3"><strong>Reflectivity</strong><small>Storm structure</small></button>
        <button type="button" data-beta-radar-product="velocitylevel3"><strong>Velocity</strong><small>Base velocity</small></button>
        <button type="button" data-beta-radar-product="correlation"><strong>Correlation</strong><small>Dual-pol debris</small></button>
        <button type="button" data-beta-radar-product="precip1h"><strong>1-hour rain</strong><small>Recent accumulation</small></button>
        <button type="button" data-beta-radar-product="mesh60"><strong>Hail track</strong><small>MRMS 60-minute MESH</small></button>
      </div>
      <button type="button" class="compact-button beta-radar-all-products">Choose from all products</button>
    </div>`;
  const firstSection = panel.querySelector(":scope > .ops-section");
  panel.insertBefore(section, firstSection || panel.firstChild);
  section.addEventListener("click", (event) => {
    const preset = event.target.closest("[data-beta-radar-product]");
    if (preset) {
      setPrimaryRadarProduct(preset.dataset.betaRadarProduct);
      syncHiveBetaRadarPresets();
      return;
    }
    if (event.target.closest(".beta-radar-all-products")) {
      controls.radarProductSelect?.focus();
      if (typeof controls.radarProductSelect?.showPicker === "function") {
        try { controls.radarProductSelect.showPicker(); } catch { /* browser may require a different picker gesture */ }
      }
    }
  });
  controls.radarProductSelect?.addEventListener("change", syncHiveBetaRadarPresets);
  if (controls.radarPanelContext) {
    new MutationObserver(syncHiveBetaRadarPresets).observe(controls.radarPanelContext, { childList: true, characterData: true, subtree: true });
  }
  syncHiveBetaRadarPresets();
}

initializeSystemWarning();
initializeAccessActivityAudit();
if (hiveBetaMode) {
  initializeHiveBetaWarningStream();
  initializeHiveBetaTimelineTray();
  initializeHiveBetaReadinessStatus();
  initializeHiveBetaDataOverview();
  initializeHiveBetaMapContext();
  initializeHiveBetaKeyboardOperations();
  initializeHiveBetaRadarPanel();
  initializeHiveBetaSatellitePanel();
  initializeHiveBetaPanelPopouts();
  initializeHiveBetaMapPopoutMode();
  initializeHiveBetaDeferredTools();
}
else initializeNhcForecastTool();

boot().catch((error) => {
  console.error("[boot] failed", error);
  // Still try to paint identity so the rail is not stuck on "?" / "…"
  loadSession().catch(() => applySessionToUi());
});
